INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92247, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "论文是研究一件事以后，写出来的长文章。", "primary_collocate": null, "pronunciation": "lùn wén", "ipa": "lwən˥˩ wən˧˥", "syllable_count": 2, "sentences": [{"text": "毕业前，每个学生都要交一篇论文。", "target_word": "论文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我写论文写了三个月。", "target_word": "论文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的论文有三十页。", "target_word": "论文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我的论文太长了。", "target_word": "论文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨晚熬夜写论文，今天很累。", "target_word": "论文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写论文以前，我先查了很多资料。", "target_word": "论文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "论文写完以后，他请朋友帮忙看看。", "target_word": "论文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个星期我要把论文改好。", "target_word": "论文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的论文题目是中国茶文化。", "target_word": "论文", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "论文要在六月前交给老师。", "target_word": "论文", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "篇", "label": "量词"}, {"form": "学术论文", "label": "复合"}, {"form": "毕业论文", "label": "复合"}, {"form": "論文", "label": "繁体"}], "register": "中性", "sense_fingerprint": "研究一件事后写出的长文章", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f447c5a2-140b-433d-8f46-2a9e5f4c3fee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92247, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "论文", "is_correct": true, "explanation": "正确：“交论文”是毕业前的常见要求，“一篇”指一篇长文章。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“篇”只用于文章，不能说“交一篇石头”。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：“梦想”不能被“交”，与“毕业前交”的学业要求不符。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：“海洋”不能交给老师，与“毕业前交”矛盾。"}], "explanations": {"论文": "正确：“交论文”是毕业前的常见要求，“一篇”指一篇长文章。", "石头": "搭配：“篇”只用于文章，不能说“交一篇石头”。", "梦想": "语义：“梦想”不能被“交”，与“毕业前交”的学业要求不符。", "海洋": "语义：“海洋”不能交给老师，与“毕业前交”矛盾。"}, "sentence_index": 0, "correct_answer": "论文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他写了一篇论文，表达对母亲的感情。", "explanation": "这里应该用〈诗〉。“论文”指研究一件事后写出的长文章，不是用来抒发感情的。"}, {"text": "妈妈在厨房煎论文，香味飘了出来。", "explanation": "这里应该用〈饼〉。“论文”是研究一件事后写出的长文章，不能用“煎”来做。"}, {"text": "妈妈唱了一篇论文，哄我睡觉。", "explanation": "这里应该用〈歌〉。“论文”是研究一件事后写出的长文章，不能用“唱”来表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92247, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "论文", "is_correct": true, "explanation": "正确：“论文写完”指研究文章写成，“请朋友帮忙看看”也是为了检查文章。"}, {"text": "面条", "is_correct": false, "explanation": "搭配：“写完”的对象不能是“面条”，与“写完以后”搭配不当。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“房间”不能被“写完”，说“房间写完以后”不成立。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：“小猫”不能被写，与“请朋友帮忙看看”的文字内容矛盾。"}], "explanations": {"论文": "正确：“论文写完”指研究文章写成，“请朋友帮忙看看”也是为了检查文章。", "面条": "搭配：“写完”的对象不能是“面条”，与“写完以后”搭配不当。", "房间": "搭配：“房间”不能被“写完”，说“房间写完以后”不成立。", "小猫": "语义：“小猫”不能被写，与“请朋友帮忙看看”的文字内容矛盾。"}, "sentence_index": 6, "correct_answer": "论文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的论文坏了，要拿去修。", "explanation": "这里应该用〈手机〉。“论文”是研究一件事后写出的长文章，不是可以修理的机器。"}, {"text": "她穿上论文，很好看。", "explanation": "这里应该用〈衣服〉。“论文”是长文章，不能用“穿”来搭配。"}, {"text": "妈妈炒了一盘论文，香味很好。", "explanation": "这里应该用〈青菜〉。“论文”是研究性文章，不能用来炒着吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92247, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我用了三个月才写完这只论文。", "corrected_sentence": "我用了三个月才写完这篇论文。", "error_description": "“论文”的量词应为“篇”，“只”只用于动物，不能用于论文。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92247, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班交了两个篇论文。", "corrected_sentence": "我们班交了两篇论文。", "error_description": "量词重复：“两”后已用“篇”，不能再加“个”，应说“两篇论文”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
