INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92281, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "高看是觉得一个人比别人想的更好。", "primary_collocate": null, "pronunciation": "gāo kàn", "ipa": "kɑʊ˥ kʰan˥˩", "syllable_count": 2, "sentences": [{"text": "大家都高看他了，其实他没那么厉害。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你太高看我了，我只是个普通人。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别人都夸他能干，但我觉得你太高看他了。", "target_word": "高看", "complexity_tier": "T3", "furigana": "bié rén dōu kuā tā néng gàn, dàn wǒ juéde nǐ tài gāo kàn tā le.", "sentence_source": "generated"}, {"text": "我没有高看自己，只是想试试。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的能力其实一般，你别高看她。", "target_word": "高看", "complexity_tier": "T3", "furigana": "tā de nénglì qíshí yìbān, nǐ bié gāo kàn tā.", "sentence_source": "generated"}, {"text": "这个人没什么特别的，别高看他。", "target_word": "高看", "complexity_tier": "T3", "furigana": "zhè ge rén méi shénme tèbié de, bié gāo kàn tā.", "sentence_source": "generated"}, {"text": "他总高看新同事，觉得他们都很能干。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你这么说是高看我了，我做不到。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我以前真是高看他了，其实他很一般。", "target_word": "高看", "complexity_tier": "T3", "furigana": "wǒ yǐqián zhēn shì gāo kàn tā le, qíshí tā hěn yìbān.", "sentence_source": "generated"}, {"text": "朋友们都高看他，觉得他样样都行。", "target_word": "高看", "complexity_tier": "T3", "furigana": "péngyǒumen dōu gāo kàn tā, juéde tā yàngyàng dōu xíng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "高看了", "label": "体标"}, {"form": "高看过", "label": "体标"}], "register": "口语", "sense_fingerprint": "把某人估计得比实际或一般看法更好、更有能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f447c5a2-140b-433d-8f46-2a9e5f4c3fee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92281, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高看", "is_correct": true, "explanation": "正确：高看，把人估计得比实际更好。"}, {"text": "高亢", "is_correct": false, "explanation": "亢（kàng）与看（kàn）韵尾不同，ng 与 n 的区别，意思是声音高而洪亮，与本词无关。"}, {"text": "高干", "is_correct": false, "explanation": "干（gàn）与看（kàn）声母不同，g 与 k 的区别，意思是高级干部。"}, {"text": "高坎", "is_correct": false, "explanation": "坎（kǎn）与看（kàn）声调不同，第三声与第四声的区别，意思是较高的台阶或斜坡。"}, {"text": "高慢", "is_correct": false, "explanation": "慢（màn）与看（kàn）声母不同，m 与 k 的区别，意思是傲慢、目中无人。"}], "explanations": {"高看": "正确：高看，把人估计得比实际更好。", "高亢": "亢（kàng）与看（kàn）韵尾不同，ng 与 n 的区别，意思是声音高而洪亮，与本词无关。", "高干": "干（gàn）与看（kàn）声母不同，g 与 k 的区别，意思是高级干部。", "高坎": "坎（kǎn）与看（kàn）声调不同，第三声与第四声的区别，意思是较高的台阶或斜坡。", "高慢": "慢（màn）与看（kàn）声母不同，m 与 k 的区别，意思是傲慢、目中无人。"}, "sentence_index": null, "correct_answer": "高看"}, "level_3": {"options": [{"text": "高看", "is_correct": true, "explanation": "正确：“高看”是把人估计得比实际更好，与后句“其实他没那么厉害”相照应。"}, {"text": "小看", "is_correct": false, "explanation": "语义：“小看”是看轻、低估，与“其实他没那么厉害”所说的评价方向相反，句意矛盾。"}, {"text": "低估", "is_correct": false, "explanation": "语义：“低估”是估计得比实际低，与后句“其实他没那么厉害”的转折不合，句意矛盾。"}, {"text": "鄙视", "is_correct": false, "explanation": "语域：“鄙视”语气强烈、偏书面，含轻蔑之意，与口语化的“大家都……了，其实……”不协调。"}], "explanations": {"高看": "正确：“高看”是把人估计得比实际更好，与后句“其实他没那么厉害”相照应。", "小看": "语义：“小看”是看轻、低估，与“其实他没那么厉害”所说的评价方向相反，句意矛盾。", "低估": "语义：“低估”是估计得比实际低，与后句“其实他没那么厉害”的转折不合，句意矛盾。", "鄙视": "语域：“鄙视”语气强烈、偏书面，含轻蔑之意，与口语化的“大家都……了，其实……”不协调。"}, "sentence_index": 0, "correct_answer": "高看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他高看那个陌生人，却觉得他一无是处。", "explanation": "这里应该用〈小看〉。高看与后句“一无是处”矛盾。"}, {"text": "他站在山顶，高看远处的村庄。", "explanation": "这里应该用〈俯瞰〉。高看是对人的能力作估计，不表示居高临下地看景物。"}, {"text": "他站在窗前，高看那片天空，半天没动。", "explanation": "这里应该用〈仰望〉。高看是对人的评价，不表示抬头看景物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92281, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高看", "is_correct": true, "explanation": "正确：“高看”是把人估计得比实际更好，与后句“觉得他们都很能干”照应。"}, {"text": "瞧不起", "is_correct": false, "explanation": "语义：“瞧不起”是看不起、轻视，与后句“觉得他们都很能干”的评价正相反，句意矛盾。"}, {"text": "轻慢", "is_correct": false, "explanation": "语域：“轻慢”偏书面、语气重，与口语化的“他总……，觉得……”不协调，且表示怠慢，与后句的认可矛盾。"}, {"text": "歧视", "is_correct": false, "explanation": "语义：“歧视”指因偏见而区别对待，与后句“觉得他们都很能干”的认可相矛盾。"}], "explanations": {"高看": "正确：“高看”是把人估计得比实际更好，与后句“觉得他们都很能干”照应。", "瞧不起": "语义：“瞧不起”是看不起、轻视，与后句“觉得他们都很能干”的评价正相反，句意矛盾。", "轻慢": "语域：“轻慢”偏书面、语气重，与口语化的“他总……，觉得……”不协调，且表示怠慢，与后句的认可矛盾。", "歧视": "语义：“歧视”指因偏见而区别对待，与后句“觉得他们都很能干”的认可相矛盾。"}, "sentence_index": 6, "correct_answer": "高看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师高看那几个调皮的学生，却总说他们不行。", "explanation": "这里应该用〈小看〉。高看与后句“总说他们不行”矛盾。"}, {"text": "他踮起脚，高看了一下墙的高度。", "explanation": "这里应该用〈量〉。高看是对人的评价，不表示测量高度。"}, {"text": "朋友们在山下抬头高看天上的飞机。", "explanation": "这里应该用〈仰望〉。高看是对人的评价，不表示抬头看飞机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92281, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我没高看了他的能力，其实他并不行。", "corrected_sentence": "我没高看他的能力，其实他并不行。", "error_description": "错误：“没”否定时不用“了”，应说“我没高看他的能力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92281, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板没高看了这位新人，也没给他机会。", "corrected_sentence": "老板没高看这位新人，也没给他机会。", "error_description": "错误：否定句中“没”之后多加了“了”，应去掉。正确形式为“没高看”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
