INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92282, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看重；对人或事物给予较高的评价。", "primary_collocate": null, "pronunciation": "gāo kàn", "ipa": "kɑʊ˥ kʰan˥˩", "syllable_count": 2, "sentences": [{"text": "公司很高看有经验的工人。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师特别高看爱读书的学生。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很高看这份工作，每天都认真做。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都高看她的才华。", "target_word": "高看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "中国人高看诚实的人。", "target_word": "高看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他很高看这次机会，准备了一个月。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板高看你，所以才让你负责这件事。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里人都高看读书人。", "target_word": "高看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我最高看那些爱帮助别人的人。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从不高看有钱人，只看人品。", "target_word": "高看", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "高看了", "label": "体标"}, {"form": "高看过", "label": "体标"}], "register": "口语", "sense_fingerprint": "看重某类人或某件事，给予较高评价", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f447c5a2-140b-433d-8f46-2a9e5f4c3fee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92282, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高看", "is_correct": true, "explanation": "正确：高看，看重某人或某事，给予较高评价。"}, {"text": "高亢", "is_correct": false, "explanation": "亢（kàng）与看（kàn）韵尾不同，ng 与 n 的区别，意思是声音高而洪亮，与本词无关。"}, {"text": "高干", "is_correct": false, "explanation": "干（gàn）与看（kàn）声母不同，g 与 k 的区别，意思是高级干部。"}, {"text": "高坎", "is_correct": false, "explanation": "坎（kǎn）与看（kàn）声调不同，第三声与第四声的区别，意思是较高的台阶或斜坡。"}, {"text": "高慢", "is_correct": false, "explanation": "慢（màn）与看（kàn）声母不同，m 与 k 的区别，意思是傲慢、目中无人。"}], "explanations": {"高看": "正确：高看，看重某人或某事，给予较高评价。", "高亢": "亢（kàng）与看（kàn）韵尾不同，ng 与 n 的区别，意思是声音高而洪亮，与本词无关。", "高干": "干（gàn）与看（kàn）声母不同，g 与 k 的区别，意思是高级干部。", "高坎": "坎（kǎn）与看（kàn）声调不同，第三声与第四声的区别，意思是较高的台阶或斜坡。", "高慢": "慢（màn）与看（kàn）声母不同，m 与 k 的区别，意思是傲慢、目中无人。"}, "sentence_index": null, "correct_answer": "高看"}, "level_3": {"options": [{"text": "高看", "is_correct": true, "explanation": "正确：“高看”是看重、给予较高评价，与“有经验的工人”的价值相符。"}, {"text": "招待", "is_correct": false, "explanation": "搭配：“招待”多用于接待客人，不说招待有经验的工人。"}, {"text": "供养", "is_correct": false, "explanation": "搭配：“供养”指赡养、养活家人，不用于公司对员工的态度。"}, {"text": "怀疑", "is_correct": false, "explanation": "语义：“怀疑”是不相信、存疑，与“有经验的工人”所体现的能力相矛盾，且与高看的评价方向相反。"}], "explanations": {"高看": "正确：“高看”是看重、给予较高评价，与“有经验的工人”的价值相符。", "招待": "搭配：“招待”多用于接待客人，不说招待有经验的工人。", "供养": "搭配：“供养”指赡养、养活家人，不用于公司对员工的态度。", "怀疑": "语义：“怀疑”是不相信、存疑，与“有经验的工人”所体现的能力相矛盾，且与高看的评价方向相反。"}, "sentence_index": 0, "correct_answer": "高看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店高看这件商品，却说它一文不值。", "explanation": "这里应该用〈小看〉。高看与后句“一文不值”矛盾。"}, {"text": "我们高看那个新来的司机，却总觉得他不会开车。", "explanation": "这里应该用〈小看〉。高看与后句“总觉得他不会开车”矛盾。"}, {"text": "他站在桥上，高看河里的船。", "explanation": "这里应该用〈俯瞰〉。高看是对人或事的评价，不表示居高看景物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92282, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高看", "is_correct": true, "explanation": "正确：“高看”是看重、给予较高评价，与“所以才让你负责这件事”的器重相照应。"}, {"text": "怠慢", "is_correct": false, "explanation": "语义：“怠慢”是冷淡、不重视，与“所以才让你负责这件事”的器重矛盾。"}, {"text": "冷落", "is_correct": false, "explanation": "语义：“冷落”是冷淡对待、不理睬，与“让你负责这件事”的信任矛盾。"}, {"text": "排斥", "is_correct": false, "explanation": "语域：“排斥”偏书面，口语中多说“排挤”；且表示拒绝接纳，与后句委以重任相矛盾。"}], "explanations": {"高看": "正确：“高看”是看重、给予较高评价，与“所以才让你负责这件事”的器重相照应。", "怠慢": "语义：“怠慢”是冷淡、不重视，与“所以才让你负责这件事”的器重矛盾。", "冷落": "语义：“冷落”是冷淡对待、不理睬，与“让你负责这件事”的信任矛盾。", "排斥": "语域：“排斥”偏书面，口语中多说“排挤”；且表示拒绝接纳，与后句委以重任相矛盾。"}, "sentence_index": 6, "correct_answer": "高看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司高看新人，却觉得他们一无是处。", "explanation": "这里应该用〈小看〉。高看与后句“一无是处”矛盾。"}, {"text": "他站在窗边，高看楼下的汽车。", "explanation": "这里应该用〈打量〉。高看表示给予较高评价，不表示观察景物。"}, {"text": "他把手放在额头上，高看远处的灯塔。", "explanation": "这里应该用〈眺望〉。高看是对人或事的评价，不表示观望远处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师很高看了这个学生的努力，经常表扬他。", "corrected_sentence": "老师很高看这个学生的努力，经常表扬他。", "error_description": "错误：副词“很”与动词后的“了”搭配不当，“了”应去掉。正确形式为“很高看”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班主任从没高看了成绩差的学生。", "corrected_sentence": "班主任从没高看过成绩差的学生。", "error_description": "错误：“从没”表示从未发生过，动词后应用“过”而不用“了”。正确形式为“从没高看过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92285, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "幸运", "is_correct": true, "explanation": "反义：“幸运”与“不幸”相对，指遭遇好事。"}, {"text": "勤奋", "is_correct": false, "explanation": "无反义关系：“勤奋”说的是努力做事，与“遭遇坏事”不是相对的状态。"}, {"text": "富裕", "is_correct": false, "explanation": "无反义关系：“富裕”说的是经济条件，与“不幸”没有相对的关系。"}, {"text": "高大", "is_correct": false, "explanation": "无反义关系：“高大”说的是体形，与“不幸”的意思无关。"}], "correct_answer": "幸运", "explanations": {"幸运": "反义：“幸运”与“不幸”相对，指遭遇好事。", "勤奋": "无反义关系：“勤奋”说的是努力做事，与“遭遇坏事”不是相对的状态。", "富裕": "无反义关系：“富裕”说的是经济条件，与“不幸”没有相对的关系。", "高大": "无反义关系：“高大”说的是体形，与“不幸”的意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92285, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "幸福", "is_correct": true, "explanation": "反义：“幸福”与“不幸”相对，指生活顺利快乐。"}, {"text": "聪明", "is_correct": false, "explanation": "无反义关系：“聪明”说的是智力，与“不幸”没有相对的关系。"}, {"text": "勤劳", "is_correct": false, "explanation": "无反义关系：“勤劳”说的是肯干，与“遭遇坏事”不是相对的状态。"}, {"text": "狭窄", "is_correct": false, "explanation": "无反义关系：“狭窄”说的是空间，与“不幸”的意思无关。"}], "correct_answer": "幸福", "explanations": {"幸福": "反义：“幸福”与“不幸”相对，指生活顺利快乐。", "聪明": "无反义关系：“聪明”说的是智力，与“不幸”没有相对的关系。", "勤劳": "无反义关系：“勤劳”说的是肯干，与“遭遇坏事”不是相对的状态。", "狭窄": "无反义关系：“狭窄”说的是空间，与“不幸”的意思无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92285, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不幸是遇到了很坏、很伤心的事。", "primary_collocate": null, "pronunciation": "bù xìng", "ipa": "pu˥˩ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他很不幸，小时候就没有了父母。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个不幸的孩子一直住在奶奶家。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她真不幸，刚买的新车就坏了。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到这个不幸的消息，大家都很难过。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位老人一生很不幸，丈夫和儿子都走了。", "target_word": "不幸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得自己是世界上最不幸的人。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们都为这个不幸的家庭担心过。", "target_word": "不幸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很不幸，工作丢了，家也没了。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那次旅行真不幸，天天下雨，还生了病。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友很不幸，妻子生病，孩子也出了事。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容人或事遇到坏事、很伤心，不幸运，可说“很不幸”“不幸的人／消息”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fda20375-ed58-4eb8-96ba-b11b06ce9777') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92285, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不幸", "is_correct": true, "explanation": "正确：“不幸”指遭遇坏事、不顺利。"}, {"text": "不行", "is_correct": false, "explanation": "bù xíng 与 bù xìng 的第二个音节声调不同（第二声与第四声），意思是“不可以”。"}, {"text": "步行", "is_correct": false, "explanation": "bù xíng 与 bù xìng 的第二个音节声调不同（第二声与第四声），意思是“走路”。"}, {"text": "不信", "is_correct": false, "explanation": "xìn 与 xìng 韵尾不同（n 与 ng），意思是“不相信”。"}, {"text": "不兴", "is_correct": false, "explanation": "xīng（第一声）与 xìng（第四声）声调不同，意思是“不流行”。"}], "explanations": {"不幸": "正确：“不幸”指遭遇坏事、不顺利。", "不行": "bù xíng 与 bù xìng 的第二个音节声调不同（第二声与第四声），意思是“不可以”。", "步行": "bù xíng 与 bù xìng 的第二个音节声调不同（第二声与第四声），意思是“走路”。", "不信": "xìn 与 xìng 韵尾不同（n 与 ng），意思是“不相信”。", "不兴": "xīng（第一声）与 xìng（第四声）声调不同，意思是“不流行”。"}, "sentence_index": null, "correct_answer": "不幸"}, "level_3": {"options": [{"text": "不幸", "is_correct": true, "explanation": "正确：“很不幸”说明他遭遇坏事，与后句“没有了父母”相符。"}, {"text": "幸福", "is_correct": false, "explanation": "语义：“很幸福”与后句“小时候就没有了父母”的经历相矛盾。"}, {"text": "快乐", "is_correct": false, "explanation": "语义：“很快乐”与后句叙述的丧亲经历不协调。"}, {"text": "幸运", "is_correct": false, "explanation": "语义：“很幸运”与后句“小时候就没有了父母”的经历相矛盾。"}], "explanations": {"不幸": "正确：“很不幸”说明他遭遇坏事，与后句“没有了父母”相符。", "幸福": "语义：“很幸福”与后句“小时候就没有了父母”的经历相矛盾。", "快乐": "语义：“很快乐”与后句叙述的丧亲经历不协调。", "幸运": "语义：“很幸运”与后句“小时候就没有了父母”的经历相矛盾。"}, "sentence_index": 0, "correct_answer": "不幸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在那场比赛中获得了不幸。", "explanation": "这里应该用〈荣誉〉。“获得”搭配荣誉、奖项等好事，“不幸”指遇到的坏事，不能被获得。"}, {"text": "今天的天气很不幸，我们只好待在家里。", "explanation": "这里应该用〈糟糕〉。“不幸”形容人或事遭遇坏事，不用来形容天气。"}, {"text": "这次考试很不幸，他得了满分。", "explanation": "这里应该用〈幸运〉。“不幸”表示遇到坏事，与“得了满分”这样的好结果矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92285, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不幸", "is_correct": true, "explanation": "正确：“这个不幸的家庭”说明家庭遭遇坏事，与“担心过”相符。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描写身材，不能用来形容一个家庭。"}, {"text": "富裕", "is_correct": false, "explanation": "语义：“富裕”说的是经济状况，与“为……担心过”的语境不符。"}, {"text": "美满", "is_correct": false, "explanation": "语义：“美满”指生活圆满，与“为……担心过”的语义相冲突。"}], "explanations": {"不幸": "正确：“这个不幸的家庭”说明家庭遭遇坏事，与“担心过”相符。", "高大": "体貌：“高大”描写身材，不能用来形容一个家庭。", "富裕": "语义：“富裕”说的是经济状况，与“为……担心过”的语境不符。", "美满": "语义：“美满”指生活圆满，与“为……担心过”的语义相冲突。"}, "sentence_index": 6, "correct_answer": "不幸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在公园玩得很不幸。", "explanation": "这里应该用〈开心〉。“不幸”指遭遇坏事，不能用来形容愉快的游玩。"}, {"text": "晚会很不幸。", "explanation": "这里应该用〈热闹〉。“不幸”说的是坏事，不能形容活动的气氛。"}, {"text": "看到孩子长大，他很不幸。", "explanation": "这里应该用〈欣慰〉。“欣慰”表示满意和安心，与“不幸”的坏事含义矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92285, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个很不幸孩子很需要帮助。", "corrected_sentence": "这个很不幸的孩子很需要帮助。", "error_description": "“很”修饰形容词、后接名词时，中间要加“的”；“很不幸孩子”应为“很不幸的孩子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92285, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位老人的晚年很很不幸。", "corrected_sentence": "那位老人的晚年很不幸。", "error_description": "程度副词“很”重复使用，“很很不幸”多了一个“很”。删去多余的一个，应为“很不幸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92286, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "幸福", "is_correct": true, "explanation": "反义：“幸福”与“不幸”相对，指快乐顺利的生活状态。"}, {"text": "办法", "is_correct": false, "explanation": "无反义关系：“办法”指解决问题的方式，与“不幸”没有相对的关系。"}, {"text": "桌子", "is_correct": false, "explanation": "无反义关系：“桌子”是家具，与“不幸”的意思无关。"}, {"text": "计划", "is_correct": false, "explanation": "无反义关系：“计划”指打算要做的事，与“不幸”没有相对的关系。"}], "correct_answer": "幸福", "explanations": {"幸福": "反义：“幸福”与“不幸”相对，指快乐顺利的生活状态。", "办法": "无反义关系：“办法”指解决问题的方式，与“不幸”没有相对的关系。", "桌子": "无反义关系：“桌子”是家具，与“不幸”的意思无关。", "计划": "无反义关系：“计划”指打算要做的事，与“不幸”没有相对的关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92286, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "幸福", "is_correct": true, "explanation": "反义：“幸福”与“不幸”相对，指快乐顺利的生活状态。"}, {"text": "收获", "is_correct": false, "explanation": "无反义关系：“收获”指所得到的成果，与“不幸”没有相对的关系。"}, {"text": "天空", "is_correct": false, "explanation": "无反义关系：“天空”指自然景象，与“不幸”的意思无关。"}, {"text": "学问", "is_correct": false, "explanation": "无反义关系：“学问”指知识和学识，与“不幸”没有相对的关系。"}], "correct_answer": "幸福", "explanations": {"幸福": "反义：“幸福”与“不幸”相对，指快乐顺利的生活状态。", "收获": "无反义关系：“收获”指所得到的成果，与“不幸”没有相对的关系。", "天空": "无反义关系：“天空”指自然景象，与“不幸”的意思无关。", "学问": "无反义关系：“学问”指知识和学识，与“不幸”没有相对的关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92286, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "遭遇不好的事情；不顺利，令人悲伤。", "primary_collocate": null, "pronunciation": "bù xìng", "ipa": "pu˥˩ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他在小时候遭遇过不幸。", "target_word": "不幸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想帮他走出不幸。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场不幸让全家人都很难过。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从不向别人说自己的不幸。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友遇到了不幸，我们应该去看看他。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不幸发生以后，他一直不说话。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一次不幸改变了他的一生。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面对不幸，她没有哭，也没有放弃。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家人的不幸，让整个村子都很伤心。", "target_word": "不幸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生活里的不幸，有时会让人变得更坚强。", "target_word": "不幸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词用法，指遭遇的灾难或坏事，常作“遭遇／遇到／面对”的宾语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fda20375-ed58-4eb8-96ba-b11b06ce9777') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92286, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不幸", "is_correct": true, "explanation": "正确：“不幸”作名词时指遭遇的坏事或灾难。"}, {"text": "不行", "is_correct": false, "explanation": "bù xíng 与 bù xìng 的第二个音节声调不同（第二声与第四声），意思是“不可以”。"}, {"text": "步行", "is_correct": false, "explanation": "bù xíng 与 bù xìng 的第二个音节声调不同（第二声与第四声），意思是“走路”。"}, {"text": "不信", "is_correct": false, "explanation": "xìn 与 xìng 韵尾不同（n 与 ng），意思是“不相信”。"}, {"text": "不兴", "is_correct": false, "explanation": "xīng（第一声）与 xìng（第四声）声调不同，意思是“不流行”。"}], "explanations": {"不幸": "正确：“不幸”作名词时指遭遇的坏事或灾难。", "不行": "bù xíng 与 bù xìng 的第二个音节声调不同（第二声与第四声），意思是“不可以”。", "步行": "bù xíng 与 bù xìng 的第二个音节声调不同（第二声与第四声），意思是“走路”。", "不信": "xìn 与 xìng 韵尾不同（n 与 ng），意思是“不相信”。", "不兴": "xīng（第一声）与 xìng（第四声）声调不同，意思是“不流行”。"}, "sentence_index": null, "correct_answer": "不幸"}, "level_3": {"options": [{"text": "不幸", "is_correct": true, "explanation": "正确：“遭遇过不幸”指小时候遇到过坏事，与句意相合。"}, {"text": "好运", "is_correct": false, "explanation": "搭配：“遭遇”多接坏事，一般不接“好运”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“遭遇”在这里指遇到的坏事，“天气”不是这一类的事件。"}, {"text": "幸福", "is_correct": false, "explanation": "语义：“遭遇过幸福”与“遭遇”所指的坏事语境不符。"}], "explanations": {"不幸": "正确：“遭遇过不幸”指小时候遇到过坏事，与句意相合。", "好运": "搭配：“遭遇”多接坏事，一般不接“好运”。", "天气": "语义：“遭遇”在这里指遇到的坏事，“天气”不是这一类的事件。", "幸福": "语义：“遭遇过幸福”与“遭遇”所指的坏事语境不符。"}, "sentence_index": 0, "correct_answer": "不幸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在小时候得到了一份不幸。", "explanation": "这里应该用〈礼物〉。“得到”搭配礼物、机会等好事，“不幸”指坏事，不能被得到。"}, {"text": "她每天都在享受不幸。", "explanation": "这里应该用〈幸福〉。“享受”搭配幸福、快乐等好事，不搭配坏事。"}, {"text": "他的不幸让全家人都很开心。", "explanation": "这里应该用〈喜悦〉。“不幸”指坏事，与“都很开心”的说法相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92286, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不幸", "is_correct": true, "explanation": "正确：“一次不幸改变了他的一生”指一件坏事带来深远影响，与句意相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是能改变一生的事件，句中说的是一次经历。"}, {"text": "星期一", "is_correct": false, "explanation": "语义：“星期一”是时间，不是能改变一生的事件。"}, {"text": "拖鞋", "is_correct": false, "explanation": "语义：“拖鞋”是日用品，不是能改变一生的事件。"}], "explanations": {"不幸": "正确：“一次不幸改变了他的一生”指一件坏事带来深远影响，与句意相合。", "颜色": "语义：“颜色”不是能改变一生的事件，句中说的是一次经历。", "星期一": "语义：“星期一”是时间，不是能改变一生的事件。", "拖鞋": "语义：“拖鞋”是日用品，不是能改变一生的事件。"}, "sentence_index": 6, "correct_answer": "不幸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他抓住了这次不幸。", "explanation": "这里应该用〈机会〉。“抓住”搭配机会、好的时机，不搭配“不幸”。"}, {"text": "我们送去了不幸。", "explanation": "这里应该用〈祝福〉。“送去”的是美好的东西，“不幸”是坏事，不能送去。"}, {"text": "我们为他的不幸庆祝了一番。", "explanation": "这里应该用〈成功〉。“庆祝”用于值得高兴的事，“不幸”不能被庆祝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一位不幸让村子里的人都很难过。", "corrected_sentence": "一场不幸让村子里的人都很难过。", "error_description": "“不幸”指事件，量词应用“场”或“次”；“位”只用于人，不能修饰“不幸”，应为“一场不幸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一次很不幸改变了我们全家的生活。", "corrected_sentence": "一次不幸改变了我们全家的生活。", "error_description": "“不幸”作名词时不能受程度副词“很”修饰；应去掉“很”，为“一次不幸改变了我们全家的生活”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
