INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92293, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "代价是为了得到一样东西，必须付出的东西。", "primary_collocate": null, "pronunciation": "dài jià", "ipa": "tai˥˩ tɕja˥˩", "syllable_count": 2, "sentences": [{"text": "想成功，就要付出代价。", "target_word": "代价", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次错误让他付出了很大的代价。", "target_word": "代价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不好好学习，将来要付出代价。", "target_word": "代价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了这份工作，他付出的代价不小。", "target_word": "代价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "懒惰的代价是考试不及格。", "target_word": "代价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她为自己的决定付出了代价。", "target_word": "代价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "成功的代价往往是时间和精力。", "target_word": "代价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你愿意为梦想付出什么代价？", "target_word": "代价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吸烟的代价是身体变差。", "target_word": "代价", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "不管代价多大，他都要去。", "target_word": "代价", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种代价", "label": "量词搭配"}], "register": "中性", "sense_fingerprint": "为得到某物而必须付出的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1214d3e9-5c7a-47b4-bed0-11150dfe4c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92293, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "代价", "is_correct": true, "explanation": "正确答案。代价（dàijià）指为得到某物而必须付出的东西。"}, {"text": "大家", "is_correct": false, "explanation": "dài 与 dà 韵母不同（ai／a），jià（第四声）与 jiā（第一声）声调也不同，意思是「大家、众人」。"}, {"text": "单价", "is_correct": false, "explanation": "dài 与 dān 韵母不同（ai／an），声调也不同（第四声与第一声），意思是「每单位的价格」。"}, {"text": "底价", "is_correct": false, "explanation": "dài 与 dǐ 韵母不同（ai／i），声调也不同（第四声与第三声），意思是「最低成交价」。"}], "explanations": {"代价": "正确答案。代价（dàijià）指为得到某物而必须付出的东西。", "大家": "dài 与 dà 韵母不同（ai／a），jià（第四声）与 jiā（第一声）声调也不同，意思是「大家、众人」。", "单价": "dài 与 dān 韵母不同（ai／an），声调也不同（第四声与第一声），意思是「每单位的价格」。", "底价": "dài 与 dǐ 韵母不同（ai／i），声调也不同（第四声与第三声），意思是「最低成交价」。"}, "sentence_index": null, "correct_answer": "代价"}, "level_3": {"options": [{"text": "代价", "is_correct": true, "explanation": "正确答案。“付出”的对象是代价，指为成功必须付出的东西。"}, {"text": "奖励", "is_correct": false, "explanation": "搭配：“付出”不与“奖励”搭配，获得奖励才说“得到”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以付出的东西，句子读不通。"}, {"text": "朋友", "is_correct": false, "explanation": "搭配：“付出”可以带“友情”，不能说“付出朋友”。"}], "explanations": {"代价": "正确答案。“付出”的对象是代价，指为成功必须付出的东西。", "奖励": "搭配：“付出”不与“奖励”搭配，获得奖励才说“得到”。", "天气": "语义：天气不是可以付出的东西，句子读不通。", "朋友": "搭配：“付出”可以带“友情”，不能说“付出朋友”。"}, "sentence_index": 0, "correct_answer": "代价"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的代价很厚。", "explanation": "这里应该用〈厚度〉。代价指付出的东西，不能用来形容物体的厚薄。"}, {"text": "这次比赛的代价是我们赢了。", "explanation": "这里应该用〈结果〉。代价指为得到某物而付出的东西，不能用来表示事情的结局，应说「比赛的结果是我们赢了」。"}, {"text": "他从这次比赛中得到了很大的代价。", "explanation": "这里应该用〈收获〉。代价是为得到某物而付出的东西，不能说「得到代价」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92293, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "代价", "is_correct": true, "explanation": "正确答案。代价（dàijià）指为得到某物而必须付出的东西。"}, {"text": "地价", "is_correct": false, "explanation": "dài 与 dì 韵母不同（ai／i），声调相同（都是第四声），意思是「土地的价格」。"}, {"text": "菜价", "is_correct": false, "explanation": "dài 与 cài 声母不同（d／c），声调与韵母相同，意思是「蔬菜的价格」。"}, {"text": "大加", "is_correct": false, "explanation": "dài 与 dà 韵母不同（ai／a），jià 与 jiā 声调不同，「大加」是副词，意思是「大大地」。"}], "explanations": {"代价": "正确答案。代价（dàijià）指为得到某物而必须付出的东西。", "地价": "dài 与 dì 韵母不同（ai／i），声调相同（都是第四声），意思是「土地的价格」。", "菜价": "dài 与 cài 声母不同（d／c），声调与韵母相同，意思是「蔬菜的价格」。", "大加": "dài 与 dà 韵母不同（ai／a），jià 与 jiā 声调不同，「大加」是副词，意思是「大大地」。"}, "sentence_index": null, "correct_answer": "代价"}, "level_3": {"options": [{"text": "代价", "is_correct": true, "explanation": "正确答案。“代价”指成功所付出的东西，与“时间和精力”相呼应。"}, {"text": "性格", "is_correct": false, "explanation": "语义：时间和精力是付出的东西，“性格”不能作为成功的代价，句子读不通。"}, {"text": "灯光", "is_correct": false, "explanation": "语义：灯光不是为成功而付出的东西，句子意思荒谬。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：颜色是外在特征，不能说“成功的颜色”。"}], "explanations": {"代价": "正确答案。“代价”指成功所付出的东西，与“时间和精力”相呼应。", "性格": "语义：时间和精力是付出的东西，“性格”不能作为成功的代价，句子读不通。", "灯光": "语义：灯光不是为成功而付出的东西，句子意思荒谬。", "颜色": "体貌：颜色是外在特征，不能说“成功的颜色”。"}, "sentence_index": 6, "correct_answer": "代价"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里离车站的代价很远。", "explanation": "这里应该用〈距离〉。代价指付出的东西，不能用来表示空间的远近。"}, {"text": "他的代价很强，什么工作都能做。", "explanation": "这里应该用〈能力〉。代价是为得到某物而付出的东西，不能用来形容人的本事。"}, {"text": "这种药的代价很好。", "explanation": "这里应该用〈效果〉。代价不能用来评价药的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92293, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他为了健康得到了不少代价。", "corrected_sentence": "他为了健康付出了不少代价。", "error_description": "「得到」与「代价」不搭配。代价是为得到某物而付出的东西，应说「付出了不少代价」，把「付出」误写成「得到」，句子意思完全相反。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92293, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "为了这个目标，我们享受了很大的代价。", "corrected_sentence": "为了这个目标，我们承担了很大的代价。", "error_description": "「享受」与「代价」不搭配。代价是要承担或付出的，应说「承担了很大的代价」，把「承担」误写成「享受」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
