INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92297, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "俩是两个人。", "primary_collocate": null, "pronunciation": "liǎ", "ipa": "lja˨˩˦", "syllable_count": 1, "sentences": [{"text": "我们俩是多年的好朋友，就我和他从小一起长大。", "target_word": "俩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他俩昨天一起去看电影了。", "target_word": "俩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐妹俩长得很像。", "target_word": "俩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你们俩别吵了，快坐下吃饭。", "target_word": "俩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "兄弟俩住在同一个城市。", "target_word": "俩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "咱俩明天一起去爬山吧。", "target_word": "俩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她俩从小就认识。", "target_word": "俩", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夫妻俩每天早上一起跑步。", "target_word": "俩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，你们俩下课后来我办公室。", "target_word": "俩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们俩都喜欢踢足球。", "target_word": "俩", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "咱俩", "label": "复合"}, {"form": "俩人", "label": "复合"}], "register": "口语", "sense_fingerprint": "指两个人，常接在人称代词或亲属称谓后，如“我们俩”“姐妹俩”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f447c5a2-140b-433d-8f46-2a9e5f4c3fee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92297, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "俩", "is_correct": true, "explanation": "俩 liǎ 指两个人，是本词的读音和意思。"}, {"text": "脸", "is_correct": false, "explanation": "liǎn（第三声）与 liǎ 韵母不同（多了 -n），意思是脸，与“两个人”无关。"}, {"text": "假", "is_correct": false, "explanation": "jiǎ（第三声）与 liǎ 声母不同（j 与 l），意思是假，与“两个人”无关。"}, {"text": "柳", "is_correct": false, "explanation": "liǔ（第三声）与 liǎ 韵母不同（u 与 a），意思是柳树。"}], "explanations": {"俩": "俩 liǎ 指两个人，是本词的读音和意思。", "脸": "liǎn（第三声）与 liǎ 韵母不同（多了 -n），意思是脸，与“两个人”无关。", "假": "jiǎ（第三声）与 liǎ 声母不同（j 与 l），意思是假，与“两个人”无关。", "柳": "liǔ（第三声）与 liǎ 韵母不同（u 与 a），意思是柳树。"}, "sentence_index": null, "correct_answer": "俩"}, "level_3": {"options": [{"text": "俩", "is_correct": true, "explanation": "俩指两个人，与“我们”组合表示说话人和另一个人，符合句意。"}, {"text": "仨", "is_correct": false, "explanation": "语义：仨指三个人，与“俩”表示的两人义不符。"}, {"text": "四个", "is_correct": false, "explanation": "语义：“四个”与“俩”所指的两人不符，与后句“就我和他”矛盾。"}, {"text": "一个", "is_correct": false, "explanation": "搭配：“我们一个”不成词组，不能表示人数。"}], "explanations": {"俩": "俩指两个人，与“我们”组合表示说话人和另一个人，符合句意。", "仨": "语义：仨指三个人，与“俩”表示的两人义不符。", "四个": "语义：“四个”与“俩”所指的两人不符，与后句“就我和他”矛盾。", "一个": "搭配：“我们一个”不成词组，不能表示人数。"}, "sentence_index": 0, "correct_answer": "俩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们俩一共三个人。", "explanation": "“俩”指两人，与“一共三个人”人数矛盾，应说〈我们三个人〉。"}, {"text": "咱俩和老王四人一起去超市。", "explanation": "“咱俩”加上老王是三人，“四人”与之矛盾，应说〈三人〉。"}, {"text": "他俩是一个人。", "explanation": "这里把“俩”用来指单独一人，但“俩”只能指两人，单人应改用〈一人〉之类的说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92297, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "俩", "is_correct": true, "explanation": "俩 liǎ 指两个人，是本词的读音和意思。"}, {"text": "咧", "is_correct": false, "explanation": "liě（第三声）与 liǎ 韵母不同（e 与 a），意思是咧嘴。"}, {"text": "里", "is_correct": false, "explanation": "lǐ（第三声）比 liǎ 少了韵母 a，声调相同，意思是里面。"}, {"text": "甲", "is_correct": false, "explanation": "jiǎ（第三声）与 liǎ 声母不同（j 与 l），意思是甲。"}], "explanations": {"俩": "俩 liǎ 指两个人，是本词的读音和意思。", "咧": "liě（第三声）与 liǎ 韵母不同（e 与 a），意思是咧嘴。", "里": "lǐ（第三声）比 liǎ 少了韵母 a，声调相同，意思是里面。", "甲": "jiǎ（第三声）与 liǎ 声母不同（j 与 l），意思是甲。"}, "sentence_index": null, "correct_answer": "俩"}, "level_3": {"options": [{"text": "俩", "is_correct": true, "explanation": "俩指两个人，作“她”的同位成分，表示她和另一人，符合句意。"}, {"text": "本人", "is_correct": false, "explanation": "语义：本人指她自己一人，与“俩”表示的两人义不符。"}, {"text": "大伙", "is_correct": false, "explanation": "搭配：“大伙”指一群人，不能紧跟“她”构成表示两人的主语。"}, {"text": "人家", "is_correct": false, "explanation": "搭配：“人家”多指他人或自称，与“她”后接“从小就认识”的两人关系不搭配。"}], "explanations": {"俩": "俩指两个人，作“她”的同位成分，表示她和另一人，符合句意。", "本人": "语义：本人指她自己一人，与“俩”表示的两人义不符。", "大伙": "搭配：“大伙”指一群人，不能紧跟“她”构成表示两人的主语。", "人家": "搭配：“人家”多指他人或自称，与“她”后接“从小就认识”的两人关系不搭配。"}, "sentence_index": 6, "correct_answer": "俩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他俩都在场，但现场只有一个人。", "explanation": "“他俩都在场”与“现场只有一个人”矛盾，“俩”指两人，不能指一人。"}, {"text": "他们俩都是一个人，互相不认识。", "explanation": "“俩”指两人，却说“都是一个人”，数量矛盾。"}, {"text": "他们俩都是三个人。", "explanation": "这里人数是三个，应改用〈仨〉，不能用〈俩〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92297, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们俩个明天一起去买菜。", "corrected_sentence": "我们俩明天一起去买菜。", "error_description": "错误形式：“俩个”；正确形式：“俩”。“俩”已包含“两个”的意思，其后不能再加量词“个”，应说“我们俩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92297, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她俩们从小就很熟。", "corrected_sentence": "她俩从小就很熟。", "error_description": "错误形式：“俩们”；正确形式：“俩”。“俩”本身已指两人，后面不能再加复数后缀“们”，应说“她俩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
