INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92302, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "整个城市。", "primary_collocate": null, "pronunciation": "quán shì", "ipa": "tɕʰɥɛn˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "全市的人都在看比赛。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全市人民都很高兴。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天全市停电了。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全市学生明天一起考试。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的名字全市都知道。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全市都在等这场雨。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息传遍了全市。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全市的医生都来帮忙了。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全市一起过节，特别热闹。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说全市只有他得了第一。", "target_word": "全市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "整个城市，指城里的全体人或整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a375dcb8-ff9a-4a39-9db4-43a216043314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92302, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "全市", "is_correct": true, "explanation": "全市 quán shì：整个城市，指城里的全体人或整体。"}, {"text": "拳师", "is_correct": false, "explanation": "拳师 quánshī 与 全市 quánshì 第二个音节声调不同，意思是拳击或武术教练。"}, {"text": "全诗", "is_correct": false, "explanation": "全诗 quánshī 与 全市 quánshì 第二个音节声调不同，意思是完整的一首诗。"}, {"text": "全史", "is_correct": false, "explanation": "全史 quánshǐ 与 全市 quánshì 第二个音节声调不同，意思是完整的历史。"}], "explanations": {"全市": "全市 quán shì：整个城市，指城里的全体人或整体。", "拳师": "拳师 quánshī 与 全市 quánshì 第二个音节声调不同，意思是拳击或武术教练。", "全诗": "全诗 quánshī 与 全市 quánshì 第二个音节声调不同，意思是完整的一首诗。", "全史": "全史 quánshǐ 与 全市 quánshì 第二个音节声调不同，意思是完整的历史。"}, "sentence_index": null, "correct_answer": "全市"}, "level_3": {"options": [{"text": "全市", "is_correct": true, "explanation": "全市指城里的全体人，符合“都在看比赛”的语境。"}, {"text": "全身", "is_correct": false, "explanation": "语义：“全身”指人或动物的整个身体，不指城里的人群。"}, {"text": "全书", "is_correct": false, "explanation": "语义：“全书”指一本书，不能指看比赛的人。"}, {"text": "全天", "is_correct": false, "explanation": "搭配：“全天”说的是时长，不能用来修饰表示人群的名词。"}], "explanations": {"全市": "全市指城里的全体人，符合“都在看比赛”的语境。", "全身": "语义：“全身”指人或动物的整个身体，不指城里的人群。", "全书": "语义：“全书”指一本书，不能指看比赛的人。", "全天": "搭配：“全天”说的是时长，不能用来修饰表示人群的名词。"}, "sentence_index": 0, "correct_answer": "全市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我全市都在发抖。", "explanation": "这里应该用〈全身〉。〈全市〉指整座城市，不能用来指一个人的身体。"}, {"text": "这本书全市共有十章。", "explanation": "这里应该用〈全书〉。〈全市〉指城市，不能用来指一本书的范围。"}, {"text": "我全市都在复习。", "explanation": "这里应该用〈全天〉。〈全市〉指城市的范围，不能用来表示一整天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92302, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全市", "is_correct": true, "explanation": "全市指整座城市，消息可以传遍全市，符合句子的语境。"}, {"text": "全年", "is_correct": false, "explanation": "语义：“全年”指一整年，消息不会“传遍”一整年。"}, {"text": "全页", "is_correct": false, "explanation": "语义：“全页”指一张纸的整页，消息不能传遍一页纸。"}, {"text": "全程", "is_correct": false, "explanation": "搭配：“全程”说的是行程的整段，不能用来指消息传播的范围。"}], "explanations": {"全市": "全市指整座城市，消息可以传遍全市，符合句子的语境。", "全年": "语义：“全年”指一整年，消息不会“传遍”一整年。", "全页": "语义：“全页”指一张纸的整页，消息不能传遍一页纸。", "全程": "搭配：“全程”说的是行程的整段，不能用来指消息传播的范围。"}, "sentence_index": 6, "correct_answer": "全市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的全市作业都做完了。", "explanation": "〈全市〉指整座城市的全体，不能表示“全部”，应说“全部作业”。"}, {"text": "我一个人把这盘菜全市都吃光了。", "explanation": "这里应该用〈全部〉。〈全市〉指整个城市或城里的全体人，「我一个人」的动作不能用「全市」来表示。"}, {"text": "他的全市钱都花光了。", "explanation": "〈全市〉指整座城市，不能表示“全部”，应说“全部的钱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个消息让全市地人民都很激动。", "corrected_sentence": "这个消息让全市的人民都很激动。", "error_description": "错误：修饰名词「人民」的「全市」要用「的」，不能用「地」；应说「全市的人民」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那场大火的消息让一个全市都紧张起来了。", "corrected_sentence": "那场大火的消息让全市都紧张起来了。", "error_description": "错误：「全市」指整个城市，是整体而非可数的个体，不能用数量词「一个」修饰。应去掉「一个」，说「让全市都紧张起来了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92305, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保守", "is_correct": true, "explanation": "保守与“冒险”意思相反，指不敢冒险、只做稳妥的事。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明指智力高、反应快，与“冒险”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹指场面喧闹、人多，与“冒险”没有反义关系。"}, {"text": "勤奋", "is_correct": false, "explanation": "勤奋指努力、不怕吃苦，与“冒险”没有反义关系。"}], "correct_answer": "保守", "explanations": {"保守": "保守与“冒险”意思相反，指不敢冒险、只做稳妥的事。", "聪明": "聪明指智力高、反应快，与“冒险”没有反义关系。", "热闹": "热闹指场面喧闹、人多，与“冒险”没有反义关系。", "勤奋": "勤奋指努力、不怕吃苦，与“冒险”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92305, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "谨慎", "is_correct": true, "explanation": "谨慎与“冒险”意思相反，指做事小心，不去做有危险的事。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮指外貌或事物好看，与“冒险”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、不模糊，与“冒险”没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "热情指态度亲切主动，与“冒险”没有反义关系。"}], "correct_answer": "谨慎", "explanations": {"谨慎": "谨慎与“冒险”意思相反，指做事小心，不去做有危险的事。", "漂亮": "漂亮指外貌或事物好看，与“冒险”没有反义关系。", "清楚": "清楚指明白、不模糊，与“冒险”没有反义关系。", "热情": "热情指态度亲切主动，与“冒险”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92305, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "冒险是去做有危险的事。", "primary_collocate": null, "pronunciation": "mào xiǎn", "ipa": "maʊ˥˩ ɕjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "他喜欢去山里冒险。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们想去森林里冒险。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就爱冒险。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们计划去非洲丛林冒险。", "target_word": "冒险", "complexity_tier": "T3", "furigana": "wǒ men jì huà qù fēi zhōu cóng lín mào xiǎn", "sentence_source": "generated"}, {"text": "我们不应该在河边冒险。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸不让我一个人冒险。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个喜欢冒险的人。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们决定去海上冒险。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人常想出去冒险。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山上冒险，结果迷路了。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "冒险家", "label": "派生词"}, {"form": "冒险精神", "label": "复合词"}], "register": "中性", "sense_fingerprint": "去做有危险的事，探险", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a375dcb8-ff9a-4a39-9db4-43a216043314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92305, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "冒险", "is_correct": true, "explanation": "冒险（mào xiǎn）意思是去做有危险的事。"}, {"text": "保险", "is_correct": false, "explanation": "bǎo（第三声）与 mào（第四声）声母不同（b 与 m），保险意思是防范风险，不是去冒险。"}, {"text": "好险", "is_correct": false, "explanation": "hǎo（第三声）与 mào（第四声）声母不同（h 与 m），好险意思是差一点出事。"}, {"text": "毛线", "is_correct": false, "explanation": "máo（第二声）与 mào（第四声）声调不同，xiàn（第四声）与 xiǎn（第三声）声调也不同，意思是羊毛线。"}], "explanations": {"冒险": "冒险（mào xiǎn）意思是去做有危险的事。", "保险": "bǎo（第三声）与 mào（第四声）声母不同（b 与 m），保险意思是防范风险，不是去冒险。", "好险": "hǎo（第三声）与 mào（第四声）声母不同（h 与 m），好险意思是差一点出事。", "毛线": "máo（第二声）与 mào（第四声）声调不同，xiàn（第四声）与 xiǎn（第三声）声调也不同，意思是羊毛线。"}, "sentence_index": null, "correct_answer": "冒险"}, "level_3": {"options": [{"text": "冒险", "is_correct": true, "explanation": "冒险：与“喜欢去山里”搭配，表示去做有危险的事，句意通顺。"}, {"text": "恐高", "is_correct": false, "explanation": "语义：「恐高」指害怕高处，与「去山里」的爱好意思矛盾，句意不通。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是不愿发生的状态，与“喜欢”的意思冲突，句意不合常理。"}, {"text": "思念", "is_correct": false, "explanation": "配价：“思念”是及物动词，必须带宾语，不能在这里单独作谓语。"}], "explanations": {"冒险": "冒险：与“喜欢去山里”搭配，表示去做有危险的事，句意通顺。", "恐高": "语义：「恐高」指害怕高处，与「去山里」的爱好意思矛盾，句意不通。", "生病": "语义：“生病”是不愿发生的状态，与“喜欢”的意思冲突，句意不合常理。", "思念": "配价：“思念”是及物动词，必须带宾语，不能在这里单独作谓语。"}, "sentence_index": 0, "correct_answer": "冒险"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份作业很简单，我想冒险做一下。", "explanation": "这里应该用〈尝试〉。作业简单、没有危险，“冒险”表示有危险地去做事，尝试普通的事不能说冒险。"}, {"text": "他冒险生病了。", "explanation": "这里应该用〈不慎〉。冒险指自己有意去做有危险的事，生病是无意中遭遇的结果，不能说“冒险”。"}, {"text": "这次旅行非常安全平稳，我们却冒险去了一趟。", "explanation": "这里应该用〈随便〉。冒险指有危险地去做事，安全平稳的旅行没有危险，不能说冒险；“随便去”是不计较地去，与“冒险”不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92305, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冒险", "is_correct": true, "explanation": "冒险：作“喜欢”的对象，表示喜欢去做有危险的事，句意通顺。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：「失眠」指长期睡不着，是不舒服的状态，与「喜欢」的意思冲突，句意不合常理。"}, {"text": "挨饿", "is_correct": false, "explanation": "语义：“挨饿”是不愿遭受的状态，与“喜欢”的意思冲突，句意不合常理。"}, {"text": "晕车", "is_correct": false, "explanation": "语义：「晕车」指乘车时身体不适，是不愿遇到的状态，与「喜欢」的意思冲突，句意不合常理。"}], "explanations": {"冒险": "冒险：作“喜欢”的对象，表示喜欢去做有危险的事，句意通顺。", "失眠": "语义：「失眠」指长期睡不着，是不舒服的状态，与「喜欢」的意思冲突，句意不合常理。", "挨饿": "语义：“挨饿”是不愿遭受的状态，与“喜欢”的意思冲突，句意不合常理。", "晕车": "语义：「晕车」指乘车时身体不适，是不愿遇到的状态，与「喜欢」的意思冲突，句意不合常理。"}, "sentence_index": 6, "correct_answer": "冒险"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我们在博物馆里冒险参观了一下午。", "explanation": "这里应该用〈游览〉。冒险指有危险地去做事；在博物馆里安全地参观、游览不含危险，不能说冒险。"}, {"text": "他在路上冒险打了个喷嚏。", "explanation": "这里应该用〈不小心〉。冒险指有意去做有危险的事；打喷嚏是无意中发生的动作，不能说冒险。"}, {"text": "他在家里冒险睡了一个安稳的午觉。", "explanation": "这里应该用〈安心〉。冒险指有危险地去做事；在家安稳睡午觉没有危险，表示放心时不能说冒险。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92305, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年冒险了过一次。", "corrected_sentence": "他去年冒险过一次。", "error_description": "错误形式：「他去年冒险了过一次」；正确形式：「他去年冒险过一次」。表示经历的「过」已经表达完成，与「了」不能同时用在动词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92305, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他冒险着一次，结果受伤了。", "corrected_sentence": "他冒险了一次，结果受伤了。", "error_description": "错误形式：「他冒险着一次，结果受伤了」；正确形式：「他冒险了一次，结果受伤了」。「着」表示动作的持续状态，「冒险一次」是一次性完成的动作，应用表示完成的「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92306, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "谨慎", "is_correct": true, "explanation": "谨慎与“不顾危险去做某事”意思相反，指做事小心、避开危险。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、不模糊，与“冒险”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮指外貌或事物好看，与“冒险”没有反义关系。"}, {"text": "勤奋", "is_correct": false, "explanation": "勤奋指努力、不怕吃苦，与“冒险”没有反义关系。"}], "correct_answer": "谨慎", "explanations": {"谨慎": "谨慎与“不顾危险去做某事”意思相反，指做事小心、避开危险。", "清楚": "清楚指明白、不模糊，与“冒险”没有反义关系。", "漂亮": "漂亮指外貌或事物好看，与“冒险”没有反义关系。", "勤奋": "勤奋指努力、不怕吃苦，与“冒险”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92306, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保守", "is_correct": true, "explanation": "保守与“不顾危险去做某事”意思相反，指不敢冒险、只求稳妥。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹指场面喧闹、人多，与“冒险”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明指智力高、反应快，与“冒险”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静指没有声音、不吵闹，与“冒险”没有反义关系。"}], "correct_answer": "保守", "explanations": {"保守": "保守与“不顾危险去做某事”意思相反，指不敢冒险、只求稳妥。", "热闹": "热闹指场面喧闹、人多，与“冒险”没有反义关系。", "聪明": "聪明指智力高、反应快，与“冒险”没有反义关系。", "安静": "安静指没有声音、不吵闹，与“冒险”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92306, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不顾危险去做某事。", "primary_collocate": null, "pronunciation": "mào xiǎn", "ipa": "maʊ˥˩ ɕjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "他冒险跳进了河里。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生冒险给病人做了手术。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她冒险走过了那座旧桥。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员冒险冲进了火里。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们冒险在雨中开车回家。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他冒险把孩子送到了医院。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士冒险过河，给大家送信。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了救人，他冒险爬上了高楼。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机冒险停下车，帮了老人。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者冒险进入了大雨中的山区。", "target_word": "冒险", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "冒险家", "label": "派生词"}, {"form": "冒险精神", "label": "复合词"}], "register": "中性", "sense_fingerprint": "不顾危险，后接动作去做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a375dcb8-ff9a-4a39-9db4-43a216043314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92306, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "冒险", "is_correct": true, "explanation": "冒险（mào xiǎn）意思是不顾危险去做某事。"}, {"text": "保险", "is_correct": false, "explanation": "bǎo（第三声）与 mào（第四声）声母不同（b 与 m），保险意思是防范风险，不是不顾危险。"}, {"text": "好险", "is_correct": false, "explanation": "hǎo（第三声）与 mào（第四声）声母不同（h 与 m），好险意思是差一点出事。"}, {"text": "毛线", "is_correct": false, "explanation": "máo（第二声）与 mào（第四声）声调不同，xiàn（第四声）与 xiǎn（第三声）声调也不同，意思是羊毛线。"}], "explanations": {"冒险": "冒险（mào xiǎn）意思是不顾危险去做某事。", "保险": "bǎo（第三声）与 mào（第四声）声母不同（b 与 m），保险意思是防范风险，不是不顾危险。", "好险": "hǎo（第三声）与 mào（第四声）声母不同（h 与 m），好险意思是差一点出事。", "毛线": "máo（第二声）与 mào（第四声）声调不同，xiàn（第四声）与 xiǎn（第三声）声调也不同，意思是羊毛线。"}, "sentence_index": null, "correct_answer": "冒险"}, "level_3": {"options": [{"text": "冒险", "is_correct": true, "explanation": "冒险：作状语修饰“跳进”，表示不顾危险地跳进河里，句意通顺。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与后面已经发生的“跳进了”意思矛盾，句意不通。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与“跳进了河里”的动作相矛盾，放弃了又跳进去，句意不通。"}, {"text": "遇到", "is_correct": false, "explanation": "配价：“遇到”后接名词性宾语，不能接“跳进了河里”这样的动词短语。"}], "explanations": {"冒险": "冒险：作状语修饰“跳进”，表示不顾危险地跳进河里，句意通顺。", "拒绝": "语义：“拒绝”与后面已经发生的“跳进了”意思矛盾，句意不通。", "放弃": "语义：“放弃”与“跳进了河里”的动作相矛盾，放弃了又跳进去，句意不通。", "遇到": "配价：“遇到”后接名词性宾语，不能接“跳进了河里”这样的动词短语。"}, "sentence_index": 0, "correct_answer": "冒险"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我在家里冒险看了一场电影。", "explanation": "这里应该用〈消遣〉。冒险指不顾危险去做某事；在家看电影只是消遣，没有危险，不能说冒险。"}, {"text": "他冒险长高了三厘米。", "explanation": "这里应该用〈不知不觉〉。冒险指不顾危险主动去做某事；长高是自然发生的变化，不能说冒险。"}, {"text": "他冒险给花浇了水。", "explanation": "这里应该用〈照例〉。冒险指不顾危险去做某事；给花浇水没有危险，不能说冒险。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冒险", "is_correct": true, "explanation": "冒险：作状语修饰“过河”，表示不顾危险地过河送信，句意通顺。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避过河”与“给大家送信”的目的相矛盾，句意不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与过河、送信毫无关联，句意荒谬。"}, {"text": "拥有", "is_correct": false, "explanation": "配价：“拥有”是及物动词，必须带宾语，不能直接接“过河”。"}], "explanations": {"冒险": "冒险：作状语修饰“过河”，表示不顾危险地过河送信，句意通顺。", "逃避": "语义：“逃避过河”与“给大家送信”的目的相矛盾，句意不通。", "结婚": "语义：“结婚”与过河、送信毫无关联，句意荒谬。", "拥有": "配价：“拥有”是及物动词，必须带宾语，不能直接接“过河”。"}, "sentence_index": 6, "correct_answer": "冒险"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天在办公室冒险打扫房间。", "explanation": "这里应该用〈日常〉。冒险指不顾危险去做某事；在办公室里日常打扫没有危险，不能说冒险。"}, {"text": "记者冒险感冒了。", "explanation": "这里应该用〈着凉〉。冒险指有意去做有危险的事；感冒是无意中得的病，不能说冒险。"}, {"text": "这条平坦的高速公路上，记者冒险开车。", "explanation": "这里应该用〈照常〉。冒险指不顾危险去做某事；在平坦畅通的路上照常开车没有危险，不能说冒险。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她冒险的穿过了火场。", "corrected_sentence": "她冒险地穿过了火场。", "error_description": "错误形式：「她冒险的穿过了火场」；正确形式：「她冒险地穿过了火场」。修饰动词的状语要用「地」，「的」只用于名词性修饰语，不能用于这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他冒险得爬上了山顶。", "corrected_sentence": "他冒险地爬上了山顶。", "error_description": "错误形式：「他冒险得爬上了山顶」；正确形式：「他冒险地爬上了山顶」。修饰动词的状语要用“地”，“得”用于补语，这里误用了“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
