INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92309, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92309, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "反正是说不管怎么样，结果都一样。", "primary_collocate": null, "pronunciation": "fǎn zhèng", "ipa": "fan˨˩ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你去不去，反正结果都一样。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别等了，他来不来，反正我们都要走。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "贵也好，便宜也好，反正我都不买。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你说什么，反正他都不会听。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坐车还是走路，反正都要一个小时。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不管你怎么解释，反正他不会相信。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早去晚去，反正都得排队，不用着急。", "target_word": "反正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "试了很多次，反正结果还是一样的。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨也好，不下雨也好，反正我都会去。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她哭也好笑也好，反正这件事不会改变。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不管怎么样，结果都一样，常与“不管”“都”“也好”连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fda20375-ed58-4eb8-96ba-b11b06ce9777') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92309, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反正", "is_correct": true, "explanation": "正确：“反正”表示不管怎样结果都一样，与“你去不去”的选择相合。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，与“去不去”的选择和“结果都一样”的判断都无关。"}, {"text": "幸好", "is_correct": false, "explanation": "搭配：“幸好”后面通常接值得庆幸的结果，这里“结果都一样”不构成庆幸的理由。"}, {"text": "果然", "is_correct": false, "explanation": "语义：“果然”表示与预料相符，这句里没有先前的预料，用它不通。"}], "explanations": {"反正": "正确：“反正”表示不管怎样结果都一样，与“你去不去”的选择相合。", "忽然": "语义：“忽然”表示突然发生，与“去不去”的选择和“结果都一样”的判断都无关。", "幸好": "搭配：“幸好”后面通常接值得庆幸的结果，这里“结果都一样”不构成庆幸的理由。", "果然": "语义：“果然”表示与预料相符，这句里没有先前的预料，用它不通。"}, "sentence_index": 0, "correct_answer": "反正"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "如果明天下雨，反正我们就不去了。", "explanation": "这里应该用〈因此〉。“因此”表示由前面的条件推出结果，“反正”表示不管条件如何结果都一样，不能引出由条件决定的结论。"}, {"text": "我猜他会迟到，反正他真的迟到了。", "explanation": "这里应该用〈果然〉。“果然”表示事情与预料相符，“反正”只强调结果不受条件影响，不表示印证。"}, {"text": "这本书反正有三百页。", "explanation": "这里应该用〈大约〉。“大约”表示估计数量，“反正”没有估计数量的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92309, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反正", "is_correct": true, "explanation": "正确：“反正”表示不论早去还是晚去，都得排队，结论不变，与“不用着急”相合。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示故意或与期望相反，这句只是说明情况，没有这层意思。"}, {"text": "刚好", "is_correct": false, "explanation": "搭配：“刚好”表示恰巧合适，与“都得排队”所说的必然性不协调。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急忙，与后句“不用着急”直接矛盾。"}], "explanations": {"反正": "正确：“反正”表示不论早去还是晚去，都得排队，结论不变，与“不用着急”相合。", "偏偏": "语义：“偏偏”表示故意或与期望相反，这句只是说明情况，没有这层意思。", "刚好": "搭配：“刚好”表示恰巧合适，与“都得排队”所说的必然性不协调。", "赶紧": "语义：“赶紧”表示急忙，与后句“不用着急”直接矛盾。"}, "sentence_index": 6, "correct_answer": "反正"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "经过三次努力，他反正考上了大学。", "explanation": "这里应该用〈终于〉。“终于”表示经过努力后才实现，“反正”表示结果与条件无关，不强调经过。"}, {"text": "他的成绩反正很好，所以老师很喜欢他。", "explanation": "这里应该用〈因为〉。“因为”引出原因，“反正”不能引出原因，它表示不管怎样结果都一样。"}, {"text": "如果你努力，反正你会成功。", "explanation": "这里应该用〈只要〉。“只要”表示条件与结果有关，“反正”表示不管条件如何结果都一样，与“努力”的条件相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92309, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "别管他，反正的我都不信。", "corrected_sentence": "别管他，反正我都不信。", "error_description": "“反正”是副词，不能加“的”修饰名词或代词；应去掉“的”，为“反正我都不信”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92309, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "坐飞机也好，坐火车也好，反正很都要花不少钱。", "corrected_sentence": "坐飞机也好，坐火车也好，反正都要花不少钱。", "error_description": "“反正”是表示结论不变的副词，不能受程度副词“很”修饰；应去掉“很”，为“反正都要花不少钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
