INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92310, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92310, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示情况虽然不同，但结果或结论不变。", "primary_collocate": null, "pronunciation": "fǎn zhèng", "ipa": "fan˨˩ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你走这条路，我走那条路，反正都能到学校。", "target_word": "反正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说得对不对，反正我已经决定了。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "红的蓝的都行，反正我只要一件。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在去或者明天去，反正你都得去。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气好不好，反正明天我们都要出发。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你用笔写，他用电脑写，反正都要交作业。", "target_word": "反正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买大的还是小的，反正价钱差不多。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师同意不同意，反正我明天都要去。", "target_word": "反正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的办法不同，反正最后的结果是一样的。", "target_word": "反正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我说中文，他说英文，反正我们都听得懂。", "target_word": "反正", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "几种情况各不相同，但结论不变，前面常列出两种或多种选择", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fda20375-ed58-4eb8-96ba-b11b06ce9777') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反正", "is_correct": true, "explanation": "正确：“反正”表示两条路各不相同，但结论都是能到学校，与句意相合。"}, {"text": "反而", "is_correct": false, "explanation": "语义：“反而”表示与预料相反，句中没有转折的意思，只是并列说明两条路。"}, {"text": "白白", "is_correct": false, "explanation": "搭配：“白白”多接“浪费”“等待”等表示徒劳的行为，不接“都能到学校”这种有好结果的说法。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上行动，与“你走这条路，我走那条路”的并列选择不相合。"}], "explanations": {"反正": "正确：“反正”表示两条路各不相同，但结论都是能到学校，与句意相合。", "反而": "语义：“反而”表示与预料相反，句中没有转折的意思，只是并列说明两条路。", "白白": "搭配：“白白”多接“浪费”“等待”等表示徒劳的行为，不接“都能到学校”这种有好结果的说法。", "立刻": "语义：“立刻”表示马上行动，与“你走这条路，我走那条路”的并列选择不相合。"}, "sentence_index": 0, "correct_answer": "反正"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他练了很久，反正拿到了驾照。", "explanation": "这里应该用〈总算〉。“总算”表示经过努力后终于达到，“反正”不表达这种感慨。"}, {"text": "我以为他不来，反正他早就到了。", "explanation": "这里应该用〈原来〉。“原来”表示发现了真相，“反正”不表示意外的发现。"}, {"text": "这件衣服是他反正做的。", "explanation": "这里应该用〈亲手〉。“亲手”强调自己动手，“反正”没有这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反正", "is_correct": true, "explanation": "正确：“反正”表示两种情况价钱不同，但结论不变，与“价钱差不多”相合。"}, {"text": "难道", "is_correct": false, "explanation": "语义：“难道”表示反问，这句是陈述语气，用它不通。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示故意或与期望相反，这句只是比较两种选择。"}, {"text": "只好", "is_correct": false, "explanation": "搭配：“只好”后接不得不做的动作，不能用来说明“价钱差不多”这种状态。"}], "explanations": {"反正": "正确：“反正”表示两种情况价钱不同，但结论不变，与“价钱差不多”相合。", "难道": "语义：“难道”表示反问，这句是陈述语气，用它不通。", "偏偏": "语义：“偏偏”表示故意或与期望相反，这句只是比较两种选择。", "只好": "搭配：“只好”后接不得不做的动作，不能用来说明“价钱差不多”这种状态。"}, "sentence_index": 6, "correct_answer": "反正"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他反正把门关上，不让我们进去。", "explanation": "这里应该用〈故意〉。“故意”表示有意识地这样做，“反正”不表示动机。"}, {"text": "他的成绩很差，反正考试总是第一。", "explanation": "这里应该用〈其实〉。“其实”揭示与表面相反的真实情况，“反正”不表示揭示真相，这里与“成绩很差”的前提自相矛盾。"}, {"text": "只要天气好，反正我们都不去。", "explanation": "这里应该用〈所以〉。“所以”引出由条件决定的结果，“反正”表示条件不影响结果，二者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我坐地铁，你骑车，反正的都能准时到公司。", "corrected_sentence": "我坐地铁，你骑车，反正都能准时到公司。", "error_description": "“反正”是副词，不能加“的”修饰后面的成分；应去掉“的”，为“反正都能准时到公司”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你在家做饭，我在外面买菜，反正很晚饭都能吃上。", "corrected_sentence": "你在家做饭，我在外面买菜，反正晚饭都能吃上。", "error_description": "“反正”不能受程度副词“很”修饰；应去掉“很”，为“反正晚饭都能吃上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92315, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92315, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92315, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很会读书写字、很有本事的女孩或女人。", "primary_collocate": null, "pronunciation": "cái nǚ", "ipa": "tsʰai˧˥ ny˨˩˦", "syllable_count": 2, "sentences": [{"text": "她从小爱读书，长大后成了有名的才女。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位才女考试总是第一名。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "才女写的字又好看又有力。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐是个才女，读书写字样样都行。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是班里的才女，作文常常被老师夸。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个才女不但会读书，做事也很有本事。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居家的才女考上了最好的大学。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位才女一个人把公司办得很好。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说她是才女，什么书都读得懂。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "才女的书房里摆满了书。", "target_word": "才女", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位才女", "label": "量词"}, {"form": "一个才女", "label": "量词"}], "register": "通用", "sense_fingerprint": "指学习、写作好，做事很有能力的女孩或女人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '074eb1d9-d5d2-4422-9990-2487466d07f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92315, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "才女", "is_correct": true, "explanation": "正确：「才女」指很会读书的女子，与前句「从小爱读书」一致。"}, {"text": "才子", "is_correct": false, "explanation": "语义：「才子」指男子，与「她」不符。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：「图书馆」是地点，不能指「她」。"}, {"text": "水平", "is_correct": false, "explanation": "搭配：「有名的水平」搭配不当，「水平」也不指人。"}], "explanations": {"才女": "正确：「才女」指很会读书的女子，与前句「从小爱读书」一致。", "才子": "语义：「才子」指男子，与「她」不符。", "图书馆": "语义：「图书馆」是地点，不能指「她」。", "水平": "搭配：「有名的水平」搭配不当，「水平」也不指人。"}, "sentence_index": 0, "correct_answer": "才女"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我哥哥是个才女，读书写字样样都行。", "explanation": "这里应该用〈才子〉。才女专指女子，形容男子要用才子。"}, {"text": "我姐姐是个才女，可是连一个字都不会写。", "explanation": "这里把「才女」用成了〈不识字的人〉的意思。才女指很会读书写字的女子，句子说她连字都不会写，与本义相反。"}, {"text": "我姐姐长得很美，大家都叫她才女。", "explanation": "这里把「才女」用来夸容貌。才女指很会读书写字、很有本事的女子，不指容貌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92315, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "才女", "is_correct": true, "explanation": "正确：「才女」指人，能考上最好的大学，与句意相符。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：「汽车」不能考上大学，与句意不符。"}, {"text": "花园", "is_correct": false, "explanation": "语义：「花园」不能考上大学，与句意不符。"}, {"text": "作品", "is_correct": false, "explanation": "搭配：「作品」不能「考上」大学，这里的主语必须是人。"}], "explanations": {"才女": "正确：「才女」指人，能考上最好的大学，与句意相符。", "汽车": "语义：「汽车」不能考上大学，与句意不符。", "花园": "语义：「花园」不能考上大学，与句意不符。", "作品": "搭配：「作品」不能「考上」大学，这里的主语必须是人。"}, "sentence_index": 6, "correct_answer": "才女"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个同学脑子很笨，学习总是跟不上，可是大家都叫她才女。", "explanation": "这里把「才女」用成了〈笨〉的意思。才女指很会读书写字、很有本事的女子，句子说她学习跟不上，与本义相反。"}, {"text": "我家的鹦鹉是才女，会背很多诗。", "explanation": "这里把「才女」用成了〈会背诗的鸟〉的意思。才女只指很会读书写字的女子或女人，不能用来指鸟。"}, {"text": "她是个才女，可是从来不看书，也不读报。", "explanation": "这里把「才女」用成了〈不爱读书的人〉的意思。才女指很会读书写字的女子，句子说她从不看书，与本义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92315, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是班里的一颗才女，读书写字样样都行。", "corrected_sentence": "她是班里的一位才女，读书写字样样都行。", "error_description": "量词「颗」用于小而圆的东西，不能用来指人；应改为「位」，说「一位才女」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92315, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那三位才女们都很有学问。", "corrected_sentence": "那三位才女都很有学问。", "error_description": "「三位」已经表示人数，名词后不能再加「们」，应说「那三位才女都很有学问」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
