INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92327, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "故意惹别人生气，找麻烦。", "primary_collocate": null, "pronunciation": "zhǎo shì", "ipa": "tʂau˨˩ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "你别没事找事，行不行？", "target_word": "找事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他喝多了酒，到处找事。", "target_word": "找事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个人故意找事，想和我吵架。", "target_word": "找事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没惹他，他为什么来找事？", "target_word": "找事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟总是找事，哥哥很生气。", "target_word": "找事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们来这里找事，我们不要理他们。", "target_word": "找事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她心情不好，就跟同学找事。", "target_word": "找事", "complexity_tier": "T3", "furigana": "tā xīnqíng bù hǎo, jiù gēn tóngxué zhǎo shì.", "sentence_source": "generated"}, {"text": "客人故意找事，说菜里有虫子。", "target_word": "找事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板不喜欢员工在会上找事。", "target_word": "找事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你再找事，我不跟你玩了。", "target_word": "找事", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "没事找事", "label": "固定搭配"}], "register": "口语", "sense_fingerprint": "故意惹人生气、找麻烦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '010817e2-98c0-49e8-8874-0f3dd93b1418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92327, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "找事", "is_correct": true, "explanation": "正确。找事（zhǎo shì）指故意惹人生气、找麻烦。"}, {"text": "早市", "is_correct": false, "explanation": "zǎo（第三声）与 zhǎo 只差声母 z 与 zh，意思是早上的集市，不是找麻烦。"}, {"text": "找死", "is_correct": false, "explanation": "第二音节 sǐ（第三声）与 shì（第四声）声调不同，意思是寻死，与找麻烦不同。"}, {"text": "掌事", "is_correct": false, "explanation": "zhǎng 与 zhǎo 韵母不同（ang/ao），意思是主管事务，与找麻烦不同。"}], "explanations": {"找事": "正确。找事（zhǎo shì）指故意惹人生气、找麻烦。", "早市": "zǎo（第三声）与 zhǎo 只差声母 z 与 zh，意思是早上的集市，不是找麻烦。", "找死": "第二音节 sǐ（第三声）与 shì（第四声）声调不同，意思是寻死，与找麻烦不同。", "掌事": "zhǎng 与 zhǎo 韵母不同（ang/ao），意思是主管事务，与找麻烦不同。"}, "sentence_index": null, "correct_answer": "找事"}, "level_3": {"options": [{"text": "找事", "is_correct": true, "explanation": "正确。“别没事找事”是固定说法，指别故意惹麻烦。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：“微笑”不惹人烦，与“行不行”这种请对方停止的语气不合。"}, {"text": "进行", "is_correct": false, "explanation": "语域：“进行”是书面语，与这句口语化的请求不合。"}, {"text": "努力", "is_correct": false, "explanation": "语义：“努力”是积极的行为，不会惹人烦，与“别没事”的请求不合。"}], "explanations": {"找事": "正确。“别没事找事”是固定说法，指别故意惹麻烦。", "微笑": "语义：“微笑”不惹人烦，与“行不行”这种请对方停止的语气不合。", "进行": "语域：“进行”是书面语，与这句口语化的请求不合。", "努力": "语义：“努力”是积极的行为，不会惹人烦，与“别没事”的请求不合。"}, "sentence_index": 0, "correct_answer": "找事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不小心找事，把窗户打破了。", "explanation": "这里应该用〈闯祸〉。找事指故意惹人，不能指无意中闯的祸。"}, {"text": "周末我们去公园找事玩，玩得很开心。", "explanation": "这里应该用〈找乐子〉。找事指故意惹人，找乐子指玩耍取乐，不能说“找事玩”。"}, {"text": "他不是故意的，只是无意中找事。", "explanation": "这里应该用〈惹事〉。找事含有故意的意思，与“无意”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bc8d629-ae1c-4edc-ba37-b7f4bba02d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92327, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "找事", "is_correct": true, "explanation": "正确。“就跟同学找事”表示心情不好时故意找茬。"}, {"text": "道歉", "is_correct": false, "explanation": "语义：“道歉”是认错，与“心情不好、故意找茬”的语境不合。"}, {"text": "合作", "is_correct": false, "explanation": "搭配：“合作”指共同做事，不用于心情不好时的发泄。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与“心情不好、跟同学”的语境完全不合。"}], "explanations": {"找事": "正确。“就跟同学找事”表示心情不好时故意找茬。", "道歉": "语义：“道歉”是认错，与“心情不好、故意找茬”的语境不合。", "合作": "搭配：“合作”指共同做事，不用于心情不好时的发泄。", "结婚": "语义：“结婚”与“心情不好、跟同学”的语境完全不合。"}, "sentence_index": 6, "correct_answer": "找事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我下班后去找事，想问问他借的书。", "explanation": "这里应该用〈找人〉。找事指故意惹人，要表示去见某人，应说“找他”。"}, {"text": "我的钥匙丢了，我到处找事。", "explanation": "这里应该用〈找东西〉。找事指故意惹人，不能指寻找丢失的东西。"}, {"text": "谢谢你来找事，我很感动。", "explanation": "这里应该用〈帮忙〉。找事指故意惹人，不能用来表示感谢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bc8d629-ae1c-4edc-ba37-b7f4bba02d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92327, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今天又找事我了。", "corrected_sentence": "他今天又找我的事了。", "error_description": "离合词位置错误。“找事”是离合词，宾语“我”要放在“找”和“事”之间，应说“找我的事”，不能说“找事我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bc8d629-ae1c-4edc-ba37-b7f4bba02d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92327, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她找事找很厉害。", "corrected_sentence": "她找事找得很厉害。", "error_description": "补语结构错误。动词后带程度补语时，要用“得”连接，应说“找事找得很厉害”，不能直接用“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bc8d629-ae1c-4edc-ba37-b7f4bba02d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92331, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主观", "is_correct": true, "explanation": "正确：「主观」与「客观」是反义词，指带有个人想法。"}, {"text": "粗鲁", "is_correct": false, "explanation": "与「客观」没有反义关系，「粗鲁」指言行没有礼貌。"}, {"text": "复杂", "is_correct": false, "explanation": "与「客观」没有反义关系，「复杂」指事情或关系不简单。"}, {"text": "灵活", "is_correct": false, "explanation": "与「客观」没有反义关系，「灵活」指不死板、能变通。"}], "correct_answer": "主观", "explanations": {"主观": "正确：「主观」与「客观」是反义词，指带有个人想法。", "粗鲁": "与「客观」没有反义关系，「粗鲁」指言行没有礼貌。", "复杂": "与「客观」没有反义关系，「复杂」指事情或关系不简单。", "灵活": "与「客观」没有反义关系，「灵活」指不死板、能变通。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92331, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主观", "is_correct": true, "explanation": "正确：「主观」与「客观」是反义词，指带有个人想法。"}, {"text": "冷淡", "is_correct": false, "explanation": "与「客观」没有反义关系，「冷淡」指态度不热情。"}, {"text": "轻率", "is_correct": false, "explanation": "与「客观」没有反义关系，「轻率」指做事不认真考虑。"}, {"text": "懒惰", "is_correct": false, "explanation": "与「客观」没有反义关系，「懒惰」指不愿意做事。"}], "correct_answer": "主观", "explanations": {"主观": "正确：「主观」与「客观」是反义词，指带有个人想法。", "冷淡": "与「客观」没有反义关系，「冷淡」指态度不热情。", "轻率": "与「客观」没有反义关系，「轻率」指做事不认真考虑。", "懒惰": "与「客观」没有反义关系，「懒惰」指不愿意做事。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92331, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "客观是照着事情真的样子看，不加上自己的想法。", "primary_collocate": null, "pronunciation": "kè guān", "ipa": "kʰɤ˥˩ kuan˥", "syllable_count": 2, "sentences": [{"text": "看新闻要客观，别先有自己的想法。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲这件事讲得很客观，只说发生了什么。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "评价别人时，我们要尽量客观。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章不客观，作者只写了好的一面。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判要客观，不能偏向自己喜欢的队。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈看孩子的时候，常常不够客观。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很客观地说出了比赛的结果。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请客观一点，先把事实说清楚。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报道不客观，大家就不会相信它。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想听你客观的看法，不要只说好听的。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "客观地", "label": "副词形式"}, {"form": "客观性", "label": "复合"}], "register": "中性", "sense_fingerprint": "照事情真样子看、不加个人想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1214d3e9-5c7a-47b4-bed0-11150dfe4c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92331, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客观", "is_correct": true, "explanation": "正确：「客观」表示照事情的真样子看，与「别先有自己的想法」相合。"}, {"text": "主观", "is_correct": false, "explanation": "语义：「主观」指加上自己的想法，与「别先有自己的想法」直接相反。"}, {"text": "偏颇", "is_correct": false, "explanation": "语义：「偏颇」指有失公允、偏向一方，与「别先有自己的想法」所要求的不偏不倚相反。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：「冷淡」形容对人或事不热情，与看新闻的要求无关。"}], "explanations": {"客观": "正确：「客观」表示照事情的真样子看，与「别先有自己的想法」相合。", "主观": "语义：「主观」指加上自己的想法，与「别先有自己的想法」直接相反。", "偏颇": "语义：「偏颇」指有失公允、偏向一方，与「别先有自己的想法」所要求的不偏不倚相反。", "冷淡": "语义：「冷淡」形容对人或事不热情，与看新闻的要求无关。"}, "sentence_index": 0, "correct_answer": "客观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对客人很客观，每次都很热情。", "explanation": "这里应该用〈客气〉。「客观」指不受个人想法影响，对客人的礼貌应说「客气」。"}, {"text": "小明很客观地哭了。", "explanation": "这里〈客观〉与情绪性动作不搭配；容易与〈冷静〉混淆。"}, {"text": "这盘菜很客观，大家都说好吃。", "explanation": "这里应该用〈可口〉。「客观」用于看法和判断，不用来形容菜的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92331, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客观", "is_correct": true, "explanation": "正确：「客观」表示按事情的真样子说，与「说出了比赛的结果」相合。"}, {"text": "懒散", "is_correct": false, "explanation": "语义：「懒散」形容做事松懒、不认真，与如实报告比赛结果的态度不相称。"}, {"text": "豪迈", "is_correct": false, "explanation": "语义：「豪迈」形容气概，与报告比赛结果的语气不相称。"}, {"text": "神秘", "is_correct": false, "explanation": "语义：「神秘」指难以捉摸，与如实报告比赛结果相矛盾。"}], "explanations": {"客观": "正确：「客观」表示按事情的真样子说，与「说出了比赛的结果」相合。", "懒散": "语义：「懒散」形容做事松懒、不认真，与如实报告比赛结果的态度不相称。", "豪迈": "语义：「豪迈」形容气概，与报告比赛结果的语气不相称。", "神秘": "语义：「神秘」指难以捉摸，与如实报告比赛结果相矛盾。"}, "sentence_index": 6, "correct_answer": "客观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我客观地饿了，想吃点东西。", "explanation": "这里〈客观〉修饰身体感觉不合适；「客观」用于看法和判断，不指个人身体感受，容易与〈冷静〉混淆。"}, {"text": "我想听你客观的歌，不要只唱好听的。", "explanation": "这里应该用〈动听〉。「客观」用于看法和判断，不用来修饰歌曲。"}, {"text": "我想听你客观的情绪，不要只说好听的。", "explanation": "这里〈客观〉与个人感受的搭配不当；它容易与〈冷静〉混淆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92331, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他客观的讲述了事情的经过。", "corrected_sentence": "他客观地讲述了事情的经过。", "error_description": "「的」应为「地」：修饰动词「讲述」要用「地」，应说「客观地讲述」，「客观的讲述」中用了「的」，不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92331, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师客观的评价了我的作业。", "corrected_sentence": "老师客观地评价了我的作业。", "error_description": "「客观的评价」应为「客观地评价」：修饰动词要用「地」，不用「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92332, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主观", "is_correct": true, "explanation": "正确：「主观」与「客观」是反义词，指带有个人想法。"}, {"text": "盲目", "is_correct": false, "explanation": "与「客观」没有反义关系，「盲目」指不加思考地行动。"}, {"text": "固执", "is_correct": false, "explanation": "与「客观」没有反义关系，「固执」指不肯改变想法。"}, {"text": "慷慨", "is_correct": false, "explanation": "与「客观」没有反义关系，「慷慨」指大方、不吝啬。"}], "correct_answer": "主观", "explanations": {"主观": "正确：「主观」与「客观」是反义词，指带有个人想法。", "盲目": "与「客观」没有反义关系，「盲目」指不加思考地行动。", "固执": "与「客观」没有反义关系，「固执」指不肯改变想法。", "慷慨": "与「客观」没有反义关系，「慷慨」指大方、不吝啬。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92332, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主观", "is_correct": true, "explanation": "正确：「主观」与「客观」是反义词，指带有个人想法。"}, {"text": "偏激", "is_correct": false, "explanation": "与「客观」没有反义关系，「偏激」指想法或态度过于极端。"}, {"text": "随便", "is_correct": false, "explanation": "与「客观」没有反义关系，「随便」指不加认真考虑。"}, {"text": "热烈", "is_correct": false, "explanation": "与「客观」没有反义关系，「热烈」指情绪高涨。"}], "correct_answer": "主观", "explanations": {"主观": "正确：「主观」与「客观」是反义词，指带有个人想法。", "偏激": "与「客观」没有反义关系，「偏激」指想法或态度过于极端。", "随便": "与「客观」没有反义关系，「随便」指不加认真考虑。", "热烈": "与「客观」没有反义关系，「热烈」指情绪高涨。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92332, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "按照事物本来面貌，不受个人想法影响的。", "primary_collocate": null, "pronunciation": "kè guān", "ipa": "kʰɤ˥˩ kuan˥", "syllable_count": 2, "sentences": [{"text": "记者写新闻时，一定要客观，不能只说自己的看法。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个老师给分很客观，不看学生是谁。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要客观地看这件事，不能只听一个人说。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说得很客观，没有夸大，也没有少说。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "判断一个人，要客观，不能只看他的一面。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告很客观，里面都是真实的数字。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间说话，有时候不太容易客观。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官必须客观，不能因为喜欢谁就帮谁。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对自己的评价很客观，知道哪里好，哪里不好。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你太生气了，说的话不够客观。", "target_word": "客观", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "客观地", "label": "副词形式"}, {"form": "客观性", "label": "复合"}], "register": "中性", "sense_fingerprint": "按事物本来面貌、不受个人想法影响的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1214d3e9-5c7a-47b4-bed0-11150dfe4c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92332, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "客观", "is_correct": true, "explanation": "正确：「客观」表示不受个人想法影响，与「不能只说自己的看法」相合。"}, {"text": "主观", "is_correct": false, "explanation": "语义：「主观」指带有个人想法，与「不能只说自己的看法」的要求相反。"}, {"text": "随意", "is_correct": false, "explanation": "语义：「随意」指随便、不认真，与「一定要」所强调的严肃态度相反。"}, {"text": "武断", "is_correct": false, "explanation": "语义：「武断」指独断专行，与「不能只说自己的看法」直接冲突。"}], "explanations": {"客观": "正确：「客观」表示不受个人想法影响，与「不能只说自己的看法」相合。", "主观": "语义：「主观」指带有个人想法，与「不能只说自己的看法」的要求相反。", "随意": "语义：「随意」指随便、不认真，与「一定要」所强调的严肃态度相反。", "武断": "语义：「武断」指独断专行，与「不能只说自己的看法」直接冲突。"}, "sentence_index": 0, "correct_answer": "客观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很客观，总是请我们吃饭。", "explanation": "这里应该用〈客气〉。「客观」指不受个人想法影响，对人的礼貌应说「客气」。"}, {"text": "今天的天气很客观。", "explanation": "这里应该用〈晴朗〉之类形容气候的词；「客观」只用于看法和判断。"}, {"text": "他客观地吃了一碗饭。", "explanation": "这里应该用〈认真〉。「客观」修饰看法或判断，不修饰吃饭这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92332, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客观", "is_correct": true, "explanation": "正确：「客观」表示不受个人想法影响，与「不太容易」的说话要求相合。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：「整齐」形容排列或样子，不能用来形容说话。"}, {"text": "雪白", "is_correct": false, "explanation": "语义：「雪白」形容颜色，与说话的态度无关，句子荒谬。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：「粗糙」指质地不细或做事不细致，用在这里句子读不通。"}], "explanations": {"客观": "正确：「客观」表示不受个人想法影响，与「不太容易」的说话要求相合。", "整齐": "搭配：「整齐」形容排列或样子，不能用来形容说话。", "雪白": "语义：「雪白」形容颜色，与说话的态度无关，句子荒谬。", "粗糙": "语义：「粗糙」指质地不细或做事不细致，用在这里句子读不通。"}, "sentence_index": 6, "correct_answer": "客观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很客观地伤心了一整天。", "explanation": "这里〈客观〉与个人情绪搭配不当；它容易与〈冷静〉混淆。"}, {"text": "这件衣服很客观，我很喜欢。", "explanation": "这里应该用〈漂亮〉。「客观」用于看法和判断，不用来形容衣服。"}, {"text": "你一生气就很客观，说了很多不好听的话。", "explanation": "这里〈客观〉与情绪激动的语境相反，应用〈冷静〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
