INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92333, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从很多东西里选出自己要的。", "primary_collocate": null, "pronunciation": "tiāo", "ipa": "tʰjɑu˥˥", "syllable_count": 1, "sentences": [{"text": "桌上有很多糖，你自己挑。", "target_word": "挑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从一堆鞋里挑出一双黑的。", "target_word": "挑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的帽子很多，我挑了半天。", "target_word": "挑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐在市场上挑菜。", "target_word": "挑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在玩具店里挑玩具。", "target_word": "挑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些香蕉都很新鲜，你多挑几个。", "target_word": "挑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从三件外套里挑了一件。", "target_word": "挑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸挑了一个最大的苹果给我。", "target_word": "挑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想要哪个，先挑吧。", "target_word": "挑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我挑的这双鞋很舒服。", "target_word": "挑", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "挑了", "label": "体标（了）"}, {"form": "挑过", "label": "体标（过）"}, {"form": "挑着", "label": "体标（着）"}, {"form": "挑挑", "label": "重叠"}, {"form": "挑选", "label": "复合"}], "register": "口语", "sense_fingerprint": "从许多东西中拿出自己想要的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77de9a14-9b0d-47dd-90ec-b14e6f01c7cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92333, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "挑", "is_correct": true, "explanation": "正确答案。挑（tiāo，第一声）指从很多东西中选出自己要的。"}, {"text": "跳", "is_correct": false, "explanation": "跳（tiào，第四声）与挑（tiāo，第一声）声调不同，意思是跳跃。"}, {"text": "条", "is_correct": false, "explanation": "条（tiáo，第二声）与挑（tiāo，第一声）声调不同，意思是条状物。"}, {"text": "天", "is_correct": false, "explanation": "天（tiān）与挑（tiāo）韵母不同（an 与 ao），意思是天空。"}, {"text": "雕", "is_correct": false, "explanation": "雕（diāo）与挑（tiāo）声母不同（d 与 t），意思是雕刻。"}, {"text": "消", "is_correct": false, "explanation": "消（xiāo）与挑（tiāo）声母不同（x 与 t），意思是消除。"}, {"text": "标", "is_correct": false, "explanation": "标（biāo）与挑（tiāo）声母不同（b 与 t），意思是标记。"}], "explanations": {"挑": "正确答案。挑（tiāo，第一声）指从很多东西中选出自己要的。", "跳": "跳（tiào，第四声）与挑（tiāo，第一声）声调不同，意思是跳跃。", "条": "条（tiáo，第二声）与挑（tiāo，第一声）声调不同，意思是条状物。", "天": "天（tiān）与挑（tiāo）韵母不同（an 与 ao），意思是天空。", "雕": "雕（diāo）与挑（tiāo）声母不同（d 与 t），意思是雕刻。", "消": "消（xiāo）与挑（tiāo）声母不同（x 与 t），意思是消除。", "标": "标（biāo）与挑（tiāo）声母不同（b 与 t），意思是标记。"}, "sentence_index": null, "correct_answer": "挑"}, "level_3": {"options": [{"text": "挑", "is_correct": true, "explanation": "正确。“你自己挑”表示从很多糖里自己选。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不指从糖中选取，句意不通。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”是修理，不能用于从很多糖中选出。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”需要文字类宾语，不能指代糖。"}], "explanations": {"挑": "正确。“你自己挑”表示从很多糖里自己选。", "唱": "搭配：“唱”不指从糖中选取，句意不通。", "修": "语义：“修”是修理，不能用于从很多糖中选出。", "写": "配价：“写”需要文字类宾语，不能指代糖。"}, "sentence_index": 0, "correct_answer": "挑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总爱挑别人的刺。", "explanation": "这里的挑是“挑剔、找毛病”的意思，与“从很多东西里选出自己要的”无关。"}, {"text": "她用扁担挑着两桶水去井边。", "explanation": "这里的挑是“用扁担担”的意思，指用肩担物，与“挑选”的意思不同。"}, {"text": "他挑拨两家的关系，让他们吵了起来。", "explanation": "这里的挑是“挑拨、从中煽动”的意思，与“从很多东西中选出”的意思无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92333, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "挑", "is_correct": true, "explanation": "正确答案。挑（tiāo，第一声）指从很多东西中选出自己要的。"}, {"text": "超", "is_correct": false, "explanation": "超（chāo）与挑（tiāo）声母不同（ch 与 t），意思是超过。"}, {"text": "烧", "is_correct": false, "explanation": "烧（shāo）与挑（tiāo）声母不同（sh 与 t），意思是燃烧。"}, {"text": "调", "is_correct": false, "explanation": "调（tiáo，第二声）与挑（tiāo，第一声）声调不同，意思是调节。"}, {"text": "添", "is_correct": false, "explanation": "添（tiān）与挑（tiāo）韵母不同（an 与 ao），意思是增添。"}], "explanations": {"挑": "正确答案。挑（tiāo，第一声）指从很多东西中选出自己要的。", "超": "超（chāo）与挑（tiāo）声母不同（ch 与 t），意思是超过。", "烧": "烧（shāo）与挑（tiāo）声母不同（sh 与 t），意思是燃烧。", "调": "调（tiáo，第二声）与挑（tiāo，第一声）声调不同，意思是调节。", "添": "添（tiān）与挑（tiāo）韵母不同（an 与 ao），意思是增添。"}, "sentence_index": null, "correct_answer": "挑"}, "level_3": {"options": [{"text": "挑", "is_correct": true, "explanation": "正确。“从三件外套里挑了一件”表示选出一件。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能说“吃了一件外套”。"}, {"text": "躲", "is_correct": false, "explanation": "语义：“躲”是躲避，不能表示从外套中选出一件。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿咬，与句中的选取义不符。"}], "explanations": {"挑": "正确。“从三件外套里挑了一件”表示选出一件。", "吃": "搭配：“吃”的宾语是食物，不能说“吃了一件外套”。", "躲": "语义：“躲”是躲避，不能表示从外套中选出一件。", "咬": "语义：“咬”是用牙齿咬，与句中的选取义不符。"}, "sentence_index": 6, "correct_answer": "挑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她挑灯缝衣到深夜。", "explanation": "这里的挑是“拨亮灯芯”的意思，指挑亮灯，与“从很多东西里选出”无关。"}, {"text": "工人在布上挑花，手很稳。", "explanation": "这里的挑是“刺绣挑花”的意思，指用针在布上绣出花纹，与“选择”的意思不同。"}, {"text": "他挑开门帘走了进去。", "explanation": "这里的挑是“用物体向上或向旁拨开”的意思，指拨起门帘，与“选择”的意思无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92333, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们正在挑了三个最甜的西瓜。", "corrected_sentence": "我们正在挑三个最甜的西瓜。", "error_description": "“正在”表示动作正在进行，不能与动态助词“了”同用，应去掉“了”。错误形式：正在挑了；正确形式：正在挑。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
