INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92334, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "挑选；选择。", "primary_collocate": null, "pronunciation": "tiāo", "ipa": "tʰjɑu˥˥", "syllable_count": 1, "sentences": [{"text": "你帮我挑一件衣服吧。", "target_word": "挑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在水果店里挑苹果。", "target_word": "挑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么多颜色，我不知道挑哪个。", "target_word": "挑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈挑了一条红色的裙子。", "target_word": "挑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买西瓜要会挑，不然不甜。", "target_word": "挑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你挑一本喜欢的书。", "target_word": "挑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以随便挑，喜欢哪个都行。", "target_word": "挑", "complexity_tier": "T3", "furigana": "tiāo", "sentence_source": "generated"}, {"text": "她挑了很久，还是没有买。", "target_word": "挑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他挑好了礼物，准备送给朋友。", "target_word": "挑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们挑了一条好走的路去爬山。", "target_word": "挑", "complexity_tier": "T3", "furigana": "tiāo", "sentence_source": "generated"}], "morphological_forms": [{"form": "挑了", "label": "体标（了）"}, {"form": "挑过", "label": "体标（过）"}, {"form": "挑着", "label": "体标（着）"}, {"form": "挑挑", "label": "重叠"}, {"form": "挑选", "label": "复合"}], "register": "口语", "sense_fingerprint": "在几个选项中选择合适的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77de9a14-9b0d-47dd-90ec-b14e6f01c7cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92334, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "挑", "is_correct": true, "explanation": "正确答案。挑（tiāo，第一声）指从几样东西中选出合适的。"}, {"text": "跳", "is_correct": false, "explanation": "跳（tiào，第四声）与挑（tiāo，第一声）声调不同，意思是跳跃。"}, {"text": "条", "is_correct": false, "explanation": "条（tiáo，第二声）与挑（tiāo，第一声）声调不同，意思是条状物。"}, {"text": "天", "is_correct": false, "explanation": "天（tiān）与挑（tiāo）韵母不同（an 与 ao），意思是天空。"}, {"text": "雕", "is_correct": false, "explanation": "雕（diāo）与挑（tiāo）声母不同（d 与 t），意思是雕刻。"}, {"text": "消", "is_correct": false, "explanation": "消（xiāo）与挑（tiāo）声母不同（x 与 t），意思是消除。"}, {"text": "标", "is_correct": false, "explanation": "标（biāo）与挑（tiāo）声母不同（b 与 t），意思是标记。"}], "explanations": {"挑": "正确答案。挑（tiāo，第一声）指从几样东西中选出合适的。", "跳": "跳（tiào，第四声）与挑（tiāo，第一声）声调不同，意思是跳跃。", "条": "条（tiáo，第二声）与挑（tiāo，第一声）声调不同，意思是条状物。", "天": "天（tiān）与挑（tiāo）韵母不同（an 与 ao），意思是天空。", "雕": "雕（diāo）与挑（tiāo）声母不同（d 与 t），意思是雕刻。", "消": "消（xiāo）与挑（tiāo）声母不同（x 与 t），意思是消除。", "标": "标（biāo）与挑（tiāo）声母不同（b 与 t），意思是标记。"}, "sentence_index": null, "correct_answer": "挑"}, "level_3": {"options": [{"text": "挑", "is_correct": true, "explanation": "正确。“帮我挑一件衣服”表示从几件中选出一件，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能说“吃一件衣服”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语是饮品，不能说“喝一件衣服”。"}, {"text": "忘", "is_correct": false, "explanation": "配价：“忘”的宾语必须是事情或经历，不能以“衣服”作宾语。"}], "explanations": {"挑": "正确。“帮我挑一件衣服”表示从几件中选出一件，符合句意。", "吃": "搭配：“吃”的宾语是食物，不能说“吃一件衣服”。", "喝": "搭配：“喝”的宾语是饮品，不能说“喝一件衣服”。", "忘": "配价：“忘”的宾语必须是事情或经历，不能以“衣服”作宾语。"}, "sentence_index": 0, "correct_answer": "挑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总爱挑我的毛病。", "explanation": "这里的挑是“挑剔、找出（缺点）”的意思，指挑毛病，与“从几样东西中选出一个”无关。"}, {"text": "他用扁担挑着两桶水。", "explanation": "这里的挑是“用扁担担”的意思，指用肩扛担，与“挑选”的意思完全不同。"}, {"text": "他挑起了两个班级的争端。", "explanation": "这里的挑是“引发、挑动”的意思，指惹起矛盾，与“选择”的意思无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92334, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "挑", "is_correct": true, "explanation": "正确答案。挑（tiāo，第一声）指从几样东西中选出合适的。"}, {"text": "超", "is_correct": false, "explanation": "超（chāo）与挑（tiāo）声母不同（ch 与 t），意思是超过。"}, {"text": "烧", "is_correct": false, "explanation": "烧（shāo）与挑（tiāo）声母不同（sh 与 t），意思是燃烧。"}, {"text": "调", "is_correct": false, "explanation": "调（tiáo，第二声）与挑（tiāo，第一声）声调不同，意思是调节。"}, {"text": "添", "is_correct": false, "explanation": "添（tiān）与挑（tiāo）韵母不同（an 与 ao），意思是增添。"}], "explanations": {"挑": "正确答案。挑（tiāo，第一声）指从几样东西中选出合适的。", "超": "超（chāo）与挑（tiāo）声母不同（ch 与 t），意思是超过。", "烧": "烧（shāo）与挑（tiāo）声母不同（sh 与 t），意思是燃烧。", "调": "调（tiáo，第二声）与挑（tiāo，第一声）声调不同，意思是调节。", "添": "添（tiān）与挑（tiāo）韵母不同（an 与 ao），意思是增添。"}, "sentence_index": null, "correct_answer": "挑"}, "level_3": {"options": [{"text": "挑", "is_correct": true, "explanation": "正确。“随便挑，喜欢哪个都行”表示从多个中选择。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与“喜欢哪个都行”的选择义矛盾。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：“摔”指使东西跌落破碎，不用于从多个中选择。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿咬，与句中“随便……喜欢哪个都行”的挑选意思不符。"}], "explanations": {"挑": "正确。“随便挑，喜欢哪个都行”表示从多个中选择。", "扔": "语义：“扔”是丢弃，与“喜欢哪个都行”的选择义矛盾。", "摔": "搭配：“摔”指使东西跌落破碎，不用于从多个中选择。", "咬": "语义：“咬”是用牙齿咬，与句中“随便……喜欢哪个都行”的挑选意思不符。"}, "sentence_index": 6, "correct_answer": "挑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他挑灯夜读，很认真。", "explanation": "这里的挑是“拨亮灯芯”的意思，指挑亮油灯，与“从多样东西中选择”无关。"}, {"text": "她在布上挑花，绣得很漂亮。", "explanation": "这里的挑是“刺绣挑花”的意思，指用针在布上绣出花纹，与“选择”的意思不同。"}, {"text": "他用针挑出了鱼刺。", "explanation": "这里的挑是“拨出、剔除”的意思，指用针拨出异物，与“选择”的意思无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在挑了一件很好看的外套。", "corrected_sentence": "他正在挑一件很好看的外套。", "error_description": "“正在”表示动作正在进行，不能与动态助词“了”同用，应去掉“了”。错误形式：正在挑了；正确形式：正在挑。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹挑了了一双鞋。", "corrected_sentence": "妹妹挑了一双鞋。", "error_description": "“了”重复出现，动态助词只能用一次。错误形式：挑了了一双鞋；正确形式：挑了一双鞋。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92337, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
