INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92337, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对家是玩牌时坐在你对面的人。", "primary_collocate": null, "pronunciation": "duì jiā", "ipa": "tweɪ˥˩ tɕja˥", "syllable_count": 2, "sentences": [{"text": "打牌时，我的对家是我爸爸。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他坐在我对面，是我的对家。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "麻将桌上，对家出了一张五万。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对家笑着看了看我手里的牌。", "target_word": "对家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对家一直在想怎么出牌。", "target_word": "对家", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "打牌时，我和对家隔着桌子互相看了一眼。", "target_word": "对家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩牌时，你的对家坐在你对面。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对家今天手气很好，赢了不少。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打麻将时，对家的牌我看不到。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的对家是个老师，打牌很慢。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "打牌、打麻将时坐在自己对面的那个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f447c5a2-140b-433d-8f46-2a9e5f4c3fee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92337, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对家", "is_correct": true, "explanation": "对家指打牌时坐在对面的人，可以是爸爸，符合句意。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：朋友是泛指的好友，与“是我爸爸”的亲属身份冲突。"}, {"text": "邻居", "is_correct": false, "explanation": "语义：邻居说明居住关系，与句中“是我爸爸”的身份冲突。"}, {"text": "同事", "is_correct": false, "explanation": "搭配：“同事”说的是工作关系，与“是我爸爸”不搭配。"}], "explanations": {"对家": "对家指打牌时坐在对面的人，可以是爸爸，符合句意。", "朋友": "语义：朋友是泛指的好友，与“是我爸爸”的亲属身份冲突。", "邻居": "语义：邻居说明居住关系，与句中“是我爸爸”的身份冲突。", "同事": "搭配：“同事”说的是工作关系，与“是我爸爸”不搭配。"}, "sentence_index": 0, "correct_answer": "对家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我看到一只对家坐在我对面。", "explanation": "“对家”指人，计量应用“位”或“个”；“只”多用于动物。"}, {"text": "我和对家一起去超市买菜了。", "explanation": "这里把“对家”误用为牌局之外的〈朋友〉，“对家”专指牌局中坐在对面的人。"}, {"text": "对家坐在我的左边，我们正在打牌。", "explanation": "这里把“对家”误作〈旁边的人〉，“对家”指坐在对面的人，应改用〈上家〉或〈下家〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92337, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对家", "is_correct": true, "explanation": "对家指坐在对面的人，可以作“坐在你对面”的主语，符合句意。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“坐在”的主语须为人，椅子不能“坐”在对面。"}, {"text": "牌", "is_correct": false, "explanation": "语义：牌是物件，不能作为坐在对面的人。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：桌子不能坐，与“坐在你对面”不搭配。"}], "explanations": {"对家": "对家指坐在对面的人，可以作“坐在你对面”的主语，符合句意。", "椅子": "搭配：“坐在”的主语须为人，椅子不能“坐”在对面。", "牌": "语义：牌是物件，不能作为坐在对面的人。", "桌子": "搭配：桌子不能坐，与“坐在你对面”不搭配。"}, "sentence_index": 6, "correct_answer": "对家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的对家是我自己，我们一起打牌。", "explanation": "这里把“对家”误作说话人自己，“对家”指对面的另一人，应改用〈搭档〉指他人。"}, {"text": "我的对家是一张麻将桌。", "explanation": "这里把“对家”误作〈桌子〉一类的物件，“对家”只指人，不能指麻将桌。"}, {"text": "我的对家在我的左边坐着，我们正在打牌。", "explanation": "这里把“对家”误作〈旁边的人〉，“对家”指对面的人，应改用〈上家〉或〈下家〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92337, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "麻将桌上，我的一只对家是我姐姐。", "corrected_sentence": "麻将桌上，我的一位对家是我姐姐。", "error_description": "错误形式：“一只对家”；正确形式：“一位对家”。“对家”指人，计量应用“位”或“个”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92337, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的对家们今天牌打得很好。", "corrected_sentence": "我的对家今天牌打得很好。", "error_description": "错误形式：“对家们”；正确形式：“对家”。麻将一局中对家只有一人，加“们”表示复数，与句意矛盾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
