INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92338, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "牌局中坐在对面、与自己同一方的人（搭档）。", "primary_collocate": null, "pronunciation": "duì jiā", "ipa": "tweɪ˥˩ tɕja˥", "syllable_count": 2, "sentences": [{"text": "打桥牌时，我和对家配合得很好。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对家出了红桃，我马上跟了一张。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是我多年的对家，我们常常一起赢牌。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们是一方，对家要多给我提示。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对家一出大牌，我就知道该怎么打。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这局我和对家输了，下局再来。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛开始前，我和对家先商量了一下暗号。", "target_word": "对家", "complexity_tier": "T3", "furigana": "duìjiā", "sentence_source": "generated"}, {"text": "去年的比赛中，我的对家是个很厉害的高手。", "target_word": "对家", "complexity_tier": "T3", "furigana": "duìjiā", "sentence_source": "generated"}, {"text": "我和对家商量好了，用同一种打法。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对家点了点头，我就明白了他的意思。", "target_word": "对家", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "牌局中坐在对面、与自己同一方的搭档", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f447c5a2-140b-433d-8f46-2a9e5f4c3fee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92338, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对家", "is_correct": true, "explanation": "对家指桥牌中同一方的搭档，与“配合”的同伴关系相符。"}, {"text": "对手", "is_correct": false, "explanation": "语义：对手是竞争的一方，与“配合”的同伴关系相反。"}, {"text": "裁判", "is_correct": false, "explanation": "搭配：“配合”的对象须为同伴，不能是裁判。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众不参与比赛，与“配合”的协作义不符。"}], "explanations": {"对家": "对家指桥牌中同一方的搭档，与“配合”的同伴关系相符。", "对手": "语义：对手是竞争的一方，与“配合”的同伴关系相反。", "裁判": "搭配：“配合”的对象须为同伴，不能是裁判。", "观众": "语义：观众不参与比赛，与“配合”的协作义不符。"}, "sentence_index": 0, "correct_answer": "对家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和对家一起去超市买菜了。", "explanation": "这里把“对家”误用为牌局之外的〈朋友〉，“对家”专指牌局中坐在对面、同方的人。"}, {"text": "对家坐在我旁边，我们是一方。", "explanation": "这里把“对家”误作〈旁边的人〉，“对家”指坐在对面的人，应改用〈上家〉或〈下家〉。"}, {"text": "我的对家就是我自己。", "explanation": "这里把“对家”误作说话人自己，“对家”指牌局中另一位同方的人，应改用〈搭档〉指他人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92338, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对家", "is_correct": true, "explanation": "对家指同一方的搭档，与“商量暗号”的合作关系相符。"}, {"text": "对方", "is_correct": false, "explanation": "语义：对方指对手一方，与“商量暗号”的合作关系冲突。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：敌人是对立的一方，与“商量暗号”的合作义不符。"}, {"text": "警察", "is_correct": false, "explanation": "搭配：“商量暗号”的对象通常是同伴，不能是警察。"}], "explanations": {"对家": "对家指同一方的搭档，与“商量暗号”的合作关系相符。", "对方": "语义：对方指对手一方，与“商量暗号”的合作关系冲突。", "敌人": "语义：敌人是对立的一方，与“商量暗号”的合作义不符。", "警察": "搭配：“商量暗号”的对象通常是同伴，不能是警察。"}, "sentence_index": 6, "correct_answer": "对家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他出了一张对家，我就赢了。", "explanation": "这里把“对家”误作可以计牌的名词，“对家”指人，不能用牌的量词〈张〉计量，应说〈位〉。"}, {"text": "对家是我自己，我坐在对面看他打牌。", "explanation": "这里把“对家”误作说话人自己，“对家”指牌局中另一位同方的人，应改用〈搭档〉指他人。"}, {"text": "对家在厨房里做饭，我们正在打牌。", "explanation": "这里把“对家”用于牌局之外的人，“对家”只指牌局中同方的人，应改用〈朋友〉等说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这局我和对家们赢了三把。", "corrected_sentence": "这局我和对家赢了三把。", "error_description": "错误形式：“对家们”；正确形式：“对家”。桥牌一局中对家只有一位搭档，加“们”表示复数，与句意矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我和一只对家先商量了一下暗号。", "corrected_sentence": "我和一位对家先商量了一下暗号。", "error_description": "错误形式：“一只对家”；正确形式：“一位对家”。“对家”指人，计量应用“位”或“个”，不用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92339, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
