INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92339, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力气或刀枪，抢走别人的东西。", "primary_collocate": null, "pronunciation": "qiǎng jié", "ipa": "tɕʰjɑŋ˨˩˦ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "昨天有人在街上抢劫。", "target_word": "抢劫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坏人拿着刀抢劫了一家商店。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为抢劫被警察抓住了。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上一个人走路，要小心有人抢劫。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人用枪抢劫银行。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着刀，在路上抢劫路人的钱包。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在找昨晚抢劫的人。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抢劫是犯法的事情，不能做。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个男人抢劫了一位老人的手机。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前抢劫过别人，现在后悔了。", "target_word": "抢劫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抢劫了", "label": "体标（了）"}, {"form": "抢劫过", "label": "体标（过）"}, {"form": "抢劫犯", "label": "复合"}, {"form": "抢劫案", "label": "复合"}, {"form": "搶劫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用力气或武器强行夺走别人的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77de9a14-9b0d-47dd-90ec-b14e6f01c7cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92339, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抢劫", "is_correct": true, "explanation": "正确。“抢劫”指用暴力夺取财物，与“在街上”的语境相符。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：街上不能洗澡，“在街上洗澡”句意说不通。"}, {"text": "上课", "is_correct": false, "explanation": "语义：“上课”需要教室，“在街上上课”说不通。"}, {"text": "长高", "is_correct": false, "explanation": "体貌：“长高”描述身高变化，不指在街上发生的行为。"}], "explanations": {"抢劫": "正确。“抢劫”指用暴力夺取财物，与“在街上”的语境相符。", "洗澡": "语义：街上不能洗澡，“在街上洗澡”句意说不通。", "上课": "语义：“上课”需要教室，“在街上上课”说不通。", "长高": "体貌：“长高”描述身高变化，不指在街上发生的行为。"}, "sentence_index": 0, "correct_answer": "抢劫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在地铁上抢劫了一个空座位。", "explanation": "这里应该用〈抢占〉。先于别人占据空位，并未夺取他人财物，不能说抢劫。"}, {"text": "他在网上抢劫了一张打折的机票。", "explanation": "这里应该用〈抢购〉。抢着买，并非用暴力夺取他人财物，不能说抢劫。"}, {"text": "他趁老师不注意，抢劫了同学的橡皮。", "explanation": "这里应该用〈偷〉。悄悄拿走，没有使用暴力或威胁，应说偷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92339, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抢劫", "is_correct": true, "explanation": "正确。“抢劫的人”指作案的人，与“找”的语境相符。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”的对象是书刊，“昨晚出版的人”与找人的语境不符。"}, {"text": "变胖", "is_correct": false, "explanation": "体貌：“变胖”说的是体形变化，不能用来修饰警察要找的作案人。"}, {"text": "发送", "is_correct": false, "explanation": "搭配：“发送”需要物件或信息作宾语，“发送的人”说不通。"}], "explanations": {"抢劫": "正确。“抢劫的人”指作案的人，与“找”的语境相符。", "出版": "搭配：“出版”的对象是书刊，“昨晚出版的人”与找人的语境不符。", "变胖": "体貌：“变胖”说的是体形变化，不能用来修饰警察要找的作案人。", "发送": "搭配：“发送”需要物件或信息作宾语，“发送的人”说不通。"}, "sentence_index": 6, "correct_answer": "抢劫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在超市抢劫了一瓶酒，还没付钱。", "explanation": "这里应该用〈偷窃〉。抢劫需要当场使用暴力或威胁，悄悄拿走商品而不付钱应说偷窃。"}, {"text": "他用假消息抢劫了老人的钱。", "explanation": "这里应该用〈骗〉。用欺骗手段获取钱财，没有暴力或威胁，不能说抢劫。"}, {"text": "很多人一早就去商场抢劫打折的商品。", "explanation": "这里应该用〈抢购〉。抢购是争着买，不是用力气或刀枪抢走财物，不能说抢劫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92339, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个青年在夜里被抢劫了一家便利店。", "corrected_sentence": "两个青年在夜里抢劫了一家便利店。", "error_description": "“被”把“两个青年”变成受害者，而“便利店”并非他们所有，句意不通；应去掉“被”。错误形式：被抢劫了一家便利店；正确形式：抢劫了一家便利店。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92339, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有抢劫了一家银行。", "corrected_sentence": "他没有抢劫过一家银行。", "error_description": "“没有”与“了”不能搭配，表示没有过的经历应用体标“过”。错误形式：没有抢劫了；正确形式：没有抢劫过。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
