INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92343, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92343, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对比是把两样东西放在一起，看有什么不一样。", "primary_collocate": null, "pronunciation": "duì bǐ", "ipa": "tweɪ˥˩ pi˨˩˦", "syllable_count": 2, "sentences": [{"text": "把两张照片对比一下。", "target_word": "对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们来对比这两个手机。", "target_word": "对比", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "对比了价格，我买了便宜的。", "target_word": "对比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让学生对比两篇文章。", "target_word": "对比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你对比过这两家店吗？", "target_word": "对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对比着看，差别就很清楚。", "target_word": "对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请对比一下去年和今年的成绩。", "target_word": "对比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对比了几种方法，选了最简单的。", "target_word": "对比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买东西前，最好先对比价格。", "target_word": "对比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把新旧房子对比了一下。", "target_word": "对比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对比了", "label": "体标"}, {"form": "对比过", "label": "体标"}, {"form": "对比着", "label": "体标"}, {"form": "对比度", "label": "复合"}], "register": "中性", "sense_fingerprint": "把两样东西放在一起看差别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1214d3e9-5c7a-47b4-bed0-11150dfe4c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92343, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对比", "is_correct": true, "explanation": "正确答案。“对比”指把两张照片放在一起看有什么不同。"}, {"text": "吃", "is_correct": false, "explanation": "语义：照片不能吃，“吃一下照片”句子读不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“照片”作宾语，搭配不当。"}, {"text": "煮", "is_correct": false, "explanation": "语义：照片不能用来煮，句子意思荒谬。"}], "explanations": {"对比": "正确答案。“对比”指把两张照片放在一起看有什么不同。", "吃": "语义：照片不能吃，“吃一下照片”句子读不通。", "唱": "搭配：“唱”不能带“照片”作宾语，搭配不当。", "煮": "语义：照片不能用来煮，句子意思荒谬。"}, "sentence_index": 0, "correct_answer": "对比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生对比了病人。", "explanation": "这里应该用〈检查〉。对比要把两样东西放在一起看差别，只针对一个对象时要说「检查」。"}, {"text": "他对比了一本书。", "explanation": "这里应该用〈阅读〉。对比至少要两样东西，不能只对比一本书。"}, {"text": "妈妈对比了那件衣服。", "explanation": "这里应该用〈挑选〉。对比要两样东西放在一起看，挑选一件衣服不用「对比」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92343, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对比", "is_correct": true, "explanation": "正确答案。“对比”指把去年和今年的成绩放在一起看差别。"}, {"text": "咬", "is_correct": false, "explanation": "语义：成绩不能咬，句子意思荒谬。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“成绩”作宾语。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不与“成绩”搭配，句子读不通。"}], "explanations": {"对比": "正确答案。“对比”指把去年和今年的成绩放在一起看差别。", "咬": "语义：成绩不能咬，句子意思荒谬。", "睡": "配价：“睡”是不及物动词，不能带“成绩”作宾语。", "洗": "搭配：“洗”不与“成绩”搭配，句子读不通。"}, "sentence_index": 6, "correct_answer": "对比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人对比了这台机器。", "explanation": "这里应该用〈修理〉。对比需要两样东西放在一起看，只针对一台机器时不用「对比」。"}, {"text": "他们对比了长城。", "explanation": "这里应该用〈游览〉。对比要求两样以上的东西，不能只对比一个地点。"}, {"text": "司机对比了这辆车。", "explanation": "这里应该用〈驾驶〉。对比不用于只针对一辆车的操作，应说「驾驶」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92343, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请对比了这两份报告。", "corrected_sentence": "请对比这两份报告。", "error_description": "「请」开头的祈使句不能加「了」。「了」表示已经完成，与祈使语气矛盾，应说「请对比这两份报告」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92343, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对比了过两份报告。", "corrected_sentence": "他对比过两份报告。", "error_description": "时态助词错误。「对比过」表示经历过，「了」与「过」不能同时使用，应说「他对比过两份报告」，去掉多余的「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
