INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92344, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把两种事物放在一起比较，看出差别。", "primary_collocate": null, "pronunciation": "duì bǐ", "ipa": "tweɪ˥˩ pi˨˩˦", "syllable_count": 2, "sentences": [{"text": "对比两个城市，差别很大。", "target_word": "对比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家对比了两种水的成分。", "target_word": "对比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把中文和英文对比，会有新发现。", "target_word": "对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们对比新旧产品的质量。", "target_word": "对比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对比一下就知道哪个更好。", "target_word": "对比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生对比两个故事的结尾。", "target_word": "对比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生对比了病人前后的检查结果。", "target_word": "对比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们对比过很多种品牌。", "target_word": "对比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对比这两张图，你能看出什么？", "target_word": "对比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一边看一边对比着价格。", "target_word": "对比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对比了", "label": "体标"}, {"form": "对比过", "label": "体标"}, {"form": "对比着", "label": "体标"}, {"form": "对比度", "label": "复合"}], "register": "中性", "sense_fingerprint": "把两种事物放在一起比较以看出差别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1214d3e9-5c7a-47b4-bed0-11150dfe4c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92344, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对比", "is_correct": true, "explanation": "正确答案。“对比”指把两个城市放在一起看差别。"}, {"text": "烧", "is_correct": false, "explanation": "语义：城市不能用来烧，句子意思荒谬。"}, {"text": "养", "is_correct": false, "explanation": "搭配：“养”不能带“城市”作宾语，搭配不当。"}, {"text": "闻", "is_correct": false, "explanation": "语义：闻城市无法看出差别，句子读不通。"}], "explanations": {"对比": "正确答案。“对比”指把两个城市放在一起看差别。", "烧": "语义：城市不能用来烧，句子意思荒谬。", "养": "搭配：“养”不能带“城市”作宾语，搭配不当。", "闻": "语义：闻城市无法看出差别，句子读不通。"}, "sentence_index": 0, "correct_answer": "对比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "导游对比了这座古城。", "explanation": "这里应该用〈介绍〉。对比要把两样东西放在一起看差别，介绍一座古城不用「对比」。"}, {"text": "护士对比了那个病人。", "explanation": "这里应该用〈照顾〉。对比不能只针对一个人，照顾病人要说「照顾」。"}, {"text": "她对比了一首歌。", "explanation": "这里应该用〈演唱〉。对比要求两样以上的东西，演唱一首歌不能说「对比」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对比", "is_correct": true, "explanation": "正确答案。“对比”指把病人前后的检查结果放在一起比较。"}, {"text": "吃", "is_correct": false, "explanation": "语义：检查结果不能吃，句子读不通。"}, {"text": "喝", "is_correct": false, "explanation": "语义：检查结果不能喝，句子意思荒谬。"}, {"text": "跳", "is_correct": false, "explanation": "配价：“跳”是不及物动词，不能带“检查结果”作宾语。"}], "explanations": {"对比": "正确答案。“对比”指把病人前后的检查结果放在一起比较。", "吃": "语义：检查结果不能吃，句子读不通。", "喝": "语义：检查结果不能喝，句子意思荒谬。", "跳": "配价：“跳”是不及物动词，不能带“检查结果”作宾语。"}, "sentence_index": 6, "correct_answer": "对比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对比了一台电脑。", "explanation": "这里应该用〈购买〉。对比要两样东西放在一起看，只针对一台电脑时不能用「对比」。"}, {"text": "他对比了房间。", "explanation": "这里应该用〈打扫〉。对比需要两样东西，只有一个房间时不能说「对比房间」。"}, {"text": "他对比了蜡烛。", "explanation": "这里应该用〈点燃〉。对比不用于只有一支蜡烛的动作，应说「点燃」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们对比了出两款手机的差别。", "corrected_sentence": "他们对比出了两款手机的差别。", "error_description": "语序错误。「出」应紧跟「对比」，说「对比出」，「了」放在「出」之后，「对比了出」不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们对比不到这两种药的区别。", "corrected_sentence": "我们对比不出这两种药的区别。", "error_description": "补语错误。可能补语的否定形式应是「对比不出」，用「出」表示看出差别；「对比不到」不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92351, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "聚", "is_correct": true, "explanation": "正确：「聚」指聚拢，与「散」指人群走开的义项相反。"}, {"text": "吃", "is_correct": false, "explanation": "「吃」指进食，与「散」没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "「写」指书写文字，与「散」没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "「唱」指发出歌声，与「散」没有反义关系。"}], "correct_answer": "聚", "explanations": {"聚": "正确：「聚」指聚拢，与「散」指人群走开的义项相反。", "吃": "「吃」指进食，与「散」没有反义关系。", "写": "「写」指书写文字，与「散」没有反义关系。", "唱": "「唱」指发出歌声，与「散」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92351, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "聚集", "is_correct": true, "explanation": "正确：「聚集」指人或物集中到一起，与「散」指人群走开的义项相反。"}, {"text": "吹", "is_correct": false, "explanation": "「吹」指风或口气的流动，与「散」没有反义关系。"}, {"text": "挂", "is_correct": false, "explanation": "「挂」指悬挂，与「散」没有反义关系。"}, {"text": "亮", "is_correct": false, "explanation": "「亮」指发光或明白，与「散」没有反义关系。"}], "correct_answer": "聚集", "explanations": {"聚集": "正确：「聚集」指人或物集中到一起，与「散」指人群走开的义项相反。", "吹": "「吹」指风或口气的流动，与「散」没有反义关系。", "挂": "「挂」指悬挂，与「散」没有反义关系。", "亮": "「亮」指发光或明白，与「散」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92351, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "聚在一起的人走开了。", "primary_collocate": null, "pronunciation": "sàn", "ipa": "san˥˩", "syllable_count": 1, "sentences": [{"text": "会开完了，大家都散了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影结束后，看电影的人慢慢散了。", "target_word": "散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，广场上的人都散了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下课铃一响，学生们就散了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚会结束了，客人们都散了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛完了，球迷们很快就散了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨下大了，街上的人一下子就散了。", "target_word": "散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等人都散了，老师才离开教室。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演出一结束，观众就散了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃完饭，朋友们都散了，我才回家。", "target_word": "散", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "散了", "label": "体标"}, {"form": "散场", "label": "复合"}, {"form": "散会", "label": "复合"}], "register": "中性", "sense_fingerprint": "聚在一起的人群离开、各自走开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '074eb1d9-d5d2-4422-9990-2487466d07f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92351, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "散", "is_correct": true, "explanation": "正确：散（sàn，第四声），指聚在一起的人走开。"}, {"text": "三", "is_correct": false, "explanation": "sān（第一声）与 sàn（第四声）声调不同，意思是数字三。"}, {"text": "赞", "is_correct": false, "explanation": "zàn 与 sàn 声母不同（z 与 s），意思是称赞。"}, {"text": "慢", "is_correct": false, "explanation": "màn 与 sàn 声母不同（m 与 s），意思是速度低。"}, {"text": "看", "is_correct": false, "explanation": "kàn 与 sàn 声母不同（k 与 s），意思是看。"}], "explanations": {"散": "正确：散（sàn，第四声），指聚在一起的人走开。", "三": "sān（第一声）与 sàn（第四声）声调不同，意思是数字三。", "赞": "zàn 与 sàn 声母不同（z 与 s），意思是称赞。", "慢": "màn 与 sàn 声母不同（m 与 s），意思是速度低。", "看": "kàn 与 sàn 声母不同（k 与 s），意思是看。"}, "sentence_index": null, "correct_answer": "散"}, "level_3": {"options": [{"text": "散", "is_correct": true, "explanation": "正确：「大家都散了」指聚在一起的人走开，符合「会开完了」的语境。"}, {"text": "聚", "is_correct": false, "explanation": "语义：「聚」指聚拢，与「会开完了」之后人群离开的情景相反。"}, {"text": "解", "is_correct": false, "explanation": "搭配：「解」单用时不能指人群散去，要说「解散」。"}, {"text": "挤", "is_correct": false, "explanation": "语义：「挤」指拥挤推搡，与会议结束后大家离开的情景不合。"}], "explanations": {"散": "正确：「大家都散了」指聚在一起的人走开，符合「会开完了」的语境。", "聚": "语义：「聚」指聚拢，与「会开完了」之后人群离开的情景相反。", "解": "搭配：「解」单用时不能指人群散去，要说「解散」。", "挤": "语义：「挤」指拥挤推搡，与会议结束后大家离开的情景不合。"}, "sentence_index": 0, "correct_answer": "散"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下课以后，他一个人很快就散了。", "explanation": "这里应该用〈离开〉。散指聚在一起的一群人各自走开，单独一人离开不说散，要说离开。"}, {"text": "下课铃一响，学生们就散了教室。", "explanation": "这里应该用〈离开〉。散不带处所宾语，不能说「散了教室」；人从某处走开要说离开。"}, {"text": "保安很快就把人群散了。", "explanation": "这里应该用〈驱散〉。散表示聚在一起的人自行走开，不能用「把」加人群宾语表示外力使其散去；外力赶走人群要说驱散。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92351, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "散", "is_correct": true, "explanation": "正确：散（sàn，第四声），指聚在一起的人走开。"}, {"text": "伞", "is_correct": false, "explanation": "sǎn（第三声）与 sàn（第四声）声调不同，意思是雨伞。"}, {"text": "饭", "is_correct": false, "explanation": "fàn 与 sàn 声母不同（f 与 s），意思是米饭。"}, {"text": "半", "is_correct": false, "explanation": "bàn 与 sàn 声母不同（b 与 s），意思是一半。"}, {"text": "善", "is_correct": false, "explanation": "shàn 与 sàn 声母不同（sh 与 s），意思是善良。"}, {"text": "战", "is_correct": false, "explanation": "zhàn 与 sàn 声母不同（zh 与 s），意思是战斗。"}], "explanations": {"散": "正确：散（sàn，第四声），指聚在一起的人走开。", "伞": "sǎn（第三声）与 sàn（第四声）声调不同，意思是雨伞。", "饭": "fàn 与 sàn 声母不同（f 与 s），意思是米饭。", "半": "bàn 与 sàn 声母不同（b 与 s），意思是一半。", "善": "shàn 与 sàn 声母不同（sh 与 s），意思是善良。", "战": "zhàn 与 sàn 声母不同（zh 与 s），意思是战斗。"}, "sentence_index": null, "correct_answer": "散"}, "level_3": {"options": [{"text": "散", "is_correct": true, "explanation": "正确：「街上的人一下子就散了」指人群迅速走开，符合「雨下大了」的语境。"}, {"text": "集", "is_correct": false, "explanation": "语义：「集」指聚集，与「一下子就……了」描写的人群走开相反。"}, {"text": "游", "is_correct": false, "explanation": "语义：「游」指游泳或游玩，雨天街上的人不会「游」开。"}, {"text": "凑", "is_correct": false, "explanation": "搭配：「凑」通常说「凑在一起」，单说「一下子就凑了」不成句。"}], "explanations": {"散": "正确：「街上的人一下子就散了」指人群迅速走开，符合「雨下大了」的语境。", "集": "语义：「集」指聚集，与「一下子就……了」描写的人群走开相反。", "游": "语义：「游」指游泳或游玩，雨天街上的人不会「游」开。", "凑": "搭配：「凑」通常说「凑在一起」，单说「一下子就凑了」不成句。"}, "sentence_index": 6, "correct_answer": "散"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校宣布散社团，同学们都很难过。", "explanation": "这里应该用〈解散〉。散表示聚在一起的人自行走开，不能用「宣布散」让团体解散；使团体解散要说解散。"}, {"text": "吃完饭，大家都散到一起聊天。", "explanation": "这里应该用〈聚〉。散指聚在一起的人走开、分开，不能表示向一处集中；大家往一处集合要说聚。"}, {"text": "放学后，学生们都散家了。", "explanation": "这里应该用〈回〉。散不带处所宾语，不能说「散家」；人回到某处要用回。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92351, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下课以后，学生们散很快。", "corrected_sentence": "下课以后，学生们散得很快。", "error_description": "错误形式是「学生们散很快」，正确应为「学生们散得很快」。「散」后面要用「得」引出程度补语，漏掉「得」不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92351, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把学生们散了。", "corrected_sentence": "老师把学生们赶散了。", "error_description": "错误形式是「老师把学生们散了」，正确应为「老师把学生们赶散了」。「散」作结果补语，需要「赶」说明使人分开的动作，缺少「赶」不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
