INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92352, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "由聚集而分开；分离。", "primary_collocate": null, "pronunciation": "sàn", "ipa": "san˥˩", "syllable_count": 1, "sentences": [{"text": "早上的雾慢慢散了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天上的云都散了，太阳出来了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗户开着，房间里的烟很快就散了。", "target_word": "散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，花香就散了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨停以后，天上的黑云散了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房的味道一会儿就散了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热气慢慢散了，汤不烫了。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雾还没有散，路上看不清。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湖上的水汽散了，能看见对岸了。", "target_word": "散", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等雾散了，我们再出发。", "target_word": "散", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "散了", "label": "体标"}, {"form": "散开", "label": "复合"}, {"form": "散去", "label": "复合"}], "register": "中性", "sense_fingerprint": "云、雾、烟、气味等聚在一起的东西分开、消失", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '074eb1d9-d5d2-4422-9990-2487466d07f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92352, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "散", "is_correct": true, "explanation": "正确：散（sàn，第四声），指由聚到分、分开消失。"}, {"text": "伞", "is_correct": false, "explanation": "sǎn（第三声）与 sàn（第四声）声调不同，意思是雨伞。"}, {"text": "饭", "is_correct": false, "explanation": "fàn 与 sàn 声母不同（f 与 s），意思是米饭。"}, {"text": "半", "is_correct": false, "explanation": "bàn 与 sàn 声母不同（b 与 s），意思是一半。"}, {"text": "善", "is_correct": false, "explanation": "shàn 与 sàn 声母不同（sh 与 s），意思是善良。"}], "explanations": {"散": "正确：散（sàn，第四声），指由聚到分、分开消失。", "伞": "sǎn（第三声）与 sàn（第四声）声调不同，意思是雨伞。", "饭": "fàn 与 sàn 声母不同（f 与 s），意思是米饭。", "半": "bàn 与 sàn 声母不同（b 与 s），意思是一半。", "善": "shàn 与 sàn 声母不同（sh 与 s），意思是善良。"}, "sentence_index": null, "correct_answer": "散"}, "level_3": {"options": [{"text": "散", "is_correct": true, "explanation": "正确：「雾慢慢散了」指雾由聚而分、消失，符合句意。"}, {"text": "洒", "is_correct": false, "explanation": "搭配：「洒」多指液体或粉末撒落，不说「雾洒了」。"}, {"text": "飞", "is_correct": false, "explanation": "语义：「飞」强调迅速，与句中「慢慢」矛盾，雾不会「飞」走。"}, {"text": "吹", "is_correct": false, "explanation": "配价：「吹」需要施事（如风），单说「雾慢慢吹了」缺少施事，不成立。"}], "explanations": {"散": "正确：「雾慢慢散了」指雾由聚而分、消失，符合句意。", "洒": "搭配：「洒」多指液体或粉末撒落，不说「雾洒了」。", "飞": "语义：「飞」强调迅速，与句中「慢慢」矛盾，雾不会「飞」走。", "吹": "配价：「吹」需要施事（如风），单说「雾慢慢吹了」缺少施事，不成立。"}, "sentence_index": 0, "correct_answer": "散"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在汤里散了一点盐。", "explanation": "这里应该用〈撒〉。撒指把盐、糖之类细碎的东西放开、洒开；散用于云雾、气味等由聚而分，不用于撒调料。"}, {"text": "雨停以后，地上的积水慢慢散了。", "explanation": "这里应该用〈退〉。散用于云雾、气味等由聚而分，积水慢慢消去要说退；「散」不用于积水。"}, {"text": "一阵大风很快就散了这场雾。", "explanation": "这里应该用〈驱散〉。散是不及物用法，云雾自己分开，不能带宾语「这场雾」；要表示外力使其分开，用〈驱散〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92352, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "散", "is_correct": true, "explanation": "正确：散（sàn，第四声），指由聚到分、分开消失。"}, {"text": "三", "is_correct": false, "explanation": "sān（第一声）与 sàn（第四声）声调不同，意思是数字三。"}, {"text": "赞", "is_correct": false, "explanation": "zàn 与 sàn 声母不同（z 与 s），意思是称赞。"}, {"text": "慢", "is_correct": false, "explanation": "màn 与 sàn 声母不同（m 与 s），意思是速度低。"}, {"text": "看", "is_correct": false, "explanation": "kàn 与 sàn 声母不同（k 与 s），意思是看。"}, {"text": "战", "is_correct": false, "explanation": "zhàn 与 sàn 声母不同（zh 与 s），意思是战斗。"}], "explanations": {"散": "正确：散（sàn，第四声），指由聚到分、分开消失。", "三": "sān（第一声）与 sàn（第四声）声调不同，意思是数字三。", "赞": "zàn 与 sàn 声母不同（z 与 s），意思是称赞。", "慢": "màn 与 sàn 声母不同（m 与 s），意思是速度低。", "看": "kàn 与 sàn 声母不同（k 与 s），意思是看。", "战": "zhàn 与 sàn 声母不同（zh 与 s），意思是战斗。"}, "sentence_index": null, "correct_answer": "散"}, "level_3": {"options": [{"text": "散", "is_correct": true, "explanation": "正确：「热气慢慢散了」指热气由聚而分、消失，与「汤不烫了」相符。"}, {"text": "燃", "is_correct": false, "explanation": "语义：「燃」指燃烧起火，热气不会燃烧，句子不成立。"}, {"text": "扇", "is_correct": false, "explanation": "配价：「扇」需要施事去扇动某物，单说「热气慢慢扇了」缺少施事。"}, {"text": "浇", "is_correct": false, "explanation": "搭配：「浇」的对象是水等液体，不说「浇热气」。"}], "explanations": {"散": "正确：「热气慢慢散了」指热气由聚而分、消失，与「汤不烫了」相符。", "燃": "语义：「燃」指燃烧起火，热气不会燃烧，句子不成立。", "扇": "配价：「扇」需要施事去扇动某物，单说「热气慢慢扇了」缺少施事。", "浇": "搭配：「浇」的对象是水等液体，不说「浇热气」。"}, "sentence_index": 6, "correct_answer": "散"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天气一暖，地上的雪很快就散了。", "explanation": "这里应该用〈化〉。散指云雾、气味等由聚而分，雪由固态变成水要说化；散不用于雪的融化。"}, {"text": "这杯茶放了一夜，水都散了。", "explanation": "这里应该用〈蒸发〉。水分变成水汽跑掉要说蒸发；散用于云雾、气味等由聚而分，不能用来描述液体蒸发。"}, {"text": "一阵风把烟散了。", "explanation": "这里应该用〈吹散〉。散不带受事宾语直接搭配「把」，不能说「把烟散了」；要表示风施加作用，需用〈吹散〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风把花香散了。", "corrected_sentence": "风把花香吹散了。", "error_description": "错误形式是「风把花香散了」，正确应为「风把花香吹散了」。「散」作结果补语，需要「吹」说明使花香分开的动作，缺少「吹」不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "太阳出来以后，烟散很快。", "corrected_sentence": "太阳出来以后，烟散得很快。", "error_description": "错误形式是「烟散很快」，正确应为「烟散得很快」。「散」后面要用「得」引出程度补语，漏掉「得」不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92357, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆", "is_correct": true, "explanation": "正确：「拆」指拆除建筑，与「新建」盖起建筑的义项相反。"}, {"text": "写", "is_correct": false, "explanation": "「写」指书写文字，与「新建」没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "「唱」指发出歌声，与「新建」没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "「吃」指进食，与「新建」没有反义关系。"}], "correct_answer": "拆", "explanations": {"拆": "正确：「拆」指拆除建筑，与「新建」盖起建筑的义项相反。", "写": "「写」指书写文字，与「新建」没有反义关系。", "唱": "「唱」指发出歌声，与「新建」没有反义关系。", "吃": "「吃」指进食，与「新建」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
