INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92357, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "新盖起来。", "primary_collocate": null, "pronunciation": "xīn jiàn", "ipa": "ɕin˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他在老家新建了一座房子。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河上新建了一座大桥。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这栋楼是去年新建的。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村子东边新建了很多楼房。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们家新建的房子又大又亮。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山下新建了几间木屋。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷想在院子里新建一间小屋。", "target_word": "新建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新建的楼房里住着很多年轻人。", "target_word": "新建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里新建了一个凉亭。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座新建的塔有五十米高。", "target_word": "新建", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "新建了", "label": "体标"}, {"form": "新建过", "label": "体标"}], "register": "中性", "sense_fingerprint": "新盖起房屋、桥梁、塔等实体建筑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '074eb1d9-d5d2-4422-9990-2487466d07f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92357, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "新建", "is_correct": true, "explanation": "正确：新建（xīn jiàn），指新盖起来。"}, {"text": "亲见", "is_correct": false, "explanation": "qīnjiàn 与 xīnjiàn 第一个音节声母不同（q 与 x），意思是亲眼看见。"}, {"text": "新片", "is_correct": false, "explanation": "xīnpiàn 与 xīnjiàn 第二个音节声母不同（p 与 j），意思是新上映的影片。"}, {"text": "新教", "is_correct": false, "explanation": "xīnjiào 与 xīnjiàn 第二个音节韵母不同（ao 与 an），意思是基督教新教。"}, {"text": "新店", "is_correct": false, "explanation": "xīndiàn 与 xīnjiàn 第二个音节声母不同（d 与 j），意思是新开的店。"}], "explanations": {"新建": "正确：新建（xīn jiàn），指新盖起来。", "亲见": "qīnjiàn 与 xīnjiàn 第一个音节声母不同（q 与 x），意思是亲眼看见。", "新片": "xīnpiàn 与 xīnjiàn 第二个音节声母不同（p 与 j），意思是新上映的影片。", "新教": "xīnjiào 与 xīnjiàn 第二个音节韵母不同（ao 与 an），意思是基督教新教。", "新店": "xīndiàn 与 xīnjiàn 第二个音节声母不同（d 与 j），意思是新开的店。"}, "sentence_index": null, "correct_answer": "新建"}, "level_3": {"options": [{"text": "新建", "is_correct": true, "explanation": "正确：「他在老家新建了一座房子」指新盖起房子，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，不说「吃了一座房子」。"}, {"text": "读", "is_correct": false, "explanation": "搭配：「读」的对象是文字，不说「读了一座房子」。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」指发出歌声，与盖房子无关，不成立。"}], "explanations": {"新建": "正确：「他在老家新建了一座房子」指新盖起房子，符合句意。", "吃": "搭配：「吃」的对象是食物，不说「吃了一座房子」。", "读": "搭配：「读」的对象是文字，不说「读了一座房子」。", "唱": "语义：「唱」指发出歌声，与盖房子无关，不成立。"}, "sentence_index": 0, "correct_answer": "新建"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村子东边新建了很多旧楼房。", "explanation": "这里应该用〈拆〉。新建指新盖起来，不能用于已有的旧楼房；拆掉旧楼房要说拆。"}, {"text": "他们很快就新建了一棵树。", "explanation": "这里应该用〈种〉。新建指盖起房屋、桥梁等建筑，树不是建筑，要说种。"}, {"text": "村里新建了几间老木屋。", "explanation": "这里应该用〈修复〉。新建指新盖起来，老木屋已经存在，不能说新建；修理旧房子要用修复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
