INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92358, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "新建", "is_correct": true, "explanation": "正确：新建（xīn jiàn），指新近建造或设立。"}, {"text": "信件", "is_correct": false, "explanation": "xìnjiàn 与 xīnjiàn 第一个音节声调不同，意思是信件。"}, {"text": "亲见", "is_correct": false, "explanation": "qīnjiàn 与 xīnjiàn 第一个音节声母不同（q 与 x），意思是亲眼看见。"}, {"text": "新片", "is_correct": false, "explanation": "xīnpiàn 与 xīnjiàn 第二个音节声母不同（p 与 j），意思是新上映的影片。"}, {"text": "新店", "is_correct": false, "explanation": "xīndiàn 与 xīnjiàn 第二个音节声母不同（d 与 j），意思是新开的店。"}], "explanations": {"新建": "正确：新建（xīn jiàn），指新近建造或设立。", "信件": "xìnjiàn 与 xīnjiàn 第一个音节声调不同，意思是信件。", "亲见": "qīnjiàn 与 xīnjiàn 第一个音节声母不同（q 与 x），意思是亲眼看见。", "新片": "xīnpiàn 与 xīnjiàn 第二个音节声母不同（p 与 j），意思是新上映的影片。", "新店": "xīndiàn 与 xīnjiàn 第二个音节声母不同（d 与 j），意思是新开的店。"}, "sentence_index": null, "correct_answer": "新建"}, "level_3": {"options": [{"text": "新建", "is_correct": true, "explanation": "正确：「市里新建了一所小学」指市里新近建造了学校，符合句意。"}, {"text": "写", "is_correct": false, "explanation": "搭配：「写」的对象是文字，不能说「写了一所小学」。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」指进食，与建造学校无关，不成立。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」的对象是歌曲，不能说「唱了一所小学」。"}], "explanations": {"新建": "正确：「市里新建了一所小学」指市里新近建造了学校，符合句意。", "写": "搭配：「写」的对象是文字，不能说「写了一所小学」。", "吃": "语义：「吃」指进食，与建造学校无关，不成立。", "唱": "搭配：「唱」的对象是歌曲，不能说「唱了一所小学」。"}, "sentence_index": 0, "correct_answer": "新建"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校新建了老图书馆。", "explanation": "这里应该用〈翻修〉。新建指从无到有地建造或设立，不能用于已有的老图书馆；修整旧建筑要用翻修。"}, {"text": "他每天晚上都新建一首歌。", "explanation": "这里应该用〈创作〉。新建指建造或设立房屋、机构等实体，不能用于音乐作品；写歌要说创作。"}, {"text": "学校新建了一场比赛。", "explanation": "这里应该用〈举办〉。新建指建造或设立机构、设施，比赛不是设施，要用举办。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92358, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "新建", "is_correct": true, "explanation": "正确：新建（xīn jiàn），指新近建造或设立。"}, {"text": "心间", "is_correct": false, "explanation": "xīnjiān 与 xīnjiàn 第二个音节声调不同（jiān 与 jiàn），意思是心里。"}, {"text": "信笺", "is_correct": false, "explanation": "xìnjiān 与 xīnjiàn 两个音节声调都不同，意思是写信用的纸。"}, {"text": "新教", "is_correct": false, "explanation": "xīnjiào 与 xīnjiàn 第二个音节韵母不同（ao 与 an），意思是基督教新教。"}], "explanations": {"新建": "正确：新建（xīn jiàn），指新近建造或设立。", "心间": "xīnjiān 与 xīnjiàn 第二个音节声调不同（jiān 与 jiàn），意思是心里。", "信笺": "xìnjiān 与 xīnjiàn 两个音节声调都不同，意思是写信用的纸。", "新教": "xīnjiào 与 xīnjiàn 第二个音节韵母不同（ao 与 an），意思是基督教新教。"}, "sentence_index": null, "correct_answer": "新建"}, "level_3": {"options": [{"text": "新建", "is_correct": true, "explanation": "正确：「他们新建了一个小组」指新近组建了小组，符合「专门做研究」的语境。"}, {"text": "读", "is_correct": false, "explanation": "搭配：「读」的对象是书报或文字，不说「读了一个小组」。"}, {"text": "修", "is_correct": false, "explanation": "搭配：「修」多用于修理器物或建筑，不能修「小组」。"}, {"text": "织", "is_correct": false, "explanation": "语义：「织」指用线编织，与组建小组无关，不成立。"}], "explanations": {"新建": "正确：「他们新建了一个小组」指新近组建了小组，符合「专门做研究」的语境。", "读": "搭配：「读」的对象是书报或文字，不说「读了一个小组」。", "修": "搭配：「修」多用于修理器物或建筑，不能修「小组」。", "织": "语义：「织」指用线编织，与组建小组无关，不成立。"}, "sentence_index": 6, "correct_answer": "新建"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校新建了原来的教学楼。", "explanation": "这里应该用〈扩建〉。「原来的」说明楼已存在，新建指从无到有地建造，不能用于已有的楼；扩大已有建筑要用扩建。"}, {"text": "他很快就新建了一个句子。", "explanation": "这里应该用〈造〉。新建指建造或设立房屋、机构等实体，不能用于句子；用词语组成句子要说造。"}, {"text": "学校新建了三十名新生。", "explanation": "这里应该用〈招收〉。新建指建造或设立机构、设施，不能用于人；招收学生要用招收。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92358, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市里刚很新建了一所小学。", "corrected_sentence": "市里刚新建了一所小学。", "error_description": "错误形式是「市里刚很新建了一所小学」，正确应为「市里刚新建了一所小学」。「新建」是动作动词，不能用程度副词「很」修饰，应去掉「很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92358, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所小学是去年新建了。", "corrected_sentence": "这所小学是去年新建的。", "error_description": "错误形式是「这所小学是去年新建了」，正确应为「这所小学是去年新建的」。「是……的」句式强调动作的时间，「新建」后要用「的」，不用「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
