INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92359, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "成了是原来不是，现在变成了。", "primary_collocate": null, "pronunciation": "chéng le", "ipa": "ʈʂʰɤŋ˧˥ lɤ", "syllable_count": 2, "sentences": [{"text": "他成了我的好朋友。", "target_word": "成了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑了，路灯成了唯一的光。", "target_word": "成了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她小时候想当医生，现在成了老师。", "target_word": "成了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雨让马路成了小河。", "target_word": "成了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟长大了，成了高个子。", "target_word": "成了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小店成了城里有名的地方。", "target_word": "成了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过去的朋友，现在成了陌生人。", "target_word": "成了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里以前是农田，现在成了一个小区。", "target_word": "成了", "complexity_tier": "T3", "furigana": "zhè lǐ yǐ qián shì nóng tián, xiàn zài chéng le yí gè xiǎo qū", "sentence_source": "generated"}, {"text": "他很快成了班里的第一名。", "target_word": "成了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机成了人们生活的一部分。", "target_word": "成了", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "成", "label": "原形"}, {"form": "成不了", "label": "否定可能"}], "register": "中性", "sense_fingerprint": "原来不是，现在变成了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1214d3e9-5c7a-47b4-bed0-11150dfe4c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92359, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "成了", "is_correct": true, "explanation": "正确答案：成了（chéng le）。"}, {"text": "长了", "is_correct": false, "explanation": "cháng（第二声）与 chéng 元音不同（a 与 e），意思是长（头发长了）。"}, {"text": "沉了", "is_correct": false, "explanation": "chén 与 chéng 韵尾不同（n 与 ng），意思是沉（船沉了）。"}, {"text": "撑了", "is_correct": false, "explanation": "chēng（第一声）与 chéng（第二声）声调不同，意思是撑（撑了一下）。"}], "explanations": {"成了": "正确答案：成了（chéng le）。", "长了": "cháng（第二声）与 chéng 元音不同（a 与 e），意思是长（头发长了）。", "沉了": "chén 与 chéng 韵尾不同（n 与 ng），意思是沉（船沉了）。", "撑了": "chēng（第一声）与 chéng（第二声）声调不同，意思是撑（撑了一下）。"}, "sentence_index": null, "correct_answer": "成了"}, "level_3": {"options": [{"text": "成了", "is_correct": true, "explanation": "正确：「成了」表示由不是变成是，与「我的好朋友」这一身份变化相合。"}, {"text": "吃了", "is_correct": false, "explanation": "搭配：「吃」不能带「好朋友」作宾语。"}, {"text": "喝了", "is_correct": false, "explanation": "搭配：「喝」不能带人作宾语，与「我的好朋友」不搭配。"}, {"text": "闻了", "is_correct": false, "explanation": "语义：「闻了」指用鼻子嗅，把「好朋友」当作嗅的对象，句子荒谬。"}], "explanations": {"成了": "正确：「成了」表示由不是变成是，与「我的好朋友」这一身份变化相合。", "吃了": "搭配：「吃」不能带「好朋友」作宾语。", "喝了": "搭配：「喝」不能带人作宾语，与「我的好朋友」不搭配。", "闻了": "语义：「闻了」指用鼻子嗅，把「好朋友」当作嗅的对象，句子荒谬。"}, "sentence_index": 0, "correct_answer": "成了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直成了我的好朋友。", "explanation": "这里应该用〈是〉。「成了」表示变化的结果，不能与「一直」连用，应说「他一直是我的好朋友」。"}, {"text": "大雨让马路成了三米。", "explanation": "这里应该用〈加宽〉之类表示宽度变化的词。「成了」表示变成某种事物，不能直接接数量作结果。"}, {"text": "大雨让马路成了这场雨。", "explanation": "这里应该用〈形成〉。「成了」的宾语应是变化后的新事物，「这场雨」是原因，不能作结果，应说「大雨形成了一条小河」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92359, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "成了", "is_correct": true, "explanation": "正确答案：成了（chéng le）。"}, {"text": "缠了", "is_correct": false, "explanation": "chán 与 chéng 韵尾不同（an 与 eng），意思是缠（缠了很久）。"}, {"text": "尝了", "is_correct": false, "explanation": "cháng 与 chéng 元音不同（a 与 e），意思是尝（尝了一口）。"}, {"text": "疼了", "is_correct": false, "explanation": "téng 与 chéng 声母不同（t 与 ch），意思是疼（疼了一下）。"}], "explanations": {"成了": "正确答案：成了（chéng le）。", "缠了": "chán 与 chéng 韵尾不同（an 与 eng），意思是缠（缠了很久）。", "尝了": "cháng 与 chéng 元音不同（a 与 e），意思是尝（尝了一口）。", "疼了": "téng 与 chéng 声母不同（t 与 ch），意思是疼（疼了一下）。"}, "sentence_index": null, "correct_answer": "成了"}, "level_3": {"options": [{"text": "成了", "is_correct": true, "explanation": "正确：「成了」表示原来的朋友现在变成了陌生人。"}, {"text": "保持", "is_correct": false, "explanation": "搭配：「保持」应接状态或距离，不能直接带「陌生人」作宾语。"}, {"text": "恢复", "is_correct": false, "explanation": "语义：「恢复」表示回到原来的状态，与「过去的朋友」之后的变化方向相反。"}, {"text": "维持", "is_correct": false, "explanation": "语义：「维持」表示保持不变，与「现在」所表示的变化相矛盾。"}], "explanations": {"成了": "正确：「成了」表示原来的朋友现在变成了陌生人。", "保持": "搭配：「保持」应接状态或距离，不能直接带「陌生人」作宾语。", "恢复": "语义：「恢复」表示回到原来的状态，与「过去的朋友」之后的变化方向相反。", "维持": "语义：「维持」表示保持不变，与「现在」所表示的变化相矛盾。"}, "sentence_index": 6, "correct_answer": "成了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "手机成了人们生活的一场比赛。", "explanation": "这里应该用〈参加〉。「成了」表示变化或事情办成，不能用比赛这类活动作宾语，应说「参加比赛」。"}, {"text": "手机成了人们生活的三年。", "explanation": "这里应该用〈过〉。「成了」不表示时间流逝，不能接时段作宾语，应说「过了三年」。"}, {"text": "手机成了人们生活的很重要。", "explanation": "这里应该用〈变得〉。「成了」后不直接接形容词作补语，应说「变得很重要」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92359, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块木头后来成着一张桌子。", "corrected_sentence": "这块木头后来成了一张桌子。", "error_description": "体标误用：「成着」表示持续状态，不表示由不是变成是的结果，此处应用「成了」。「了」改为「着」是唯一的错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92359, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书出版后，他成了了一名作家。", "corrected_sentence": "这本书出版后，他成了一名作家。", "error_description": "「成了了」应为「成了」：「了」只用一个，多出的「了」不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
