INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92371, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "所属是归在某个地方或某个人的。", "primary_collocate": null, "pronunciation": "suǒ shǔ", "ipa": "swɔ˨˩ ʂu˨˩", "syllable_count": 2, "sentences": [{"text": "请写出你所属的班级。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店所属的公司在上海。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明所属的球队今天赢了。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个学生都有自己所属的小组。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公司所属的研究所在南京。", "target_word": "所属", "complexity_tier": "T3", "furigana": "zhè ge gōngsī suǒshǔ de yánjiūsuǒ zài Nánjīng", "sentence_source": "generated"}, {"text": "你所属的部门在哪一层？", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位运动员所属的俱乐部很有名。", "target_word": "所属", "complexity_tier": "T3", "furigana": "zhè wèi yùndòngyuán suǒshǔ de jùlèbù hěn yǒumíng", "sentence_source": "generated"}, {"text": "这个公园所属的区在城北。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在所属的学院里很受欢迎。", "target_word": "所属", "complexity_tier": "T3", "furigana": "tā zài suǒshǔ de xuéyuàn lǐ hěn shòu huānyíng", "sentence_source": "generated"}, {"text": "这家医院所属的大学在上海。", "target_word": "所属", "complexity_tier": "T3", "furigana": "zhè jiā yīyuàn suǒshǔ de dàxué zài Shànghǎi", "sentence_source": "generated"}], "morphological_forms": [{"form": "所属部门", "label": "复合"}, {"form": "所属单位", "label": "复合"}, {"form": "所屬", "label": "繁体"}], "register": "书面", "sense_fingerprint": "所属:归在某地或某人名下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71448ad7-633e-46ca-9bd3-7ed98c22466a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92371, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所属", "is_correct": true, "explanation": "所属：归在某个班级名下，符合句意。"}, {"text": "擅长", "is_correct": false, "explanation": "搭配：“擅长”后接技能，不能修饰班级。"}, {"text": "冒犯", "is_correct": false, "explanation": "语义：“冒犯”指得罪人，不能用于班级。"}, {"text": "驾驭", "is_correct": false, "explanation": "搭配：“驾驭”搭配局面、技术，不能用于班级。"}], "explanations": {"所属": "所属：归在某个班级名下，符合句意。", "擅长": "搭配：“擅长”后接技能，不能修饰班级。", "冒犯": "语义：“冒犯”指得罪人，不能用于班级。", "驾驭": "搭配：“驾驭”搭配局面、技术，不能用于班级。"}, "sentence_index": 0, "correct_answer": "所属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每个学生都有自己所属的生日。", "explanation": "这里误把〈所属〉当成〈属于〉用。所属只用于某人或某物归在某个组织、单位名下，如“所属的小组”；生日是个人的属性，不能说“所属的生日”。"}, {"text": "这张桌子所属的颜色很好看。", "explanation": "这里误把〈所属〉当成〈属于〉用。所属只能指归在组织或单位名下，颜色是桌子的属性，应说“这张桌子的颜色”，不能说“所属的颜色”。"}, {"text": "我们班所属的天气很好。", "explanation": "这里误把〈所属〉当成〈属于〉用。天气不能归在班级名下，所属只用于归在组织或单位中的人或事物，应说“我们班的天气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92371, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所属", "is_correct": true, "explanation": "所属：归属某个俱乐部，符合句意。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“烹饪”搭配食物，俱乐部不能被烹饪。"}, {"text": "驱逐", "is_correct": false, "explanation": "语义：“驱逐”指赶走人或势力，不能用于俱乐部。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”的对象是物体或人，俱乐部不能被咬。"}], "explanations": {"所属": "所属：归属某个俱乐部，符合句意。", "烹饪": "搭配：“烹饪”搭配食物，俱乐部不能被烹饪。", "驱逐": "语义：“驱逐”指赶走人或势力，不能用于俱乐部。", "咬": "搭配：“咬”的对象是物体或人，俱乐部不能被咬。"}, "sentence_index": 6, "correct_answer": "所属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间教室所属的声音很大。", "explanation": "这里误把〈所属〉当成〈属于〉用。所属只用于某人或某物归在组织、单位名下，声音是教室的属性，应说“这间教室的声音”。"}, {"text": "这条河所属的味道很香。", "explanation": "这里误把〈所属〉当成〈属于〉用。所属只能指归在组织或单位名下，味道是河的属性，应说“这条河的味道”。"}, {"text": "这次考试所属的时间很短。", "explanation": "这里误把〈所属〉当成〈属于〉用。所属只用于归在组织或单位名下，考试的时间是考试本身的属性，应说“这次考试的时间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92371, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家医院所属了的大学很有名。", "corrected_sentence": "这家医院所属的大学很有名。", "error_description": "错在“了”的位置。“所属”后接“了”再带“的”做定语，很不自然；应说“所属的大学”，不说“所属了的大学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92371, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小组的所属哪个部门？", "corrected_sentence": "这个小组所属哪个部门？", "error_description": "多出了“的”。“所属”是动词，前面不能加“的”，应说“这个小组所属哪个部门”，不说“这个小组的所属哪个部门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
