INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92372, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "所隶属的；归属。", "primary_collocate": null, "pronunciation": "suǒ shǔ", "ipa": "swɔ˨˩ ʂu˨˩", "syllable_count": 2, "sentences": [{"text": "请填写你所属的单位。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机构所属的部门是教育局。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他所属的公司很有名。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道这所学校所属的系统。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个医生都要写清楚所属医院。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂所属的集团很大。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请说明你所属的部门。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她所属的团队做得很好。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所属单位的电话是多少？", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个车队所属的公司换了。", "target_word": "所属", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所属部门", "label": "复合"}, {"form": "所属单位", "label": "复合"}, {"form": "所屬", "label": "繁体"}], "register": "书面", "sense_fingerprint": "所属:所隶属的机构或单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71448ad7-633e-46ca-9bd3-7ed98c22466a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EX