INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92372, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所属", "is_correct": true, "explanation": "所属：隶属于某个单位，符合句意。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”搭配的是物体表面，单位不能被擦。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”搭配食物，单位不能被煮。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：“驱赶”指赶走人或动物，不能用于单位。"}], "explanations": {"所属": "所属：隶属于某个单位，符合句意。", "擦": "搭配：“擦”搭配的是物体表面，单位不能被擦。", "煮": "搭配：“煮”搭配食物，单位不能被煮。", "驱赶": "语义：“驱赶”指赶走人或动物，不能用于单位。"}, "sentence_index": 0, "correct_answer": "所属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我不知道这所学校所属的年龄。", "explanation": "这里误把〈所属〉当成〈属于〉用。所属只用于归在单位或系统名下，年龄是人或事物的属性，不能说“所属的年龄”。"}, {"text": "我不知道这所学校所属的脾气。", "explanation": "这里误把〈所属〉当成〈属于〉用。所属只用于归在单位或系统名下，脾气是性格的属性，不能说“所属的脾气”。"}, {"text": "我不知道这所学校所属的味道。", "explanation": "这里误把〈所属〉当成〈属于〉用。所属只用于归在单位或系统名下，味道是事物的属性，不能说“所属的味道”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
