INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92383, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "摆是把东西一个一个放好。", "primary_collocate": null, "pronunciation": "bǎi", "ipa": "paɪ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他把玩具一个一个摆在地上。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先摆碗，你再摆筷子。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友在桌上摆了一排小汽车。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开饭前，爸爸把菜摆好了。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把鞋子摆得很整齐。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的小摊摆着各种水果。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把花瓶摆在窗户旁边。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师摆了五把椅子在前面。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢把照片摆在床边。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商场里摆满了过年用的东西。", "target_word": "摆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摆了", "label": "体标"}, {"form": "摆着", "label": "体标"}, {"form": "摆过", "label": "体标"}, {"form": "摆放", "label": "复合"}, {"form": "擺", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把东西一个一个放好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1214d3e9-5c7a-47b4-bed0-11150dfe4c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92383, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "摆", "is_correct": true, "explanation": "摆读 bǎi，第三声，意思是把东西一个一个安放好。"}, {"text": "败", "is_correct": false, "explanation": "bài 与 bǎi 声调不同，意思是失败，与安放无关。"}, {"text": "北", "is_correct": false, "explanation": "běi 与 bǎi 韵母不同（ei 与 ai），意思是北方。"}, {"text": "把", "is_correct": false, "explanation": "bǎ 与 bǎi 韵母不同（缺少 i），意思是拿、握，也用于把字句。"}], "explanations": {"摆": "摆读 bǎi，第三声，意思是把东西一个一个安放好。", "败": "bài 与 bǎi 声调不同，意思是失败，与安放无关。", "北": "běi 与 bǎi 韵母不同（ei 与 ai），意思是北方。", "把": "bǎ 与 bǎi 韵母不同（缺少 i），意思是拿、握，也用于把字句。"}, "sentence_index": null, "correct_answer": "摆"}, "level_3": {"options": [{"text": "摆", "is_correct": true, "explanation": "“摆”表示把玩具一个一个安放在地上，与“一个一个”的动作相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能与玩具和地面搭配，句子不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”是发出歌声，不能用来安放玩具，句子不通。"}, {"text": "撒", "is_correct": false, "explanation": "语义：“撒”指散落，与“一个一个”的有序安放相反。"}], "explanations": {"摆": "“摆”表示把玩具一个一个安放在地上，与“一个一个”的动作相符。", "吃": "搭配：“吃”的对象是食物，不能与玩具和地面搭配，句子不通。", "唱": "搭配：“唱”是发出歌声，不能用来安放玩具，句子不通。", "撒": "语义：“撒”指散落，与“一个一个”的有序安放相反。"}, "sentence_index": 0, "correct_answer": "摆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钥匙摆进口袋里。", "explanation": "这里应该用〈放进〉。摆指在平面或一定位置排列，放入口袋这样的容器要用“放”。"}, {"text": "他把头发摆短了。", "explanation": "这里应该用〈剪〉。摆指安放或排列，不能表示把头发剪短。"}, {"text": "他把饭菜摆进嘴里。", "explanation": "这里应该用〈吃〉。摆指按次序放在一定位置，不能表示把食物送进嘴里吃掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92383, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "摆", "is_correct": true, "explanation": "摆读 bǎi，第三声，意思是把东西安放在一定位置。"}, {"text": "拜", "is_correct": false, "explanation": "bài 与 bǎi 声调不同，意思是拜访或拜谢。"}, {"text": "板", "is_correct": false, "explanation": "bǎn 与 bǎi 韵尾不同（n 与 i），意思是木板。"}, {"text": "买", "is_correct": false, "explanation": "mǎi 与 bǎi 声母不同（m 与 b），意思是购买。"}], "explanations": {"摆": "摆读 bǎi，第三声，意思是把东西安放在一定位置。", "拜": "bài 与 bǎi 声调不同，意思是拜访或拜谢。", "板": "bǎn 与 bǎi 韵尾不同（n 与 i），意思是木板。", "买": "mǎi 与 bǎi 声母不同（m 与 b），意思是购买。"}, "sentence_index": null, "correct_answer": "摆"}, "level_3": {"options": [{"text": "摆", "is_correct": true, "explanation": "“摆”表示把花瓶安放在窗户旁边，与“请把花瓶……在窗户旁边”相符。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿动作，与安放花瓶无关。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”用于清洁物品，不能说“洗在窗户旁边”。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热食物，与安放花瓶的动作无关。"}], "explanations": {"摆": "“摆”表示把花瓶安放在窗户旁边，与“请把花瓶……在窗户旁边”相符。", "咬": "语义：“咬”是用牙齿动作，与安放花瓶无关。", "洗": "搭配：“洗”用于清洁物品，不能说“洗在窗户旁边”。", "煮": "语义：“煮”是加热食物，与安放花瓶的动作无关。"}, "sentence_index": 6, "correct_answer": "摆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把茶摆进杯子里。", "explanation": "这里应该用〈倒〉。摆指按次序放在一定位置，不能表示把液体注入容器。"}, {"text": "他把纸摆进垃圾桶里。", "explanation": "这里应该用〈扔〉。摆指安放或排列，不能表示把东西丢弃。"}, {"text": "他摆了一个噩梦。", "explanation": "这里应该用〈做〉。摆指安放或排列，不能表示做梦；做噩梦要用做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCL