INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92383, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把书一本一本摆了在桌上。", "corrected_sentence": "他把书一本一本摆在桌上。", "error_description": "“了”位置错误：“摆”后接处所时用“在”，动态助词“了”不能插在“摆”和“在”之间，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92383, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把相框摆得在床头。", "corrected_sentence": "他把相框摆在床头。", "error_description": "“得”误加：“摆”后直接接处所要用“在”，“得”须接程度或状态补语，“摆得在床头”不通，应去掉“得”，即“摆在床头”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92384, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收", "is_correct": true, "explanation": "收与摆在“安放、整理”义上构成反义：摆出去，收起来。"}, {"text": "跑", "is_correct": false, "explanation": "跑是移动动作，与“安放”不构成反义。"}, {"text": "唱", "is_correct": false, "explanation": "唱是发声动作，与“安放”没有反义关系。"}, {"text": "笑", "is_correct": false, "explanation": "笑是表情动作，与“安放”不在反义关系中。"}], "correct_answer": "收", "explanations": {"收": "收与摆在“安放、整理”义上构成反义：摆出去，收起来。", "跑": "跑是移动动作，与“安放”不构成反义。", "唱": "唱是发声动作，与“安放”没有反义关系。", "笑": "笑是表情动作，与“安放”不在反义关系中。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
