INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92385, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "公共汽车、船这些，每天开着载人赚钱。", "primary_collocate": null, "pronunciation": "yíng yùn", "ipa": "iŋ˧˥ yn˥˩", "syllable_count": 2, "sentences": [{"text": "这辆公共汽车每天营运十二个小时。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条船每天营运两趟，一趟坐三十人。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧公共汽车还在营运。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共汽车天一亮就开始营运。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渡船每天早上七点开始营运。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的小船只在夏天营运。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车营运了五年，该换新的了。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上十点以后，公共汽车不营运了。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河上有三条船在营运。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的小巴士一年四季都营运。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "营运了", "label": "体标"}, {"form": "营运着", "label": "体标"}, {"form": "营运车辆", "label": "复合"}], "register": "书面", "sense_fingerprint": "公共汽车、船等每天开着载客赚钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e81304c3-911e-48ff-b4ba-3e9273962e3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92385, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "营运", "is_correct": true, "explanation": "营运（yíng yùn）：公共汽车、船等每天开着载人赚钱，即本词。"}, {"text": "营业", "is_correct": false, "explanation": "营业（yíng yè）后一音节 yè 与 yùn 韵母不同，意思是做生意、开门营业。"}, {"text": "营养", "is_correct": false, "explanation": "营养（yíng yǎng）后一音节 yǎng 与 yùn 韵母和声调都不同，意思是人体所需的养分。"}, {"text": "命运", "is_correct": false, "explanation": "命运（mìng yùn）前一音节 mìng 与 yíng 声母不同、声调也不同，意思是人的遭遇。"}, {"text": "幸运", "is_correct": false, "explanation": "幸运（xìng yùn）前一音节 xìng 与 yíng 声母不同、声调也不同，意思是运气好。"}, {"text": "盈余", "is_correct": false, "explanation": "盈余（yíng yú）后一音节 yú 与 yùn 韵母和声调不同，意思是收入超过支出的部分。"}], "explanations": {"营运": "营运（yíng yùn）：公共汽车、船等每天开着载人赚钱，即本词。", "营业": "营业（yíng yè）后一音节 yè 与 yùn 韵母不同，意思是做生意、开门营业。", "营养": "营养（yíng yǎng）后一音节 yǎng 与 yùn 韵母和声调都不同，意思是人体所需的养分。", "命运": "命运（mìng yùn）前一音节 mìng 与 yíng 声母不同、声调也不同，意思是人的遭遇。", "幸运": "幸运（xìng yùn）前一音节 xìng 与 yíng 声母不同、声调也不同，意思是运气好。", "盈余": "盈余（yíng yú）后一音节 yú 与 yùn 韵母和声调不同，意思是收入超过支出的部分。"}, "sentence_index": null, "correct_answer": "营运"}, "level_3": {"options": [{"text": "营运", "is_correct": true, "explanation": "正确：公共汽车每天开着载人赚钱，与“每天…十二个小时”相合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：公共汽车不会睡觉，与句中载人运营的意思不合。"}, {"text": "复习", "is_correct": false, "explanation": "配价：“复习”的主语须是人，公共汽车不能复习。"}, {"text": "写作业", "is_correct": false, "explanation": "搭配：公共汽车不写作业，“写作业”与车辆不搭配。"}], "explanations": {"营运": "正确：公共汽车每天开着载人赚钱，与“每天…十二个小时”相合。", "睡觉": "语义：公共汽车不会睡觉，与句中载人运营的意思不合。", "复习": "配价：“复习”的主语须是人，公共汽车不能复习。", "写作业": "搭配：公共汽车不写作业，“写作业”与车辆不搭配。"}, "sentence_index": 0, "correct_answer": "营运"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆公共汽车每天营运三十箱货物。", "explanation": "这里应该用〈运送〉。营运指载人赚钱，不能带“货物”作宾语。"}, {"text": "老师天一亮就开始营运。", "explanation": "这里应该用〈上课〉。营运的主语应是车或船，不能用人作主语。"}, {"text": "这盏灯每晚营运到十二点。", "explanation": "这里应该用〈亮〉。营运只指车船载人运营，灯不能说营运。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92385, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "营运", "is_correct": true, "explanation": "正确：“营运了五年”指车辆运营了五年，与“该换新的了”相合。"}, {"text": "喝", "is_correct": false, "explanation": "语义：车不能喝东西，“喝了五年”与句意不合。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：车辆不会游泳，“游泳了五年”与车辆不搭。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”的主体须是有生命的人或动物，“这辆车”不能散步。"}], "explanations": {"营运": "正确：“营运了五年”指车辆运营了五年，与“该换新的了”相合。", "喝": "语义：车不能喝东西，“喝了五年”与句意不合。", "游泳": "搭配：车辆不会游泳，“游泳了五年”与车辆不搭。", "散步": "配价：“散步”的主体须是有生命的人或动物，“这辆车”不能散步。"}, "sentence_index": 6, "correct_answer": "营运"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵大树一年四季都营运。", "explanation": "这里应该用〈生长〉。营运只用于车船和机构，不能用于树。"}, {"text": "警察一年四季都营运。", "explanation": "这里应该用〈站岗〉。营运的主语是车船或机构，不能用人作主语。"}, {"text": "发动机一直在营运。", "explanation": "这里应该用〈运转〉。营运用于车船和机构，发动机应说“运转”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92385, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这艘渡船每天被营运十个小时。", "corrected_sentence": "这艘渡船每天营运十个小时。", "error_description": "“营运”是不及物动词，不能用“被”字句。应说“每天营运十个小时”，不说“每天被营运十个小时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92385, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆小巴士营运了着三年。", "corrected_sentence": "这辆小巴士营运了三年。", "error_description": "体标错误：“了”和“着”不能叠用在同一个动词后。应说“营运了三年”，不说“营运了着三年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92386, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92386, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92386, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "运输工具运行，载客载货以取得收入；也指机构的经营运作。", "primary_collocate": null, "pronunciation": "yíng yùn", "ipa": "iŋ˧˥ yn˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司的新线路下个月开始营运。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条地铁线路每天从早到晚营运。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家船公司已经营运了十年。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家连锁书店营运得很稳，没有亏钱。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司营运得很好，今年赚了不少钱。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商场营运了三年，一直不赚钱。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机坏了，这条航线只好停止营运。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥修好后，新线路马上开始营运。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打算明年扩大营运的范围。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新船开始营运以后，游客多了很多。", "target_word": "营运", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "营运了", "label": "体标"}, {"form": "营运过", "label": "体标"}, {"form": "营运成本", "label": "复合"}, {"form": "营运资金", "label": "复合"}], "register": "书面", "sense_fingerprint": "运输工具载客载货取得收入的运行，也指机构的经营运作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e81304c3-911e-48ff-b4ba-3e9273962e3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92386, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "营运", "is_correct": true, "explanation": "营运（yíng yùn）：运输工具运行、载客载货取得收入，或机构的经营运作，即本词。"}, {"text": "营业", "is_correct": false, "explanation": "营业（yíng yè）后一音节 yè 与 yùn 韵母不同，意思是做生意、开门营业。"}, {"text": "营养", "is_correct": false, "explanation": "营养（yíng yǎng）后一音节 yǎng 与 yùn 韵母和声调都不同，意思是人体所需的养分。"}, {"text": "命运", "is_correct": false, "explanation": "命运（mìng yùn）前一音节 mìng 与 yíng 声母不同、声调也不同，意思是人的遭遇。"}, {"text": "幸运", "is_correct": false, "explanation": "幸运（xìng yùn）前一音节 xìng 与 yíng 声母不同、声调也不同，意思是运气好。"}, {"text": "盈余", "is_correct": false, "explanation": "盈余（yíng yú）后一音节 yú 与 yùn 韵母和声调不同，意思是收入超过支出的部分。"}], "explanations": {"营运": "营运（yíng yùn）：运输工具运行、载客载货取得收入，或机构的经营运作，即本词。", "营业": "营业（yíng yè）后一音节 yè 与 yùn 韵母不同，意思是做生意、开门营业。", "营养": "营养（yíng yǎng）后一音节 yǎng 与 yùn 韵母和声调都不同，意思是人体所需的养分。", "命运": "命运（mìng yùn）前一音节 mìng 与 yíng 声母不同、声调也不同，意思是人的遭遇。", "幸运": "幸运（xìng yùn）前一音节 xìng 与 yíng 声母不同、声调也不同，意思是运气好。", "盈余": "盈余（yíng yú）后一音节 yú 与 yùn 韵母和声调不同，意思是收入超过支出的部分。"}, "sentence_index": null, "correct_answer": "营运"}, "level_3": {"options": [{"text": "营运", "is_correct": true, "explanation": "正确：“开始营运”指新线路开始运行，与句意相合。"}, {"text": "停运", "is_correct": false, "explanation": "语义：新线路刚要开通，说“开始停运”与句意矛盾。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：线路是运输服务，不能“装修”，“装修”只搭配房屋等。"}, {"text": "上课", "is_correct": false, "explanation": "配价：“开始上课”要求有学习的人作主语，“线路”不能上课。"}], "explanations": {"营运": "正确：“开始营运”指新线路开始运行，与句意相合。", "停运": "语义：新线路刚要开通，说“开始停运”与句意矛盾。", "装修": "搭配：线路是运输服务，不能“装修”，“装修”只搭配房屋等。", "上课": "配价：“开始上课”要求有学习的人作主语，“线路”不能上课。"}, "sentence_index": 0, "correct_answer": "营运"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司每天营运三十个员工。", "explanation": "这里应该用〈雇用〉。营运不带“员工”作宾语，应说“雇用”。"}, {"text": "这家工厂的机器每天营运八小时。", "explanation": "这里应该用〈运行〉。营运用于运输工具和机构，机器运转应说“运行”。"}, {"text": "我的小猫每天营运到十二点。", "explanation": "这里应该用〈玩〉。营运的主语是运输工具或机构，不能用动物作主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "营运", "is_correct": true, "explanation": "正确：“停止营运”是固定搭配，指航线停止运营。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：航线不能唱歌，与“飞机坏了”的语境不合。"}, {"text": "上学", "is_correct": false, "explanation": "配价：“停止上学”的主语须是学生，航线不能上学。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：航线不能“考试”，“停止考试”与句中的交通情境不搭。"}], "explanations": {"营运": "正确：“停止营运”是固定搭配，指航线停止运营。", "唱歌": "语义：航线不能唱歌，与“飞机坏了”的语境不合。", "上学": "配价：“停止上学”的主语须是学生，航线不能上学。", "考试": "搭配：航线不能“考试”，“停止考试”与句中的交通情境不搭。"}, "sentence_index": 6, "correct_answer": "营运"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂每天营运三百个零件。", "explanation": "这里应该用〈制造〉。营运不带产品作宾语，工厂生产零件应说“制造”。"}, {"text": "护士每晚在医院营运到十二点。", "explanation": "这里应该用〈值班〉。营运的主语是运输工具或机构，不能用人作主语。"}, {"text": "这盏台灯每晚营运到十二点。", "explanation": "这里应该用〈亮〉。营运只用于运输工具和机构，台灯应说“亮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家物流公司的货车全年都被营运。", "corrected_sentence": "这家物流公司的货车全年都在营运。", "error_description": "“营运”是不及物动词，不能用“被”字句。表示正在进行应在动词前用“在”，应说“都在营运”，不说“都被营运”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家航空公司的新航班已经营运了着两个月。", "corrected_sentence": "这家航空公司的新航班已经营运了两个月。", "error_description": "体标错误：“了”和“着”不能叠用在同一个动词后。应说“已经营运了两个月”，不说“已经营运了着两个月”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92387, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "后期", "is_correct": true, "explanation": "后期与早期相对，指某一时期的后一段，是标准反义词。"}, {"text": "花园", "is_correct": false, "explanation": "花园是具体场所，与“早期”没有反义关系。"}, {"text": "墙壁", "is_correct": false, "explanation": "墙壁是具体物体，与“早期”不构成反义。"}, {"text": "夜晚", "is_correct": false, "explanation": "夜晚是一天中的时段，与“早期”不是同一义项，也不构成反义。"}], "correct_answer": "后期", "explanations": {"后期": "后期与早期相对，指某一时期的后一段，是标准反义词。", "花园": "花园是具体场所，与“早期”没有反义关系。", "墙壁": "墙壁是具体物体，与“早期”不构成反义。", "夜晚": "夜晚是一天中的时段，与“早期”不是同一义项，也不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
