INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92387, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "早期是一段时间最前面的那一段。", "primary_collocate": null, "pronunciation": "zǎo qī", "ipa": "tsɑʊ˨˩˦ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "清朝早期，国家很稳定。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早期的电脑要占满一个房间。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个球队早期很弱，后来越来越强。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在工作早期遇到过很多困难。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早期的火车跑得很慢。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病在早期发现，治好的机会更大。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店早期卖衣服，现在卖咖啡。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷早期住在乡下，后期搬到了城里。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唐朝早期，长安已经很热闹。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子学说话的早期，爸爸妈妈要多和他说话。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一段时间最前面的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1214d3e9-5c7a-47b4-bed0-11150dfe4c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92387, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早期", "is_correct": true, "explanation": "早期指一段时间的前段，与“清朝”搭配，说明那一朝代的前段国家稳定。"}, {"text": "夏天", "is_correct": false, "explanation": "搭配：夏天是季节，不能与朝代名组合成时间段。"}, {"text": "周末", "is_correct": false, "explanation": "语义：周末是一周中的时段，与朝代不相容，句子不通。"}, {"text": "大学", "is_correct": false, "explanation": "语义：大学不是朝代的时间段，“清朝大学”无法说明国家状况。"}], "explanations": {"早期": "早期指一段时间的前段，与“清朝”搭配，说明那一朝代的前段国家稳定。", "夏天": "搭配：夏天是季节，不能与朝代名组合成时间段。", "周末": "语义：周末是一周中的时段，与朝代不相容，句子不通。", "大学": "语义：大学不是朝代的时间段，“清朝大学”无法说明国家状况。"}, "sentence_index": 0, "correct_answer": "早期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小吃摊的早期是五点到七点。", "explanation": "这里应该用〈清晨〉。早期指某一时期的前段，不能表示一天中的营业时段；天刚亮的时段要用清晨。"}, {"text": "这次演唱会的早期定在三点。", "explanation": "这里应该用〈午后〉。早期指一段时期的前段，不能指具体钟点；表示下午的时段要用午后。"}, {"text": "孩子们的早期是周末。", "explanation": "这里应该用〈假日〉。早期指某一时期的前段，不能指具体的日子；表示休息的日子要用假日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92387, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早期", "is_correct": true, "explanation": "早期表示这家店经营衣服的前一阶段，与后文“现在卖咖啡”形成对照。"}, {"text": "墙上", "is_correct": false, "explanation": "搭配：“墙上”是位置，不能作“卖衣服”的时间状语。"}, {"text": "海里", "is_correct": false, "explanation": "语义：海里不是时间，“海里卖衣服”与店铺的经营时段无关，句子不通。"}, {"text": "天上", "is_correct": false, "explanation": "语义：天上指空中，与“这家店卖衣服”的经营情况直接矛盾。"}], "explanations": {"早期": "早期表示这家店经营衣服的前一阶段，与后文“现在卖咖啡”形成对照。", "墙上": "搭配：“墙上”是位置，不能作“卖衣服”的时间状语。", "海里": "语义：海里不是时间，“海里卖衣服”与店铺的经营时段无关，句子不通。", "天上": "语义：天上指空中，与“这家店卖衣服”的经营情况直接矛盾。"}, "sentence_index": 6, "correct_answer": "早期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个节目的早期是今晚。", "explanation": "这里应该用〈傍晚〉。早期指某一时期的前段，不能指一天中的时段；表示傍晚时分要用傍晚。"}, {"text": "这次考试的早期定在半夜。", "explanation": "这里应该用〈夜里〉。早期指某一时期的前段，不能指具体钟点；表示夜间时段要用夜里。"}, {"text": "我们的会议早期定在周五上午。", "explanation": "这里应该用〈早上〉。早期指某一时期的前段，不能指具体的时段；表示一天的清晨要用早上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92387, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座小城在早期了很安静。", "corrected_sentence": "这座小城在早期很安静。", "error_description": "“了”误加：“在早期”是整体状语，“早期”后不能接动态助词“了”，应去掉“了”，即“在早期很安静”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92387, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子在学说话早期，需要多听多说。", "corrected_sentence": "孩子在学说话的早期，需要多听多说。", "error_description": "“的”缺失：“学说话”作定语修饰“早期”时要加“的”，应为“学说话的早期”。", "correct_sentence_indices": [6, 7, 8]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
