INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92388, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某一时期中最初的一段时间。", "primary_collocate": null, "pronunciation": "zǎo qī", "ipa": "tsɑʊ˨˩˦ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "这座城市在早期只是一个小村子。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影早期都是黑白的，没有声音。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早期的画很简单，后来才越来越复杂。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病在早期很容易治好。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明朝早期，这里住着很多商人。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司早期只有五个人，现在有五百人了。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早期的手机很大，也很重。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在学习汉字的早期，常常记不住字形。", "target_word": "早期", "complexity_tier": "T3", "furigana": "zǎo qī", "sentence_source": "generated"}, {"text": "这位作家早期写小说，后期写诗。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发现问题要在早期，不要拖到以后。", "target_word": "早期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "某一时期最初的一段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1214d3e9-5c7a-47b4-bed0-11150dfe4c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92388, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早期", "is_correct": true, "explanation": "早期指某一时期的最初一段，与“只是一个小村子”描述的过去状况相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是物体，不能充当时间或地点，“在石头只是一个小村子”不通。"}, {"text": "汽水", "is_correct": false, "explanation": "语义：汽水是饮料，不能充当时间或地点，句子不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不能充当时间或地点，句子不通。"}], "explanations": {"早期": "早期指某一时期的最初一段，与“只是一个小村子”描述的过去状况相符。", "石头": "语义：石头是物体，不能充当时间或地点，“在石头只是一个小村子”不通。", "汽水": "语义：汽水是饮料，不能充当时间或地点，句子不通。", "书包": "语义：书包是物品，不能充当时间或地点，句子不通。"}, "sentence_index": 0, "correct_answer": "早期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的早期是七点到十点。", "explanation": "这里应该用〈早市〉。早期指某一时期的前段，不能表示一天中的营业时段；早上的集市要用早市。"}, {"text": "明天的早期是九点。", "explanation": "这里应该用〈早上〉。早期指某一时期的前段，不能指一天中的具体钟点；表示明天清晨要用早上。"}, {"text": "工厂的早期是六点半开工。", "explanation": "这里应该用〈早班〉。早期表示一段时期，不能指上班的具体时间；表示按时上班的时段要用早班。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92388, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早期", "is_correct": true, "explanation": "早期修饰“手机”，表示手机出现的最初阶段，与“很大，也很重”的特点相符。"}, {"text": "蚂蚁", "is_correct": false, "explanation": "体貌：蚂蚁体形极小，与“很大，也很重”直接矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "语法：“唱”是动词，不能作“手机”的定语，句子不通。"}, {"text": "跑", "is_correct": false, "explanation": "语法：“跑”是动词，不能作“手机”的定语，句子不通。"}], "explanations": {"早期": "早期修饰“手机”，表示手机出现的最初阶段，与“很大，也很重”的特点相符。", "蚂蚁": "体貌：蚂蚁体形极小，与“很大，也很重”直接矛盾。", "唱": "语法：“唱”是动词，不能作“手机”的定语，句子不通。", "跑": "语法：“跑”是动词，不能作“手机”的定语，句子不通。"}, "sentence_index": 6, "correct_answer": "早期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚会的早期定在八点。", "explanation": "这里应该用〈晚上〉。早期指某一时期的前段，不能指具体钟点；表示夜间的时段要用晚上。"}, {"text": "这个项目的早期是三号。", "explanation": "这里应该用〈今天〉。早期指一段时期的前段，不能指某个具体日子；表示当天要用今天。"}, {"text": "这次比赛的早期是中午十二点。", "explanation": "这里应该用〈正午〉。早期指某一时期的前段，不能指具体钟点；表示十二点前后的时刻要用正午。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92388, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那家小店在早期了只有两个店员。", "corrected_sentence": "那家小店在早期只有两个店员。", "error_description": "“了”误加：“在早期”是时间状语，“早期”后不能接动态助词“了”，应去掉“了”，即“在早期只有两个店员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种手机在早期了很贵，后来才便宜。", "corrected_sentence": "这种手机在早期很贵，后来才便宜。", "error_description": "“了”误加：“在早期”是时间状语，“早期”后不能接动态助词“了”，应去掉“了”，即“在早期很贵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c2b66a8-c4b9-40ff-891f-6c7a6746f517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
