INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92441, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "亲自是自己去做，不请别人做。", "primary_collocate": null, "pronunciation": "qīn zì", "ipa": "tɕʰin˥˥ tsɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这件事太重要，我要亲自去做。", "target_word": "亲自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理亲自给客人倒茶。", "target_word": "亲自", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈亲自做了一桌好菜。", "target_word": "亲自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不用送，我亲自去拿就行。", "target_word": "亲自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师亲自带学生去参观工厂。", "target_word": "亲自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不让别人帮忙，亲自搬了箱子。", "target_word": "亲自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这封信是校长亲自写的。", "target_word": "亲自", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "为了买到好茶，爷爷亲自去了山里。", "target_word": "亲自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想亲自看看孩子的新家。", "target_word": "亲自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没请人修，是爸爸亲自修好的。", "target_word": "亲自", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "親自", "label": "繁体"}], "register": "中性", "sense_fingerprint": "副词；自己去做某事，不请别人代替", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71448ad7-633e-46ca-9bd3-7ed98c22466a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92441, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亲自", "is_correct": true, "explanation": "正确。亲自表示本人直接去做，不请别人代替。"}, {"text": "亲子", "is_correct": false, "explanation": "zì（第四声）与 zǐ（第三声）声调不同，亲子意思是父母与子女的关系。"}, {"text": "金字", "is_correct": false, "explanation": "qīn 与 jīn 声母不同（q 与 j），金字意思是“金”字，如“金字招牌”。"}, {"text": "金子", "is_correct": false, "explanation": "qīn 与 jīn 声母不同（q 与 j），且第二个音节为轻声，金子意思是黄金。"}], "explanations": {"亲自": "正确。亲自表示本人直接去做，不请别人代替。", "亲子": "zì（第四声）与 zǐ（第三声）声调不同，亲子意思是父母与子女的关系。", "金字": "qīn 与 jīn 声母不同（q 与 j），金字意思是“金”字，如“金字招牌”。", "金子": "qīn 与 jīn 声母不同（q 与 j），且第二个音节为轻声，金子意思是黄金。"}, "sentence_index": null, "correct_answer": "亲自"}, "level_3": {"options": [{"text": "亲自", "is_correct": true, "explanation": "正确。“我要亲自去做”表示本人动手，与“太重要”的语境一致。"}, {"text": "随便", "is_correct": false, "explanation": "语义：随便表示马虎、不认真，与“这件事太重要”矛盾。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：偶尔表示次数很少，与“我要……去做”的郑重语气不符。"}, {"text": "白白", "is_correct": false, "explanation": "语义：白白表示徒劳无益，与“这件事太重要”的语境相矛盾。"}], "explanations": {"亲自": "正确。“我要亲自去做”表示本人动手，与“太重要”的语境一致。", "随便": "语义：随便表示马虎、不认真，与“这件事太重要”矛盾。", "偶尔": "语义：偶尔表示次数很少，与“我要……去做”的郑重语气不符。", "白白": "语义：白白表示徒劳无益，与“这件事太重要”的语境相矛盾。"}, "sentence_index": 0, "correct_answer": "亲自"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我亲自生病了三天。", "explanation": "这里不能用〈亲自〉。亲自表示本人主动去做，生病不是人能主动去做的事，不能用亲自修饰。"}, {"text": "他亲自摔了一跤。", "explanation": "这里应该用〈不小心〉。摔跤是无意的，亲自表示主动去做，不能修饰无意发生的事。"}, {"text": "我在街上亲自下了一场雨。", "explanation": "这里不能用〈亲自〉。亲自表示由人主动去做，下雨是自然现象，人无法亲自下雨，不能用亲自修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92441, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲自", "is_correct": true, "explanation": "正确。“这封信是校长亲自写的”强调是校长本人写的。"}, {"text": "永远", "is_correct": false, "explanation": "语义：永远表示长久不变，与“写的”这一已完成的动作不搭。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”指一贯如此，与这封信这一次具体的书写不搭，句子别扭。"}, {"text": "乱", "is_correct": false, "explanation": "语义：乱写含随意、潦草之意，与校长郑重写信的身份不符。"}], "explanations": {"亲自": "正确。“这封信是校长亲自写的”强调是校长本人写的。", "永远": "语义：永远表示长久不变，与“写的”这一已完成的动作不搭。", "从来": "语义：“从来”指一贯如此，与这封信这一次具体的书写不搭，句子别扭。", "乱": "语义：乱写含随意、潦草之意，与校长郑重写信的身份不符。"}, "sentence_index": 6, "correct_answer": "亲自"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听到这个消息，他亲自高兴得跳了起来。", "explanation": "这里应该用〈特别〉。亲自表示本人直接去做，不修饰心情；心情应说特别高兴。"}, {"text": "这棵老树亲自长高了不少。", "explanation": "这里应该用〈慢慢〉。亲自要求由人主动去做，树不能亲自长高，应说慢慢长高。"}, {"text": "那次考试，他亲自睡着了。", "explanation": "这里不能用〈亲自〉。亲自强调本人主动去做，睡着不是主动去做的事，不能用亲自修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92441, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈亲自的做饭。", "corrected_sentence": "妈妈亲自做饭。", "error_description": "错误在“亲自”后多了“的”。“亲自”是副词，直接修饰动词，不能加“的”变成定语；这里应说“妈妈亲自做饭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92441, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "王阿姨很亲自下厨做晚饭。", "corrected_sentence": "王阿姨亲自下厨做晚饭。", "error_description": "错误在“亲自”前多了“很”。“亲自”是副词，不能再被“很”修饰，应说“王阿姨亲自下厨做晚饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
