INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92442, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示自己直接去做。", "primary_collocate": null, "pronunciation": "qīn zì", "ipa": "tɕʰin˥˥ tsɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "老板亲自来机场接我们。", "target_word": "亲自", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他亲自打电话告诉了我这个好消息。", "target_word": "亲自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个蛋糕是女儿亲自烤的。", "target_word": "亲自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市长亲自去医院看望病人。", "target_word": "亲自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不放心的话，可以亲自去问他。", "target_word": "亲自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想亲自对他说一声谢谢。", "target_word": "亲自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长亲自把奖杯交给了他。", "target_word": "亲自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题很难，王老师亲自来帮我们了。", "target_word": "亲自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她亲自选了每一件衣服。", "target_word": "亲自", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛那天，爸爸亲自开车送我去学校。", "target_word": "亲自", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "親自", "label": "繁体"}], "register": "中性", "sense_fingerprint": "副词；表示动作由本人直接去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71448ad7-633e-46ca-9bd3-7ed98c22466a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92442, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亲自", "is_correct": true, "explanation": "正确。亲自表示本人直接去做，不请别人代替。"}, {"text": "亲子", "is_correct": false, "explanation": "zì（第四声）与 zǐ（第三声）声调不同，亲子意思是父母与子女的关系。"}, {"text": "金字", "is_correct": false, "explanation": "qīn 与 jīn 声母不同（q 与 j），金字意思是“金”字，如“金字招牌”。"}, {"text": "金子", "is_correct": false, "explanation": "qīn 与 jīn 声母不同（q 与 j），且第二个音节为轻声，金子意思是黄金。"}], "explanations": {"亲自": "正确。亲自表示本人直接去做，不请别人代替。", "亲子": "zì（第四声）与 zǐ（第三声）声调不同，亲子意思是父母与子女的关系。", "金字": "qīn 与 jīn 声母不同（q 与 j），金字意思是“金”字，如“金字招牌”。", "金子": "qīn 与 jīn 声母不同（q 与 j），且第二个音节为轻声，金子意思是黄金。"}, "sentence_index": null, "correct_answer": "亲自"}, "level_3": {"options": [{"text": "亲自", "is_correct": true, "explanation": "正确。“老板亲自来机场接我们”表示老板本人前来，语境自然。"}, {"text": "随便", "is_correct": false, "explanation": "语义：随便表示马虎、不认真，与老板郑重来机场接客人的语境不符。"}, {"text": "白白", "is_correct": false, "explanation": "语义：白白表示徒劳无益，与“来机场接我们”的语境不符。"}, {"text": "乱", "is_correct": false, "explanation": "搭配：“乱”多与“跑”“说”等搭配表示混乱，不能说“老板乱来机场接我们”。"}], "explanations": {"亲自": "正确。“老板亲自来机场接我们”表示老板本人前来，语境自然。", "随便": "语义：随便表示马虎、不认真，与老板郑重来机场接客人的语境不符。", "白白": "语义：白白表示徒劳无益，与“来机场接我们”的语境不符。", "乱": "搭配：“乱”多与“跑”“说”等搭配表示混乱，不能说“老板乱来机场接我们”。"}, "sentence_index": 0, "correct_answer": "亲自"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我亲自感冒了三天。", "explanation": "这里不能用〈亲自〉。亲自表示本人主动去做，感冒不是人能主动去做的事，不能用亲自修饰。"}, {"text": "我在车站亲自下了一场雪。", "explanation": "这里不能用〈亲自〉。亲自指由人主动去做，下雪是自然现象，人无法亲自下雪，不能用亲自修饰。"}, {"text": "听到这个消息，他亲自高兴得跳了起来。", "explanation": "这里应该用〈特别〉。亲自表示本人直接去做，不修饰心情；心情应说特别高兴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92442, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲自", "is_correct": true, "explanation": "正确。“校长亲自把奖杯交给了他”表示校长本人颁发，语境自然。"}, {"text": "永远", "is_correct": false, "explanation": "语义：永远表示长久不变，与“交给了他”这一次性动作不搭。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”指一贯如此，与校长这一次具体的交付不符，句子别扭。"}, {"text": "反复", "is_correct": false, "explanation": "语义：反复表示多次重复，与“交给了他”这一次性动作不符。"}], "explanations": {"亲自": "正确。“校长亲自把奖杯交给了他”表示校长本人颁发，语境自然。", "永远": "语义：永远表示长久不变，与“交给了他”这一次性动作不搭。", "从来": "语义：“从来”指一贯如此，与校长这一次具体的交付不符，句子别扭。", "反复": "语义：反复表示多次重复，与“交给了他”这一次性动作不符。"}, "sentence_index": 6, "correct_answer": "亲自"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵小树亲自长高了一截。", "explanation": "这里应该用〈慢慢〉。亲自要求由人主动去做，树不能亲自长高，应说慢慢长高。"}, {"text": "那场比赛，他亲自迷路了。", "explanation": "这里不能用〈亲自〉。亲自强调本人主动去做，迷路不是主动去做的事，不能用亲自修饰。"}, {"text": "他亲自打了一个大喷嚏，把大家都吓了一跳。", "explanation": "这里不能用〈亲自〉。亲自表示本人主动去做某事，打喷嚏是不由自主发生的，不能用亲自修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厂长很亲自去车间检查。", "corrected_sentence": "厂长亲自去车间检查。", "error_description": "错误在“亲自”前多了“很”。“亲自”是副词，不能再被“很”修饰，应说“厂长亲自去车间检查”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "王阿姨亲自的做了晚饭。", "corrected_sentence": "王阿姨亲自做了晚饭。", "error_description": "错误在“亲自”后多了“的”。“亲自”是副词，直接修饰动词，不能加“的”变成定语；这里应说“王阿姨亲自做了晚饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
