INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92449, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "工作以后，还回去学新本事。", "primary_collocate": null, "pronunciation": "jì xù jiào yù", "ipa": "tɕi˥˩ ɕy˥˩ tɕjɑʊ˥˩ y˥˩", "syllable_count": 4, "sentences": [{"text": "工作以后，她还参加了继续教育。", "target_word": "继续教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去上继续教育，学一点新本事。", "target_word": "继续教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司让每个人每年都上继续教育。", "target_word": "继续教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他白天上班，晚上上继续教育。", "target_word": "继续教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "继续教育让我学会了做网页。", "target_word": "继续教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸五十岁还去上继续教育。", "target_word": "继续教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家学校有很多继续教育的课。", "target_word": "继续教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做了十年老师，又去上继续教育。", "target_word": "继续教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加继续教育要花很多时间。", "target_word": "继续教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "继续教育对找新工作很有帮助。", "target_word": "继续教育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "继续教育课程", "label": "复合"}, {"form": "继续教育学院", "label": "复合"}], "register": "中性", "sense_fingerprint": "参加工作以后再回去学习新本事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e81304c3-911e-48ff-b4ba-3e9273962e3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92449, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "继续教育", "is_correct": true, "explanation": "正确：“继续教育”指工作以后补充学习，与“工作以后”相符。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：“参加”后应接活动或培训，不说“参加学校”。"}, {"text": "学位", "is_correct": false, "explanation": "搭配：“参加”接活动或考试，学位是获得的，不说“参加学位”。"}, {"text": "初中", "is_correct": false, "explanation": "搭配：“参加”不接学段名称，应说“上初中”，且与“工作以后”不符。"}], "explanations": {"继续教育": "正确：“继续教育”指工作以后补充学习，与“工作以后”相符。", "学校": "搭配：“参加”后应接活动或培训，不说“参加学校”。", "学位": "搭配：“参加”接活动或考试，学位是获得的，不说“参加学位”。", "初中": "搭配：“参加”不接学段名称，应说“上初中”，且与“工作以后”不符。"}, "sentence_index": 0, "correct_answer": "继续教育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所小学为孩子们提供免费的继续教育。", "explanation": "这里应该用〈义务教育〉。继续教育面向已参加工作的人，不用于在小学读书的孩子。"}, {"text": "刚出生的婴儿就开始接受继续教育。", "explanation": "这里应该用〈早教〉。继续教育面向已参加工作的人，婴儿的教育应说早教。"}, {"text": "幼儿园的孩子每天都在接受继续教育。", "explanation": "这里应该用〈学前教育〉。继续教育面向已参加工作的人，幼儿园的孩子应说学前教育。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92449, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "继续教育", "is_correct": true, "explanation": "正确：“继续教育”是学校开设的课程，与“学校有很多……的课”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能开课，与“学校有很多……的课”矛盾。"}, {"text": "饭店", "is_correct": false, "explanation": "搭配：“……的课”的修饰语应是教学内容，不说“饭店的课”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是课程的内容，与“学校有很多……的课”矛盾。"}], "explanations": {"继续教育": "正确：“继续教育”是学校开设的课程，与“学校有很多……的课”相符。", "石头": "语义：石头不能开课，与“学校有很多……的课”矛盾。", "饭店": "搭配：“……的课”的修饰语应是教学内容，不说“饭店的课”。", "天气": "语义：天气不是课程的内容，与“学校有很多……的课”矛盾。"}, "sentence_index": 6, "correct_answer": "继续教育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "初中生放学后都去上继续教育。", "explanation": "这里应该用〈课外辅导〉。继续教育面向已参加工作的人，初中生放学后补课应说课外辅导。"}, {"text": "新生入学前要参加继续教育。", "explanation": "这里应该用〈入学教育〉。继续教育是工作以后补充知识，新生入学前应参加入学教育。"}, {"text": "孩子们暑假去继续教育学游泳。", "explanation": "这里应该用〈夏令营〉。继续教育面向已参加工作的人，孩子暑假学游泳应说夏令营。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92449, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年参观了继续教育。", "corrected_sentence": "他去年参加了继续教育。", "error_description": "动词错误：“继续教育”是培训活动，应说“参加”；“参观”用于展览、场所等，不能说“参观继续教育”。原句“参观了继续教育”错在动词，应改为“参加了继续教育”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92449, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他利用周末参加了一本继续教育。", "corrected_sentence": "他利用周末参加了一次继续教育。", "error_description": "量词错误：“继续教育”指一次培训活动，应用量词“次”，不说“本”（“本”用于书籍）。应说“参加了一次继续教育”，不说“参加了一本继续教育”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
