INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92450, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对已经走上工作岗位的人所进行的补充和更新知识技能的教育。", "primary_collocate": null, "pronunciation": "jì xù jiào yù", "ipa": "tɕi˥˩ ɕy˥˩ tɕjɑʊ˥˩ y˥˩", "syllable_count": 4, "sentences": [{"text": "医生每年都要参加继续教育。", "target_word": "继续教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校为在职教师提供继续教育。", "target_word": "继续教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "继续教育可以帮助工作的人更新知识。", "target_word": "继续教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家很重视在职人员的继续教育。", "target_word": "继续教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位工程师通过继续教育提高了技术。", "target_word": "继续教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把继续教育放在重要的位置。", "target_word": "继续教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "继续教育的目的是更新知识和技能。", "target_word": "继续教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士完成继续教育，才能拿到新证书。", "target_word": "继续教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学开办了很多继续教育课程。", "target_word": "继续教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在职人员的继续教育越来越重要。", "target_word": "继续教育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "继续教育课程", "label": "复合"}, {"form": "继续教育学院", "label": "复合"}], "register": "书面", "sense_fingerprint": "面向在职人员、补充和更新知识技能的教育", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e81304c3-911e-48ff-b4ba-3e9273962e3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92450, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "继续教育", "is_correct": true, "explanation": "正确：“继续教育”面向已参加工作的人，与“医生每年”相符。"}, {"text": "高考", "is_correct": false, "explanation": "语义：医生不参加高考，与“医生”矛盾。"}, {"text": "幼儿园", "is_correct": false, "explanation": "搭配：“参加”不接机构名称，不说“参加幼儿园”。"}, {"text": "小学", "is_correct": false, "explanation": "搭配：“参加”不接学段名称，应说“上小学”，且与“医生”不符。"}], "explanations": {"继续教育": "正确：“继续教育”面向已参加工作的人，与“医生每年”相符。", "高考": "语义：医生不参加高考，与“医生”矛盾。", "幼儿园": "搭配：“参加”不接机构名称，不说“参加幼儿园”。", "小学": "搭配：“参加”不接学段名称，应说“上小学”，且与“医生”不符。"}, "sentence_index": 0, "correct_answer": "继续教育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府保障每个孩子都能接受免费的继续教育。", "explanation": "这里应该用〈义务教育〉。继续教育面向已参加工作的人，儿童的免费基础教育应说义务教育。"}, {"text": "新人上岗前，公司要求他们先接受继续教育。", "explanation": "这里应该用〈职前培训〉。继续教育是工作以后补充知识，新人上岗前应接受职前培训。"}, {"text": "幼儿园每天都为孩子们安排继续教育。", "explanation": "这里应该用〈学前教育〉。继续教育面向已参加工作的人，幼儿园的孩子应说学前教育。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92450, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "继续教育", "is_correct": true, "explanation": "正确：“继续教育”的目的是更新知识和技能，与句子相符。"}, {"text": "广告", "is_correct": false, "explanation": "语义：广告的目的是宣传，不是更新知识和技能。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏的目的是娱乐，与“更新知识和技能”矛盾。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“目的”前应接活动或计划，不说“工资的目的”。"}], "explanations": {"继续教育": "正确：“继续教育”的目的是更新知识和技能，与句子相符。", "广告": "语义：广告的目的是宣传，不是更新知识和技能。", "游戏": "语义：游戏的目的是娱乐，与“更新知识和技能”矛盾。", "工资": "搭配：“目的”前应接活动或计划，不说“工资的目的”。"}, "sentence_index": 6, "correct_answer": "继续教育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他暑假去上继续教育，想提高数学成绩。", "explanation": "这里应该用〈补习班〉。继续教育面向已参加工作的人，学生提高成绩应去补习班。"}, {"text": "学校要求新生先参加继续教育。", "explanation": "这里应该用〈入学教育〉。继续教育是工作以后补充知识，新生应先参加入学教育。"}, {"text": "孩子三岁起就接受继续教育。", "explanation": "这里应该用〈早教〉。继续教育面向已参加工作的人，三岁孩子的教育应说早教。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月我们参观了一次继续教育。", "corrected_sentence": "这个月我们参加了一次继续教育。", "error_description": "动词错误：“继续教育”是培训活动，应说“参加”；“参观”用于展览、场所等，不能说“参观继续教育”。原句“参观了一次继续教育”错在动词，应改为“参加了一次继续教育”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年参加完一本继续教育，就升职了。", "corrected_sentence": "他去年参加完一次继续教育，就升职了。", "error_description": "量词错误：“继续教育”指一次培训活动，应用量词“次”，不说“本”（“本”用于书籍）。应说“参加完一次继续教育”，不说“参加完一本继续教育”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
