INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92453, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "话说是讲故事时开头的一句话。", "primary_collocate": null, "pronunciation": "huà shuō", "ipa": "xwa˥˩ ʂwo˥", "syllable_count": 2, "sentences": [{"text": "“话说”是讲故事时常用的开头。", "target_word": "话说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旧小说常用“话说”开头。", "target_word": "话说", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "听评书时，你常能听到“话说”这个词。", "target_word": "话说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他讲故事时，第一句总是“话说”。", "target_word": "话说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书的每一章，都用“话说”开头。", "target_word": "话说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友问：“话说是什么意思？”", "target_word": "话说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“话说”这个开头，让我想起了爷爷。", "target_word": "话说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在的小说里，很少再用“话说”了。", "target_word": "话说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老先生清了清嗓子，说出了那句“话说”。", "target_word": "话说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作文里用“话说”开头，会显得很老派。", "target_word": "话说", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "讲故事时开头的那句话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fda20375-ed58-4eb8-96ba-b11b06ce9777') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92453, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "话说", "is_correct": true, "explanation": "正确。“话说”作名词，指讲故事开头的固定句。"}, {"text": "评书", "is_correct": false, "explanation": "语义：“评书”是一种说书的艺术形式，不是讲故事开头的一句话。"}, {"text": "故事", "is_correct": false, "explanation": "搭配：“故事”是讲述的内容，与“开头”不构成搭配。"}, {"text": "标题", "is_correct": false, "explanation": "语义：“标题”指题目，不指讲故事开头的固定句。"}], "explanations": {"话说": "正确。“话说”作名词，指讲故事开头的固定句。", "评书": "语义：“评书”是一种说书的艺术形式，不是讲故事开头的一句话。", "故事": "搭配：“故事”是讲述的内容，与“开头”不构成搭配。", "标题": "语义：“标题”指题目，不指讲故事开头的固定句。"}, "sentence_index": 0, "correct_answer": "话说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影的话说很精彩。", "explanation": "这里应该用〈故事〉。“话说”只指讲故事开头的固定句，不指故事内容。"}, {"text": "他讲完话说，大家都笑了。", "explanation": "这里应该用〈笑话〉。“话说”是开场语，不能表示讲完的内容。"}, {"text": "这个话说很有道理。", "explanation": "这里应该用〈说法〉。“话说”只指讲故事开头的固定句，不能指一种说法或观点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92453, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "话说", "is_correct": true, "explanation": "正确。““话说”这个开头”指讲故事的开场语。"}, {"text": "口号", "is_correct": false, "explanation": "语义：“口号”指宣传用语，不是讲故事开头的句子。"}, {"text": "段子", "is_correct": false, "explanation": "搭配：“段子”指笑话，与“开头”的搭配不当。"}, {"text": "书名", "is_correct": false, "explanation": "语义：“书名”是书的名字，不是讲故事时的开场语。"}], "explanations": {"话说": "正确。““话说”这个开头”指讲故事的开场语。", "口号": "语义：“口号”指宣传用语，不是讲故事开头的句子。", "段子": "搭配：“段子”指笑话，与“开头”的搭配不当。", "书名": "语义：“书名”是书的名字，不是讲故事时的开场语。"}, "sentence_index": 6, "correct_answer": "话说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老先生的话说很有风格。", "explanation": "这里应该用〈文风〉。“话说”只指讲故事开头的固定句，不指作者的写作特色。"}, {"text": "老人用一张“话说”开头，讲了很久。", "explanation": "量词不对。“张”用于纸张、桌子等，“话说”应用量词“句”。"}, {"text": "这个作家用一条“话说”开头。", "explanation": "量词不对。“条”用于细长的东西，“话说”应用量词“句”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92453, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷讲故事前，总要先说一首“话说”。", "corrected_sentence": "爷爷讲故事前，总要先说一句“话说”。", "error_description": "量词“一首”用于诗歌、歌曲，“话说”作名词指开场的一句话，应用量词“句”。应为“先说一句“话说””。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92453, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些“话说们”都很老派。", "corrected_sentence": "这些“话说”都很老派。", "error_description": "“话说”不是指人的名词，不能加复数词尾“们”。应为“这些“话说”都很老派”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92455, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "中断", "is_correct": true, "explanation": "中断与“续”相对，指事情停下来，不再接着做。"}, {"text": "打开", "is_correct": false, "explanation": "与“续”无反义关系，“打开”指把关着的东西开启。"}, {"text": "收拾", "is_correct": false, "explanation": "与“续”无反义关系，“收拾”指整理、收起。"}, {"text": "唱", "is_correct": false, "explanation": "与“续”无反义关系，“唱”指发出歌声。"}], "correct_answer": "中断", "explanations": {"中断": "中断与“续”相对，指事情停下来，不再接着做。", "打开": "与“续”无反义关系，“打开”指把关着的东西开启。", "收拾": "与“续”无反义关系，“收拾”指整理、收起。", "唱": "与“续”无反义关系，“唱”指发出歌声。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
