INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92455, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "接着往下做，让它不断。", "primary_collocate": null, "pronunciation": "xù", "ipa": "ɕy˥˩", "syllable_count": 1, "sentences": [{"text": "这个故事没写完，你来续下去吧。", "target_word": "续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话断了，我们明天再续上这个话题。", "target_word": "续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者没写完，朋友把这首诗续了两句。", "target_word": "续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火快灭了，他往里加柴，把火续上。", "target_word": "续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他唱到一半忘了词，停了一下又续上了。", "target_word": "续", "complexity_tier": "T3", "furigana": "tā chàng dào yíbàn wàng le cí, tíng le yíxià yòu xù shang le", "sentence_source": "generated"}, {"text": "刚才的话还没说完，我们再续下去吧。", "target_word": "续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个梦很好，我真想再续下去。", "target_word": "续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了上半篇，下半篇由我来续。", "target_word": "续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的缘分，不知道还能不能续下去。", "target_word": "续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的故事你讲完了，我来续一段。", "target_word": "续", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "续了", "label": "体标"}, {"form": "续过", "label": "体标"}, {"form": "续写", "label": "复合"}, {"form": "續", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把中断或没完的事接着做下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fba8654-6602-4f46-b68a-f1451ee604be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92455, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "续", "is_correct": true, "explanation": "正确答案。续（xù）意思是接着往下做。"}, {"text": "去", "is_correct": false, "explanation": "qù（第四声）与 xù 声母不同，意思是离开。"}, {"text": "戏", "is_correct": false, "explanation": "xì（第四声）与 xù 韵母不同，意思是戏剧。"}, {"text": "许", "is_correct": false, "explanation": "xǔ（第三声）与 xù（第四声）声调不同，意思是允许。"}, {"text": "系", "is_correct": false, "explanation": "xì（第四声）与 xù 韵母不同，意思是关系。"}], "explanations": {"续": "正确答案。续（xù）意思是接着往下做。", "去": "qù（第四声）与 xù 声母不同，意思是离开。", "戏": "xì（第四声）与 xù 韵母不同，意思是戏剧。", "许": "xǔ（第三声）与 xù（第四声）声调不同，意思是允许。", "系": "xì（第四声）与 xù 韵母不同，意思是关系。"}, "sentence_index": null, "correct_answer": "续"}, "level_3": {"options": [{"text": "续", "is_correct": true, "explanation": "正确。续在此表示把没写完的故事接着讲下去。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下，与“故事”无关。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”的对象是有形的物件，不能拆故事。"}, {"text": "捡", "is_correct": false, "explanation": "语义：“捡”指拾取东西，与讲故事的语境不合。"}], "explanations": {"续": "正确。续在此表示把没写完的故事接着讲下去。", "吃": "语义：“吃”指把食物咽下，与“故事”无关。", "拆": "搭配：“拆”的对象是有形的物件，不能拆故事。", "捡": "语义：“捡”指拾取东西，与讲故事的语境不合。"}, "sentence_index": 0, "correct_answer": "续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的油价续了两成。", "explanation": "这里应该用〈上涨〉。续表示接着往下做、让它不断，油价的涨幅要用上涨，不能用续。"}, {"text": "他的体重续了两公斤。", "explanation": "这里应该用〈增加〉。续表示接着往下做、让它不断，体重增加要用增加，不能用续。"}, {"text": "这个仓库的存货续了一半。", "explanation": "这里应该用〈减少〉。续表示接着往下做、让它不断，不能用来说存货数量下降。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92455, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "续", "is_correct": true, "explanation": "正确答案。续（xù）意思是接着往下做。"}, {"text": "聚", "is_correct": false, "explanation": "jù（第四声）与 xù 声母不同，意思是聚集。"}, {"text": "具", "is_correct": false, "explanation": "jù（第四声）与 xù 声母不同，意思是工具。"}, {"text": "需", "is_correct": false, "explanation": "xū（第一声）与 xù（第四声）声调不同，意思是需要。"}, {"text": "虚", "is_correct": false, "explanation": "xū（第一声）与 xù（第四声）声调不同，意思是虚假。"}], "explanations": {"续": "正确答案。续（xù）意思是接着往下做。", "聚": "jù（第四声）与 xù 声母不同，意思是聚集。", "具": "jù（第四声）与 xù 声母不同，意思是工具。", "需": "xū（第一声）与 xù（第四声）声调不同，意思是需要。", "虚": "xū（第一声）与 xù（第四声）声调不同，意思是虚假。"}, "sentence_index": null, "correct_answer": "续"}, "level_3": {"options": [{"text": "续", "is_correct": true, "explanation": "正确。续在此表示梦境接着继续下去。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃下去”指继续吃东西，与梦境无关。"}, {"text": "醒", "is_correct": false, "explanation": "配价：“醒”是不及物动词，不能用“醒下去”表示梦境延续。"}, {"text": "睁", "is_correct": false, "explanation": "配价：“睁”的对象是眼睛，不能用“睁下去”表示延续。"}], "explanations": {"续": "正确。续在此表示梦境接着继续下去。", "吃": "语义：“吃下去”指继续吃东西，与梦境无关。", "醒": "配价：“醒”是不及物动词，不能用“醒下去”表示梦境延续。", "睁": "配价：“睁”的对象是眼睛，不能用“睁下去”表示延续。"}, "sentence_index": 6, "correct_answer": "续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班的学费续了两千元。", "explanation": "这里应该用〈提高〉。续表示接着往下做、让它不断，学费的上调要用提高，不能用续。"}, {"text": "库存增加了一百，他续了一百。", "explanation": "这里应该用〈添〉。续表示接着往下做、让它不断，不能用来表示数量的增多，应说“添了一百”。"}, {"text": "这家店的面积续了两百平米。", "explanation": "这里应该用〈扩大〉。续表示接着往下做、让它不断，面积变大要用扩大，不能用续。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92455, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告还没写完，你来续了下去吧。", "corrected_sentence": "这份报告还没写完，你来续下去吧。", "error_description": "祈使句“……吧”里不用完成体“了”，应说“续下去”，去掉“续”后面的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92455, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首曲子很好听，我真想续再下去。", "corrected_sentence": "这首曲子很好听，我真想再续下去。", "error_description": "副词“再”要放在动词“续”的前面，应说“再续下去”，不能放在“续”的后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
