INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92459, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通信是用信或电话，让两个人互相知道消息。", "primary_collocate": null, "pronunciation": "tōng xìn", "ipa": "tʰʊŋ˥ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "我和老同学一直通信。", "target_word": "通信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们两个人每个月通信一次。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候，我常和奶奶通信。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们已经通信三年了。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她和远方的朋友通信很多年了，从没见过面。", "target_word": "通信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸年轻时，常和在外地的哥哥通信。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们只通信，不打电话。", "target_word": "通信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们先通信，后见面。", "target_word": "通信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈和姐姐每星期通信，聊家里的事。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老王和笔友通信二十年，感情很深。", "target_word": "通信", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "通信员", "label": "复合"}, {"form": "通信兵", "label": "复合"}], "register": "中性", "sense_fingerprint": "两个人之间用书信互相联系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fda20375-ed58-4eb8-96ba-b11b06ce9777') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92459, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "通信", "is_correct": true, "explanation": "正确。“通信”指用书信或电话互相联系，与“我和老同学一直……”的往来相符。"}, {"text": "诞生", "is_correct": false, "explanation": "语义：“诞生”指人或事物开始出现，不能和老同学一直相互进行。"}, {"text": "逝世", "is_correct": false, "explanation": "语域：“逝世”是书面的讣告用语，且指死亡，与“老同学一直……”语义冲突。"}, {"text": "降落", "is_correct": false, "explanation": "搭配：“降落”多用于飞机、降落伞，人与人之间不能用它表示往来。"}], "explanations": {"通信": "正确。“通信”指用书信或电话互相联系，与“我和老同学一直……”的往来相符。", "诞生": "语义：“诞生”指人或事物开始出现，不能和老同学一直相互进行。", "逝世": "语域：“逝世”是书面的讣告用语，且指死亡，与“老同学一直……”语义冲突。", "降落": "搭配：“降落”多用于飞机、降落伞，人与人之间不能用它表示往来。"}, "sentence_index": 0, "correct_answer": "通信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天通信了老王，问了一件事。", "explanation": "这里应该用〈联系〉。通信要用“和某人通信”，不能直接带人作宾语；找人询问要用〈联系〉。"}, {"text": "我昨天通信了他明天开会的事。", "explanation": "这里应该用〈通知〉。通信是双方互相传递消息，不能带“开会的事”作宾语；告诉别人某事要用〈通知〉。"}, {"text": "周末我去医院通信奶奶。", "explanation": "这里应该用〈看望〉。通信只表示互相传递消息，不能表示到场探望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92459, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通信", "is_correct": true, "explanation": "正确。“通信”指互相传递消息，与“他们只……，不打电话”的语境相符。"}, {"text": "通话", "is_correct": false, "explanation": "语义：“通话”就是打电话，与后半句“不打电话”直接矛盾。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：“失踪”指人下落不明，与“他们只……”所说的两人之间的交往不相符。"}, {"text": "流血", "is_correct": false, "explanation": "搭配：“流血”不能用于两人之间的交流，句意不通。"}], "explanations": {"通信": "正确。“通信”指互相传递消息，与“他们只……，不打电话”的语境相符。", "通话": "语义：“通话”就是打电话，与后半句“不打电话”直接矛盾。", "失踪": "语义：“失踪”指人下落不明，与“他们只……”所说的两人之间的交往不相符。", "流血": "搭配：“流血”不能用于两人之间的交流，句意不通。"}, "sentence_index": 6, "correct_answer": "通信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在工作中通信了很多经验。", "explanation": "这里应该用〈积累〉。通信指传递消息，不能用来表示长期积累经验。"}, {"text": "他很会通信道理，大家都愿意听。", "explanation": "这里应该用〈讲〉。通信指双方传递消息，不能用来表示讲述道理。"}, {"text": "他每天通信打游戏到凌晨，连饭都忘了吃。", "explanation": "这里应该用〈玩〉。通信指双方传递消息，不能表示玩游戏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92459, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和笔友一直通信得。", "corrected_sentence": "我和笔友一直通信。", "error_description": "动词“通信”后多加了助词“得”。“得”需要补语，句子不完整。删去“得”，应为“我和笔友一直通信。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92459, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们俩每周通信两个。", "corrected_sentence": "我们俩每周通信两次。", "error_description": "“两个”的量词用错，表示次数应用“次”。应为“每周通信两次”，动作次数的量词不能换成“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
