INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92465, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "从那时候起。", "primary_collocate": null, "pronunciation": "zì dǎ", "ipa": "tsɨ˥˩ ta˨˩˦", "syllable_count": 2, "sentences": [{"text": "自打那天起，他再也没迟到过。", "target_word": "自打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自打那以后，我们就成了好朋友。", "target_word": "自打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自打那时候，她就爱上了唱歌。", "target_word": "自打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他搬走了，自打那次，我们没见过面。", "target_word": "自打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自打那年冬天，爷爷不再出门了。", "target_word": "自打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自打那会儿，他就戒酒了。", "target_word": "自打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自打那一刻，我才懂了妈妈的辛苦。", "target_word": "自打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我摔了一跤，自打那回，就怕骑车。", "target_word": "自打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自打那场大雨，小河里就有了水。", "target_word": "自打", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们吵过一架，自打那晚，没再说话。", "target_word": "自打", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "与“那”连用，指从前面提到的那个时间点起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823356df-e298-42d6-83d2-7110f3829571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92465, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自打", "is_correct": true, "explanation": "正确：“自打那天起”指从那一天起，与后面的“再也没迟到过”相符。"}, {"text": "为", "is_correct": false, "explanation": "配价：“为”后要接对象，“为那天起”不成句。"}, {"text": "按照", "is_correct": false, "explanation": "语义：“按照”表示依据，句中说的是从那天起的时间，不是依据。"}, {"text": "凭", "is_correct": false, "explanation": "语义：“凭”表示凭借，“凭那天起”语义不合，句意不通。"}], "explanations": {"自打": "正确：“自打那天起”指从那一天起，与后面的“再也没迟到过”相符。", "为": "配价：“为”后要接对象，“为那天起”不成句。", "按照": "语义：“按照”表示依据，句中说的是从那天起的时间，不是依据。", "凭": "语义：“凭”表示凭借，“凭那天起”语义不合，句意不通。"}, "sentence_index": 0, "correct_answer": "自打"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他气得自打了一下，那一下很重。", "explanation": "这里的“自打”指“自己打”，是动词，与“从那时候起”的介词用法不同。"}, {"text": "我们明天要吵一架，自打那次，就没再见面。", "explanation": "这里应该用〈从〉。“自打”只能引出已经发生的时间起点，“那次”指明天才会发生的事，不能用“自打”引出。"}, {"text": "他们搬走了，自打那张桌子，我们没见过面。", "explanation": "这里应该用〈那次搬家〉。“自打”引出的是时间点或事件，不能引出“那张桌子”这样的事物，应说“自打那次搬家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92465, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自打", "is_correct": true, "explanation": "正确：“自打那一刻”指从那一刻起，与“才懂了妈妈的辛苦”的时间顺序相符。"}, {"text": "替", "is_correct": false, "explanation": "配价：“替”要接表示人的对象，“替那一刻”不成句。"}, {"text": "比", "is_correct": false, "explanation": "配价：“比”要接比较对象，“比那一刻”不能引出时间起点。"}, {"text": "通过", "is_correct": false, "explanation": "语义：“通过”表示经由的途径，那一刻不是途径，“通过那一刻”句意不通。"}], "explanations": {"自打": "正确：“自打那一刻”指从那一刻起，与“才懂了妈妈的辛苦”的时间顺序相符。", "替": "配价：“替”要接表示人的对象，“替那一刻”不成句。", "比": "配价：“比”要接比较对象，“比那一刻”不能引出时间起点。", "通过": "语义：“通过”表示经由的途径，那一刻不是途径，“通过那一刻”句意不通。"}, "sentence_index": 6, "correct_answer": "自打"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们吵过一架，自打那晚，才又开始说话。", "explanation": "这里应该用〈直到〉。“自打”表示从某时起，此处要说到某时为止，应用“直到”。"}, {"text": "他们吵过一架，自打那晚很冷，没再说话。", "explanation": "这里应该用〈从〉。“自打”后要接时间点或事件，“那晚很冷”是状态，不能作起点，应说“从那晚起”。"}, {"text": "他们吵过一架，自打那个人，没再说话。", "explanation": "这里应该用〈那次〉。“自打”引出的是时间点或事件，不能引出人，应说“自打那次吵架”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92465, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "自打在那年冬天起，爷爷就戒了烟。", "corrected_sentence": "自打那年冬天起，爷爷就戒了烟。", "error_description": "多余的介词：“自打”后不能再加“在”，应删去“在”，说“自打那年冬天起”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92465, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "自打在那晚，他就再也没说过话。", "corrected_sentence": "自打那晚，他就再也没说过话。", "error_description": "多余的介词：“自打”后不能再加“在”，应删去“在”，说“自打那晚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
