INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92481, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "客气地说，你想怎么做都可以。", "primary_collocate": null, "pronunciation": "qǐng biàn", "ipa": "tɕʰiŋ˨˩˦ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "你想先走的话，请便。", "target_word": "请便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不介意，你请便吧。", "target_word": "请便", "complexity_tier": "T3", "furigana": "wǒ bú jièyì, nǐ qǐngbiàn ba.", "sentence_source": "generated"}, {"text": "你累了，请便吧，不用陪我。", "target_word": "请便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说：“我还要工作，您请便。”", "target_word": "请便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的书你都可以看，请便。", "target_word": "请便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想吃什么，请便，别客气。", "target_word": "请便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先去洗手间，你们请便。", "target_word": "请便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您要是累了，请便。", "target_word": "请便", "complexity_tier": "T3", "furigana": "nín yàoshi lèi le, qǐngbiàn.", "sentence_source": "generated"}, {"text": "老板笑着说：“您请便，我不打扰。”", "target_word": "请便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不想参加的话，那就请便。", "target_word": "请便", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "客气地让对方按自己的想法去做，常接在“想……就……”之后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e461a86-2103-4f36-87ea-09eaf67ac906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92481, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "请便", "is_correct": true, "explanation": "正确。“你想先走的话，请便”表示让对方自行决定，与句意相合。"}, {"text": "请坐", "is_correct": false, "explanation": "语义：“请坐”是请对方坐下，与“想先走”的意思相反。"}, {"text": "请客", "is_correct": false, "explanation": "语义：“请客”是请人吃饭，放在这里句意不通。"}, {"text": "请示", "is_correct": false, "explanation": "配价：“请示”需要带上请示的对象，单独用在这里不成句。"}], "explanations": {"请便": "正确。“你想先走的话，请便”表示让对方自行决定，与句意相合。", "请坐": "语义：“请坐”是请对方坐下，与“想先走”的意思相反。", "请客": "语义：“请客”是请人吃饭，放在这里句意不通。", "请示": "配价：“请示”需要带上请示的对象，单独用在这里不成句。"}, "sentence_index": 0, "correct_answer": "请便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请便，洗手间在哪儿？", "explanation": "这里应该用〈请问〉。“请便”是让对方自便，不用于开口询问。"}, {"text": "谢谢你帮我，请便。", "explanation": "这里应该用〈不客气〉。“请便”是请对方自行其是，不用来回应感谢。"}, {"text": "“我把您的伞弄湿了。”“请便。”", "explanation": "这里应该用〈没关系〉。“请便”是请对方自便，不能用来表示不介意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92481, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "请便", "is_correct": true, "explanation": "正确。“我先去洗手间，你们请便”表示让对方自行其是，与句意相合。"}, {"text": "请进", "is_correct": false, "explanation": "语义：“请进”是请人进来，与“去洗手间”的意思不合。"}, {"text": "请上", "is_correct": false, "explanation": "语义：“请上”是请人上去，与句意不合。"}, {"text": "请假", "is_correct": false, "explanation": "搭配：“请假”是请求休假，不说“你们请假”去洗手间。"}], "explanations": {"请便": "正确。“我先去洗手间，你们请便”表示让对方自行其是，与句意相合。", "请进": "语义：“请进”是请人进来，与“去洗手间”的意思不合。", "请上": "语义：“请上”是请人上去，与句意不合。", "请假": "搭配：“请假”是请求休假，不说“你们请假”去洗手间。"}, "sentence_index": 6, "correct_answer": "请便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天我请便，大家吃吧。", "explanation": "这里应该用〈请客〉。“请便”表示让对方自便，不能表示由我请客。"}, {"text": "您的东西我会保管好，请便。", "explanation": "这里应该用〈请放心〉。“请便”是请对方自便，不能用来宽慰对方。"}, {"text": "路上很滑，请便。", "explanation": "这里应该用〈请注意〉。“请便”是请对方自便，不能用来提醒对方注意安全。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92481, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我还有事，您请便了吧。", "corrected_sentence": "我还有事，您请便吧。", "error_description": "错误在“请便”后加了“了”。“请便”是动词，表示让对方自便，不能直接加“了”，应说“您请便吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92481, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天太晚了，你们很请便吧。", "corrected_sentence": "今天太晚了，你们请便吧。", "error_description": "错误在副词：“很”不能插在“请便”前面，“请便”是固定说法，表示让对方自便，应说“你们请便吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
