INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92492, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "助词性后缀，用在“为了……”之后，表示目的。", "primary_collocate": null, "pronunciation": "qǐ jiàn", "ipa": "tɕʰi˨˩˦ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "为了安全起见，孩子不能一个人出门。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了卫生起见，请不要用手拿。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了大家的方便起见，门开到十点。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保密起见，这件事别告诉别人。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了礼貌起见，他还是写了一封信。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了环保起见，商店不给塑料袋。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了孩子的学习起见，我们搬到学校旁边。", "target_word": "起见", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "为了不迟到起见，他六点就起床了。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了谨慎起见，我们再开一次会。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了好记起见，我把号码写在手上。", "target_word": "起见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "后缀，放在“为了……”之后表示目的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '074eb1d9-d5d2-4422-9990-2487466d07f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92492, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "起见", "is_correct": true, "explanation": "正确答案。起见读作 qǐ jiàn，后缀，放在“为了……”之后表示目的。"}, {"text": "七件", "is_correct": false, "explanation": "qī（第一声）与 qǐ（第三声）声调不同，七件是数量短语，意思是七件物品。"}, {"text": "旗舰", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，旗舰意思是领头的大型船只或产品。"}, {"text": "气节", "is_correct": false, "explanation": "qì（第四声）与 qǐ（第三声）声调不同，jié（第二声）与 jiàn（第四声）声调也不同，气节意思是节操。"}, {"text": "起降", "is_correct": false, "explanation": "jiàng 与 jiàn 韵母不同（ang／an），起降意思是飞机起飞和降落。"}, {"text": "其间", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，jiān（第一声）与 jiàn（第四声）声调也不同，其间意思是其中、期间。"}], "explanations": {"起见": "正确答案。起见读作 qǐ jiàn，后缀，放在“为了……”之后表示目的。", "七件": "qī（第一声）与 qǐ（第三声）声调不同，七件是数量短语，意思是七件物品。", "旗舰": "qí（第二声）与 qǐ（第三声）声调不同，旗舰意思是领头的大型船只或产品。", "气节": "qì（第四声）与 qǐ（第三声）声调不同，jié（第二声）与 jiàn（第四声）声调也不同，气节意思是节操。", "起降": "jiàng 与 jiàn 韵母不同（ang／an），起降意思是飞机起飞和降落。", "其间": "qí（第二声）与 qǐ（第三声）声调不同，jiān（第一声）与 jiàn（第四声）声调也不同，其间意思是其中、期间。"}, "sentence_index": null, "correct_answer": "起见"}, "level_3": {"options": [{"text": "起见", "is_correct": true, "explanation": "正确答案。“为了安全起见”表示孩子不能单独出门是为了安全这一目的。"}, {"text": "来说", "is_correct": false, "explanation": "配价：“来说”要和“对／就”配合（对孩子来说），不能直接接在“为了安全”之后。"}, {"text": "而已", "is_correct": false, "explanation": "语义：“而已”表示“仅此而已”，与“孩子不能一个人出门”这一限制的语气不协调。"}, {"text": "而定", "is_correct": false, "explanation": "搭配：“而定”前面须有“视……”，说“为了安全而定”不成立。"}], "explanations": {"起见": "正确答案。“为了安全起见”表示孩子不能单独出门是为了安全这一目的。", "来说": "配价：“来说”要和“对／就”配合（对孩子来说），不能直接接在“为了安全”之后。", "而已": "语义：“而已”表示“仅此而已”，与“孩子不能一个人出门”这一限制的语气不协调。", "而定": "搭配：“而定”前面须有“视……”，说“为了安全而定”不成立。"}, "sentence_index": 0, "correct_answer": "起见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "为了他刚才的生气起见，我们没有说话。", "explanation": "这里不能用〈起见〉。〈起见〉要接尚未达到、可以主动去做的目的，“生气”是已经发生的情绪，不能作为目的，应说“因为他生气，我们没有说话”。"}, {"text": "为了这个孩子起见，他一天没吃饭。", "explanation": "这里不能用〈起见〉。〈起见〉表示为达到某个目的而主动做事，“一天没吃饭”与“为了孩子”的目的相矛盾，应说“为了孩子的健康，他每天都认真吃饭”。"}, {"text": "为了这个月已经瘦了五斤起见，我们一起跑步。", "explanation": "这里不能用〈起见〉。〈起见〉要接尚未实现、可以主动去做的目的，“已经瘦了五斤”是既成结果，不能作为目的，应说“为了继续减重，我们一起跑步”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起见", "is_correct": true, "explanation": "正确答案。“为了孩子的学习起见”表示搬家是为了孩子的学习这一目的。"}, {"text": "而言", "is_correct": false, "explanation": "配价：“而言”要和“对／就”配合（对孩子的学习而言），不能直接接在“为了……”之后。"}, {"text": "以来", "is_correct": false, "explanation": "语义：“以来”表示从某个时间点开始，不表示做事的目的，与“搬到学校旁边”的意图不符。"}, {"text": "所致", "is_correct": false, "explanation": "搭配：“所致”前面须是原因，说“为了孩子的学习所致”不成立。"}], "explanations": {"起见": "正确答案。“为了孩子的学习起见”表示搬家是为了孩子的学习这一目的。", "而言": "配价：“而言”要和“对／就”配合（对孩子的学习而言），不能直接接在“为了……”之后。", "以来": "语义：“以来”表示从某个时间点开始，不表示做事的目的，与“搬到学校旁边”的意图不符。", "所致": "搭配：“所致”前面须是原因，说“为了孩子的学习所致”不成立。"}, "sentence_index": 6, "correct_answer": "起见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "为了下雨起见，我们明天去爬山。", "explanation": "这里不能用〈起见〉。〈起见〉表示为达到某个目的而主动去做，“下雨”是外部条件，不能作为主动去做的目的；这里应该用〈根据〉，说“根据天气，我们明天去爬山”。"}, {"text": "为了开心起见，他一直哭个不停。", "explanation": "这里不能用〈起见〉。〈起见〉表示为达到某个目的而做事，“一直哭个不停”与“开心”的目的完全相反，应说“因为伤心，他一直哭个不停”。"}, {"text": "为了她已经吃饱起见，我们让她多吃饭。", "explanation": "这里不能用〈起见〉。〈起见〉要接尚未实现、可以主动去做的目的，“已经吃饱”是既成事实，且与“让她多吃饭”的目的相矛盾，应说“她已经吃饱，不必再让她多吃饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "为了卫生起见了，大家先洗手。", "corrected_sentence": "为了卫生起见，大家先洗手。", "error_description": "“起见”是固定的目的标记，后面不能加“了”。正确的说法是“为了卫生起见，大家先洗手”，不能说“为了卫生起见了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "为了安静的起见，大家分开走。", "corrected_sentence": "为了安静起见，大家分开走。", "error_description": "“起见”前面不能加“的”，应直接跟在目的词语之后。正确的说法是“为了安静起见”，“安静的起见”不是固定用法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
