INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92496, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体柔软、没有骨骼的；也指软体动物。", "primary_collocate": null, "pronunciation": "ruǎn tǐ", "ipa": "ʐwan˨˩˦ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "章鱼是软体，身体里没有骨头。", "target_word": "软体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海里的软体有很多，比如章鱼。", "target_word": "软体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乌贼是软体，身体又软又滑。", "target_word": "软体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友在海边找到了几种软体。", "target_word": "软体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种软体能钻进很小的洞。", "target_word": "软体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，蜗牛也是软体。", "target_word": "软体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水族馆里有各种各样的软体。", "target_word": "软体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只软体没有骨头，摸起来很软。", "target_word": "软体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种软体的肉很嫩，我很爱吃。", "target_word": "软体", "complexity_tier": "T3", "furigana": "zhè zhǒng ruǎn tǐ de ròu hěn nèn, wǒ hěn ài chī.", "sentence_source": "generated"}, {"text": "章鱼是一种聪明的软体。", "target_word": "软体", "complexity_tier": "T3", "furigana": "zhāng yú shì yì zhǒng cōng ming de ruǎn tǐ.", "sentence_source": "generated"}], "morphological_forms": [{"form": "软体动物", "label": "复合"}], "register": "中性", "sense_fingerprint": "指章鱼、乌贼、蜗牛等身体柔软没有骨骼的动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e461a86-2103-4f36-87ea-09eaf67ac906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92496, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "软体", "is_correct": true, "explanation": "正确：软体指身体柔软、没有骨骼的动物。"}, {"text": "软底", "is_correct": false, "explanation": "dǐ（第三声）与 tǐ（第三声）声母不同（d / t），意思是软底，指柔软的鞋底。"}, {"text": "软笔", "is_correct": false, "explanation": "bǐ（第三声）与 tǐ（第三声）声母不同（b / t），意思是软笔，指毛笔等软笔。"}, {"text": "软梯", "is_correct": false, "explanation": "tī（第一声）与 tǐ（第三声）声调不同，意思是软梯，指可以卷起来的绳梯。"}, {"text": "软尺", "is_correct": false, "explanation": "chǐ（第三声）与 tǐ（第三声）声母不同（ch / t），意思是软尺，指可以弯曲的卷尺。"}], "explanations": {"软体": "正确：软体指身体柔软、没有骨骼的动物。", "软底": "dǐ（第三声）与 tǐ（第三声）声母不同（d / t），意思是软底，指柔软的鞋底。", "软笔": "bǐ（第三声）与 tǐ（第三声）声母不同（b / t），意思是软笔，指毛笔等软笔。", "软梯": "tī（第一声）与 tǐ（第三声）声调不同，意思是软梯，指可以卷起来的绳梯。", "软尺": "chǐ（第三声）与 tǐ（第三声）声母不同（ch / t），意思是软尺，指可以弯曲的卷尺。"}, "sentence_index": null, "correct_answer": "软体"}, "level_3": {"options": [{"text": "软体", "is_correct": true, "explanation": "正确：软体指身体柔软、没有骨骼的动物，与句中“身体里没有骨头”相符。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：章鱼是动物，不能说是海洋。"}, {"text": "软骨", "is_correct": false, "explanation": "语义：软骨是身体里的组织，不是动物，不能说“章鱼是软骨”。"}, {"text": "硬壳", "is_correct": false, "explanation": "体貌：章鱼没有硬壳，“硬壳”指外壳的样子，与句子描述不符。"}], "explanations": {"软体": "正确：软体指身体柔软、没有骨骼的动物，与句中“身体里没有骨头”相符。", "海洋": "语义：章鱼是动物，不能说是海洋。", "软骨": "语义：软骨是身体里的组织，不是动物，不能说“章鱼是软骨”。", "硬壳": "体貌：章鱼没有硬壳，“硬壳”指外壳的样子，与句子描述不符。"}, "sentence_index": 0, "correct_answer": "软体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鸡翅的关节里有一段软体，嚼起来很脆。", "explanation": "这里应该用〈软骨〉。软体指没有骨骼的动物或其柔软的身体，关节里的软骨不能叫软体。"}, {"text": "这块牛肉炖了很久，已经变成了软体。", "explanation": "这里应该用〈柔软〉。软体指柔软无骨的身体或软体动物，形容肉的质地要用〈柔软〉，不能说软体。"}, {"text": "这管软体很滑，抹在伤口上很舒服。", "explanation": "这里应该用〈软膏〉。软体指柔软无骨的身体或软体动物，涂在伤口上的药膏要说〈软膏〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92496, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "软体", "is_correct": true, "explanation": "正确：水族馆里展出的各种软体动物，符合句意。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是搭乘交通工具的人，水族馆里展出的不会是乘客。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是出行时携带的物品，与水族馆里展出的东西不符。"}, {"text": "轮船", "is_correct": false, "explanation": "搭配：水族馆一般不陈列轮船，“各种各样的轮船”不能说在这里。"}], "explanations": {"软体": "正确：水族馆里展出的各种软体动物，符合句意。", "乘客": "语义：乘客是搭乘交通工具的人，水族馆里展出的不会是乘客。", "行李": "语义：行李是出行时携带的物品，与水族馆里展出的东西不符。", "轮船": "搭配：水族馆一般不陈列轮船，“各种各样的轮船”不能说在这里。"}, "sentence_index": 6, "correct_answer": "软体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这瓶软体很甜，孩子们都爱喝。", "explanation": "这里应该用〈软饮料〉。软体指柔软无骨的身体或软体动物，瓶装的甜饮料要说〈软饮料〉。"}, {"text": "这盒软体白白的，放进汤里煮一下就很嫩。", "explanation": "这里应该用〈豆腐〉。软体指柔软无骨的身体或软体动物，做汤用的嫩豆腐不能叫软体。"}, {"text": "这颗软体很甜，我买来送给弟弟。", "explanation": "这里应该用〈软糖〉。软体指柔软无骨的身体或软体动物，甜的糖果要说〈软糖〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在潮湿的石头下面找到了一只软体们。", "corrected_sentence": "我们在潮湿的石头下面找到了一只软体。", "error_description": "错误在“软体”后多加了复数标记“们”。“一只”已经表示数量，“软体”指软体动物，不能再加“们”，应说“一只软体”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家水族馆的展厅里养着一块软体。", "corrected_sentence": "这家水族馆的展厅里养着一种软体。", "error_description": "量词错误：“软体”指软体动物，应用量词“种”或“只”，不能用“块”（“块”用于块状的东西，如肉）。改为：一种软体。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
