INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92497, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "羡慕是看见别人有好东西，也想有。", "primary_collocate": null, "pronunciation": "xiàn mù", "ipa": "ɕjɛn˥˩ mu˥˩", "syllable_count": 2, "sentences": [{"text": "我羡慕他的新手机。", "target_word": "羡慕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟羡慕同学有一辆新自行车。", "target_word": "羡慕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们羡慕地看着别人的玩具。", "target_word": "羡慕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有大房子，我很羡慕。", "target_word": "羡慕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明羡慕邻居家有一只小狗。", "target_word": "羡慕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到朋友的新车，他羡慕极了。", "target_word": "羡慕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我羡慕过同桌的那支漂亮的笔。", "target_word": "羡慕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人有假期去旅行，她很羡慕。", "target_word": "羡慕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他羡慕着别人手里的冰淇淋。", "target_word": "羡慕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹羡慕我有一台新电脑。", "target_word": "羡慕", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "羨慕", "label": "繁体"}, {"form": "羡慕过", "label": "体标"}, {"form": "羡慕着", "label": "体标"}], "register": "中性", "sense_fingerprint": "看见别人拥有的东西或物品而自己也想拥有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823356df-e298-42d6-83d2-7110f3829571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92497, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "羡慕", "is_correct": true, "explanation": "正确：羡慕 xiàn mù，听到的就是这个词。"}, {"text": "项目", "is_correct": false, "explanation": "项目 xiàngmù 与 羡慕 xiànmù 韵母不同（ang 与 an），意思是“工作计划或事项”。"}, {"text": "显目", "is_correct": false, "explanation": "显目 xiǎnmù 与 羡慕 xiànmù 声调不同（第三声与第四声），意思是“显眼、醒目”。"}, {"text": "心目", "is_correct": false, "explanation": "心目 xīnmù 与 羡慕 xiànmù 韵母不同（in 与 an），意思是“心中的看法或印象”。"}, {"text": "香木", "is_correct": false, "explanation": "香木 xiāngmù 与 羡慕 xiànmù 韵母与声调都不同，意思是“有香味的树木”。"}], "explanations": {"羡慕": "正确：羡慕 xiàn mù，听到的就是这个词。", "项目": "项目 xiàngmù 与 羡慕 xiànmù 韵母不同（ang 与 an），意思是“工作计划或事项”。", "显目": "显目 xiǎnmù 与 羡慕 xiànmù 声调不同（第三声与第四声），意思是“显眼、醒目”。", "心目": "心目 xīnmù 与 羡慕 xiànmù 韵母不同（in 与 an），意思是“心中的看法或印象”。", "香木": "香木 xiāngmù 与 羡慕 xiànmù 韵母与声调都不同，意思是“有香味的树木”。"}, "sentence_index": null, "correct_answer": "羡慕"}, "level_3": {"options": [{"text": "羡慕", "is_correct": true, "explanation": "正确：“羡慕”表示看见别人拥有的东西而想要，用在“他的新手机”上正确。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”指想念过去的人或事，句中的手机是新的，不能怀念。"}, {"text": "同情", "is_correct": false, "explanation": "语义：新手机不值得同情，与“羡慕”所表示的向往不合。"}, {"text": "佩服", "is_correct": false, "explanation": "搭配：“佩服”用于人的能力、品质等，不用于物品。"}], "explanations": {"羡慕": "正确：“羡慕”表示看见别人拥有的东西而想要，用在“他的新手机”上正确。", "怀念": "语义：“怀念”指想念过去的人或事，句中的手机是新的，不能怀念。", "同情": "语义：新手机不值得同情，与“羡慕”所表示的向往不合。", "佩服": "搭配：“佩服”用于人的能力、品质等，不用于物品。"}, "sentence_index": 0, "correct_answer": "羡慕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他生病住院了，我很羡慕他。", "explanation": "这里应该用〈关心〉。“羡慕”针对别人拥有的好东西，别人生病时要表示“关心”，不能用“羡慕”。"}, {"text": "我很羡慕他的破手机。", "explanation": "这里应该用〈嫌弃〉。“羡慕”针对别人拥有的好东西，对破旧的东西要用“嫌弃”，不能用“羡慕”。"}, {"text": "我一直羡慕那辆被偷走的自行车。", "explanation": "这里应该用〈怀念〉。“羡慕”针对对方现在拥有的东西，已经失去的东西要用“怀念”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92497, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "羡慕", "is_correct": true, "explanation": "正确：“羡慕”表示看到别人的东西而希望自己也有，与“漂亮的笔”搭配自然。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是取笑，与句中“漂亮”的赞赏相矛盾。"}, {"text": "鄙视", "is_correct": false, "explanation": "语义：“鄙视”是看不起，与“漂亮的笔”的赞赏不相符。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”用于人的言行，不用于说一支笔。"}], "explanations": {"羡慕": "正确：“羡慕”表示看到别人的东西而希望自己也有，与“漂亮的笔”搭配自然。", "嘲笑": "语义：“嘲笑”是取笑，与句中“漂亮”的赞赏相矛盾。", "鄙视": "语义：“鄙视”是看不起，与“漂亮的笔”的赞赏不相符。", "批评": "搭配：“批评”用于人的言行，不用于说一支笔。"}, "sentence_index": 6, "correct_answer": "羡慕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很羡慕你替我付了钱。", "explanation": "这里应该用〈感激〉。别人替我付钱，我应表示“感激”，不能用“羡慕”。"}, {"text": "我很羡慕他的粗心。", "explanation": "这里应该用〈责备〉。粗心是缺点，不是值得向往的长处，这里应该用“责备”。"}, {"text": "我很羡慕他的懒惰。", "explanation": "这里应该用〈不满〉。懒惰是缺点，对别人的懒惰应当表示“不满”，“羡慕”针对别人的好东西，这里用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92497, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我羡慕了过他的新房子。", "corrected_sentence": "我羡慕过他的新房子。", "error_description": "错误：“羡慕了过”。正确：“羡慕过”。“过”表示曾经有过的经历，不能与“了”同时用在同一个动词后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92497, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我羡慕很她的大房子。", "corrected_sentence": "我羡慕她的大房子。", "error_description": "错误：“羡慕很她的大房子”。正确：“羡慕她的大房子”。“很”是程度副词，不能插在“羡慕”和宾语“她的大房子”之间；要说“很羡慕她的大房子”或直接说“羡慕她的大房子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
