INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92498, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看到别人的长处或好处而希望自己也有。", "primary_collocate": null, "pronunciation": "xiàn mù", "ipa": "ɕjɛn˥˩ mu˥˩", "syllable_count": 2, "sentences": [{"text": "大家都羡慕他的好口才。", "target_word": "羡慕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我很羡慕你会说三种语言。", "target_word": "羡慕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她羡慕过同学的好成绩。", "target_word": "羡慕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王的工作能力让同事很羡慕。", "target_word": "羡慕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他羡慕姐姐有那么好的耐心。", "target_word": "羡慕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到哥哥这么努力，我真羡慕他。", "target_word": "羡慕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁不羡慕身体好、精神也好的人呢？", "target_word": "羡慕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我一直羡慕着会画画的人。", "target_word": "羡慕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的好习惯让很多人羡慕不已。", "target_word": "羡慕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟羡慕我能跑得这么快。", "target_word": "羡慕", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "羨慕", "label": "繁体"}, {"form": "羡慕过", "label": "体标"}, {"form": "羡慕着", "label": "体标"}], "register": "中性", "sense_fingerprint": "对别人的能力、品质、条件等长处心生向往", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823356df-e298-42d6-83d2-7110f3829571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92498, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "羡慕", "is_correct": true, "explanation": "正确：羡慕 xiàn mù，听到的就是这个词。"}, {"text": "项目", "is_correct": false, "explanation": "项目 xiàngmù 与 羡慕 xiànmù 韵母不同（ang 与 an），意思是“工作计划或事项”。"}, {"text": "显目", "is_correct": false, "explanation": "显目 xiǎnmù 与 羡慕 xiànmù 声调不同（第三声与第四声），意思是“显眼、醒目”。"}, {"text": "心目", "is_correct": false, "explanation": "心目 xīnmù 与 羡慕 xiànmù 韵母不同（in 与 an），意思是“心中的看法或印象”。"}, {"text": "香木", "is_correct": false, "explanation": "香木 xiāngmù 与 羡慕 xiànmù 韵母与声调都不同，意思是“有香味的树木”。"}], "explanations": {"羡慕": "正确：羡慕 xiàn mù，听到的就是这个词。", "项目": "项目 xiàngmù 与 羡慕 xiànmù 韵母不同（ang 与 an），意思是“工作计划或事项”。", "显目": "显目 xiǎnmù 与 羡慕 xiànmù 声调不同（第三声与第四声），意思是“显眼、醒目”。", "心目": "心目 xīnmù 与 羡慕 xiànmù 韵母不同（in 与 an），意思是“心中的看法或印象”。", "香木": "香木 xiāngmù 与 羡慕 xiànmù 韵母与声调都不同，意思是“有香味的树木”。"}, "sentence_index": null, "correct_answer": "羡慕"}, "level_3": {"options": [{"text": "羡慕", "is_correct": true, "explanation": "正确：“羡慕”表示看到别人的好口才而希望自己也有，与“大家都”和“好口才”搭配自然。"}, {"text": "轻视", "is_correct": false, "explanation": "语义：“轻视”是看不起，与句中夸赞的“好口才”相矛盾。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是取笑，与句中“好口才”的赞扬意思相反。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”的对象是活动或集体，不能说“参加好口才”。"}], "explanations": {"羡慕": "正确：“羡慕”表示看到别人的好口才而希望自己也有，与“大家都”和“好口才”搭配自然。", "轻视": "语义：“轻视”是看不起，与句中夸赞的“好口才”相矛盾。", "嘲笑": "语义：“嘲笑”是取笑，与句中“好口才”的赞扬意思相反。", "参加": "搭配：“参加”的对象是活动或集体，不能说“参加好口才”。"}, "sentence_index": 0, "correct_answer": "羡慕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很羡慕他的不幸遭遇。", "explanation": "这里应该用〈同情〉。“羡慕”针对别人有的好处，别人的不幸要用“同情”，“羡慕他的不幸”不通。"}, {"text": "大家都羡慕他的坏脾气。", "explanation": "这里应该用〈讨厌〉。“羡慕”针对别人的长处或好处，对别人的缺点应当用“讨厌”，这里不能用“羡慕”。"}, {"text": "我很羡慕你每天被批评。", "explanation": "这里应该用〈心疼〉。“羡慕”针对别人的长处或好处，别人每天被批评要用“心疼”，不能用“羡慕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "羡慕", "is_correct": true, "explanation": "正确：“羡慕”表示希望拥有对方的好身体和好精神，与“谁不”所表达的普遍向往相符。"}, {"text": "同情", "is_correct": false, "explanation": "语义：身体好、精神好的人不需要同情，与句中的“好”相矛盾。"}, {"text": "照顾", "is_correct": false, "explanation": "搭配：“照顾”针对需要帮助的人，不能用来说身体好、精神好的人。"}, {"text": "鄙视", "is_correct": false, "explanation": "语义：“鄙视”是看不起，与“谁不……”所表达的普遍向往相反。"}], "explanations": {"羡慕": "正确：“羡慕”表示希望拥有对方的好身体和好精神，与“谁不”所表达的普遍向往相符。", "同情": "语义：身体好、精神好的人不需要同情，与句中的“好”相矛盾。", "照顾": "搭配：“照顾”针对需要帮助的人，不能用来说身体好、精神好的人。", "鄙视": "语义：“鄙视”是看不起，与“谁不……”所表达的普遍向往相反。"}, "sentence_index": 6, "correct_answer": "羡慕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很羡慕你的帮助。", "explanation": "这里应该用〈感激〉。“羡慕”针对别人的长处或好处，别人给予的帮助要用“感激”。"}, {"text": "我很羡慕老师的批评。", "explanation": "这里应该用〈感谢〉。“羡慕”不能用于别人对我的批评，对批评应当表示感谢。"}, {"text": "我很羡慕你的道歉。", "explanation": "这里应该用〈原谅〉。“羡慕”针对别人拥有的好东西，别人向我道歉时要用“接受”或“原谅”，不能用“羡慕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很羡慕地他能坚持运动。", "corrected_sentence": "我很羡慕他能坚持运动。", "error_description": "错误：“地”多余。“地”用在状语之后、修饰动词，这里“地”后面是主语“他”，无法构成状语，应删去“地”，说“我很羡慕他能坚持运动。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我羡慕了过你的好运气。", "corrected_sentence": "我羡慕过你的好运气。", "error_description": "错误：“羡慕了过”。正确：“羡慕过”。“过”表示曾经有过的经历，不能与“了”同时用在同一个动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
