INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92499, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "遭遇是碰上了不好的事。", "primary_collocate": null, "pronunciation": "zāo yù", "ipa": "tsɑʊ˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "他昨天在路上遭遇了危险。", "target_word": "遭遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李在比赛中遭遇了失败。", "target_word": "遭遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的飞机遭遇了坏天气。", "target_word": "遭遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇遭遇过一次大火。", "target_word": "遭遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在旅行时遭遇了车祸。", "target_word": "遭遇", "complexity_tier": "T3", "furigana": "zāo yù", "sentence_source": "generated"}, {"text": "农民今年遭遇了干旱，粮食不多。", "target_word": "遭遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店遭遇了很大的损失。", "target_word": "遭遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在新城市遭遇了不少麻烦。", "target_word": "遭遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船在河里遭遇了大浪。", "target_word": "遭遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司遭遇过不公平的对待。", "target_word": "遭遇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遭遇了", "label": "体标"}, {"form": "遭遇过", "label": "体标"}], "register": "中性", "sense_fingerprint": "碰上了不好的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5ffa561-fbb8-426b-81b7-350f6bf5c46a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92499, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "遭遇", "is_correct": true, "explanation": "遭遇（zāo yù）：碰上不好的事，与听到的读音相同。"}, {"text": "早于", "is_correct": false, "explanation": "zǎo yú（早于）与 zāo yù 声调不同：zǎo（第三声）与 zāo（第一声）不同，yú（第二声）与 yù（第四声）不同，意思是“比……早”。"}, {"text": "造雨", "is_correct": false, "explanation": "zào yǔ（造雨）与 zāo yù 声调不同：zào（第四声）与 zāo（第一声）不同，yǔ（第三声）与 yù（第四声）不同，意思是“人工降雨”。"}, {"text": "早育", "is_correct": false, "explanation": "zǎo yù（早育）与 zāo yù 的第一个音节声调不同：zǎo（第三声）与 zāo（第一声）不同，意思是“过早生育”。"}], "explanations": {"遭遇": "遭遇（zāo yù）：碰上不好的事，与听到的读音相同。", "早于": "zǎo yú（早于）与 zāo yù 声调不同：zǎo（第三声）与 zāo（第一声）不同，yú（第二声）与 yù（第四声）不同，意思是“比……早”。", "造雨": "zào yǔ（造雨）与 zāo yù 声调不同：zào（第四声）与 zāo（第一声）不同，yǔ（第三声）与 yù（第四声）不同，意思是“人工降雨”。", "早育": "zǎo yù（早育）与 zāo yù 的第一个音节声调不同：zǎo（第三声）与 zāo（第一声）不同，意思是“过早生育”。"}, "sentence_index": null, "correct_answer": "遭遇"}, "level_3": {"options": [{"text": "遭遇", "is_correct": true, "explanation": "遭遇：碰上不好的事，与“危险”的意思相合。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指喜爱地观赏美好的事物，与“危险”的意思相冲突。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”用于活动、展览，不能与“危险”搭配。"}, {"text": "享有", "is_correct": false, "explanation": "搭配：“享有”指拥有好的权利或名誉，不能带“危险”作宾语。"}], "explanations": {"遭遇": "遭遇：碰上不好的事，与“危险”的意思相合。", "欣赏": "语义：“欣赏”指喜爱地观赏美好的事物，与“危险”的意思相冲突。", "举办": "搭配：“举办”用于活动、展览，不能与“危险”搭配。", "享有": "搭配：“享有”指拥有好的权利或名誉，不能带“危险”作宾语。"}, "sentence_index": 0, "correct_answer": "遭遇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在车站遭遇了多年没见的朋友。", "explanation": "这里应该用〈遇见〉。遭遇指碰上不幸或不利的事，见到多年没见的朋友是愉快的事，不能用“遭遇”。"}, {"text": "我们这次旅行遭遇了很多有趣的事。", "explanation": "这里应该用〈经历〉。遭遇指碰上不幸或不利的事，“有趣的事”是好事，不能用“遭遇”。"}, {"text": "他在比赛中遭遇了第一名。", "explanation": "这里应该用〈获得〉。遭遇指碰上不幸或不利的事，“第一名”是好结果，不能用“遭遇”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92499, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遭遇", "is_correct": true, "explanation": "遭遇：碰上不利的事，与“很大的损失”的意思相合。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”表示为喜事欢庆，与“很大的损失”的意思相冲突。"}, {"text": "获得", "is_correct": false, "explanation": "语义：“获得”指得到好的结果，与“损失”的意思相矛盾。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”一般带“快乐”“待遇”，不能与“损失”搭配。"}], "explanations": {"遭遇": "遭遇：碰上不利的事，与“很大的损失”的意思相合。", "庆祝": "语义：“庆祝”表示为喜事欢庆，与“很大的损失”的意思相冲突。", "获得": "语义：“获得”指得到好的结果，与“损失”的意思相矛盾。", "享受": "搭配：“享受”一般带“快乐”“待遇”，不能与“损失”搭配。"}, "sentence_index": 6, "correct_answer": "遭遇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天在路上遭遇了一位好朋友。", "explanation": "这里应该用〈碰上〉。遭遇指碰上不幸或不利的事，“好朋友”是好事，不能用“遭遇”。"}, {"text": "暑假我们遭遇了一家工厂。", "explanation": "这里应该用〈参观〉。遭遇指碰上不幸或不利的事，不能用来指去参观工厂。"}, {"text": "晚上我们在河边遭遇了月亮。", "explanation": "这里应该用〈欣赏〉。遭遇指碰上不幸的事，“月亮”是美好的景物，不能用“遭遇”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92499, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在工厂里遭遇的一次机器故障。", "corrected_sentence": "她在工厂里遭遇了一次机器故障。", "error_description": "助词错误：表示完成应用“了”，此处误用“的”，句子缺少谓语，不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92499, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他上个月在海上遭遇了过一场大风。", "corrected_sentence": "他上个月在海上遭遇过一场大风。", "error_description": "体标错误：“遭遇”后面只用“过”或“了”之一，不能同时使用“了过”。正确写法是“遭遇过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
