INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92501, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西给别人。", "primary_collocate": null, "pronunciation": "sòng rén", "ipa": "sʊŋ˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "这件衣服我不穿了，想送人。", "target_word": "送人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的苹果太多了，吃不完，送人吧。", "target_word": "送人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧书我都整理好了，打算送人。", "target_word": "送人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了两盒月饼，一盒自己吃，一盒送人。", "target_word": "送人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我养不了这只小猫，只好送人。", "target_word": "送人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做了很多饺子，让我拿一些送人。", "target_word": "送人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些玩具孩子不玩了，我们送人吧。", "target_word": "送人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多余的票我用不上，不如送人。", "target_word": "送人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台旧电视还能用，扔了可惜，不如送人。", "target_word": "送人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买多了水果，分一些送人。", "target_word": "送人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "送了人", "label": "体标"}, {"form": "送过人", "label": "体标"}, {"form": "送人情", "label": "复合"}], "register": "口语", "sense_fingerprint": "把自己用不上或多余的东西给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fba8654-6602-4f46-b68a-f1451ee604be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92501, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "送人", "is_correct": true, "explanation": "正确答案。送人（sòng rén）意思是把东西给别人。"}, {"text": "松仁", "is_correct": false, "explanation": "sōng（第一声）与 sòng（第四声）声调不同，意思是松子的果仁。"}, {"text": "众人", "is_correct": false, "explanation": "zhòng 与 sòng 声母不同，意思是许多人。"}, {"text": "动人", "is_correct": false, "explanation": "dòng 与 sòng 声母不同，意思是感人。"}], "explanations": {"送人": "正确答案。送人（sòng rén）意思是把东西给别人。", "松仁": "sōng（第一声）与 sòng（第四声）声调不同，意思是松子的果仁。", "众人": "zhòng 与 sòng 声母不同，意思是许多人。", "动人": "dòng 与 sòng 声母不同，意思是感人。"}, "sentence_index": null, "correct_answer": "送人"}, "level_3": {"options": [{"text": "送人", "is_correct": true, "explanation": "正确。送人在此表示把不穿的衣服给别人。"}, {"text": "穿上", "is_correct": false, "explanation": "语义：“穿上”与前面的“我不穿了”矛盾。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：衣服不能被“吃掉”，搭配不成立。"}, {"text": "喝下", "is_correct": false, "explanation": "搭配：“喝下”的对象是饮料或药，不能用于衣服。"}], "explanations": {"送人": "正确。送人在此表示把不穿的衣服给别人。", "穿上": "语义：“穿上”与前面的“我不穿了”矛盾。", "吃掉": "搭配：衣服不能被“吃掉”，搭配不成立。", "喝下": "搭配：“喝下”的对象是饮料或药，不能用于衣服。"}, "sentence_index": 0, "correct_answer": "送人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把旧车送人，收了五千块钱。", "explanation": "这里应该用〈卖〉。送人是无偿给别人，收钱的交易要用卖。"}, {"text": "春节前，他常去给客户送人。", "explanation": "这里应该用〈送礼〉。送人是把自己多余的东西给别人，给客户表示心意要用〈送礼〉。"}, {"text": "这本书我送人了，过几天要还回来。", "explanation": "这里应该用〈借〉。送人是永久给出，过几天还回来说明是借出，要用借。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92501, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "送人", "is_correct": true, "explanation": "正确。送人在此表示把不玩的玩具给别人。"}, {"text": "赠予人", "is_correct": false, "explanation": "语域：“赠予”是书面语，与口语的“我们……吧”语气不合。"}, {"text": "借人", "is_correct": false, "explanation": "语义：“借”是借来还去，与“不玩了，送人吧”的赠予语境不合。"}, {"text": "租人", "is_correct": false, "explanation": "配价：“租”的对象是房屋或物品，不能租人。"}], "explanations": {"送人": "正确。送人在此表示把不玩的玩具给别人。", "赠予人": "语域：“赠予”是书面语，与口语的“我们……吧”语气不合。", "借人": "语义：“借”是借来还去，与“不玩了，送人吧”的赠予语境不合。", "租人": "配价：“租”的对象是房屋或物品，不能租人。"}, "sentence_index": 6, "correct_answer": "送人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间房我送人住了一年，每月还收房租。", "explanation": "这里应该用〈出租〉。送人是无偿给别人，每月收房租说明是租出，要用出租。"}, {"text": "年底他常给老板送人。", "explanation": "这里应该用〈送礼〉。送人是把自己多余的东西给别人，给老板表示心意要用〈送礼〉。"}, {"text": "我把这本书送人，换来了一双鞋。", "explanation": "这里应该用〈交换〉。送人是白白给出，拿东西换回要用交换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92501, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台旧收音机还能用，我想送了人。", "corrected_sentence": "这台旧收音机还能用，我想送人。", "error_description": "“想”表示打算，后面的动作还没发生，“送了人”用了完成体。应去掉“了”，说“想送人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92501, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这些小饰品整理好了，准备送人了。", "corrected_sentence": "我把这些小饰品整理好了，准备送人。", "error_description": "“准备”表示打算，后面的动作还没发生，句末不能用“了”。应去掉句末的“了”，说“准备送人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51f02ffb-1968-400e-9402-e0b5fd30faba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
