INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92508, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92508, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过体育活动增强体质；也指磨炼。", "primary_collocate": null, "pronunciation": "duàn liàn", "ipa": "tuan⁵¹ ljɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "游泳可以锻炼全身的肌肉。", "target_word": "锻炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多爬山能锻炼身体，也能锻炼意志。", "target_word": "锻炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作锻炼了我的耐心。", "target_word": "锻炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛锻炼了孩子们的勇气。", "target_word": "锻炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "独自出国留学锻炼了她的独立能力。", "target_word": "锻炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天打篮球，能锻炼身体。", "target_word": "锻炼", "complexity_tier": "T3", "furigana": "měi tiān dǎ lán qiú néng duàn liàn shēn tǐ", "sentence_source": "generated"}, {"text": "他在农村锻炼过两年，变得很能吃苦。", "target_word": "锻炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军训能锻炼学生吃苦的精神。", "target_word": "锻炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做家务也能锻炼孩子的责任心。", "target_word": "锻炼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人要多经历困难，才能锻炼自己。", "target_word": "锻炼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "锻炼了", "label": "体标（了）"}, {"form": "锻炼过", "label": "体标（过）"}, {"form": "锻炼着", "label": "体标（着）"}, {"form": "锻炼锻炼", "label": "重叠"}, {"form": "鍛煉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "增强体质，也指在困难中磨炼意志和能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5defac78-781a-4fa9-9921-04631e3ba9d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92508, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "锻炼", "is_correct": true, "explanation": "正确：锻炼（duàn liàn），指通过体育活动增强体质，也指磨炼。"}, {"text": "断电", "is_correct": false, "explanation": "diàn 与 liàn 声母不同，意思是停止供电。"}, {"text": "断线", "is_correct": false, "explanation": "xiàn 与 liàn 声母不同，意思是线路或联系中断。"}, {"text": "断裂", "is_correct": false, "explanation": "liè 与 liàn 韵母不同，意思是断开、破裂。"}, {"text": "断面", "is_correct": false, "explanation": "miàn 与 liàn 声母不同，意思是物体的横截面。"}], "explanations": {"锻炼": "正确：锻炼（duàn liàn），指通过体育活动增强体质，也指磨炼。", "断电": "diàn 与 liàn 声母不同，意思是停止供电。", "断线": "xiàn 与 liàn 声母不同，意思是线路或联系中断。", "断裂": "liè 与 liàn 韵母不同，意思是断开、破裂。", "断面": "miàn 与 liàn 声母不同，意思是物体的横截面。"}, "sentence_index": null, "correct_answer": "锻炼"}, "level_3": {"options": [{"text": "锻炼", "is_correct": true, "explanation": "正确：“锻炼全身的肌肉”指通过运动使肌肉更有力。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”针对物品，不能用于肌肉。"}, {"text": "清洗", "is_correct": false, "explanation": "搭配：“清洗”不与“肌肉”搭配，说清洗肌肉不自然。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”需要带场所或展品作宾语，不能说参观肌肉。"}], "explanations": {"锻炼": "正确：“锻炼全身的肌肉”指通过运动使肌肉更有力。", "修理": "语义：“修理”针对物品，不能用于肌肉。", "清洗": "搭配：“清洗”不与“肌肉”搭配，说清洗肌肉不自然。", "参观": "配价：“参观”需要带场所或展品作宾语，不能说参观肌肉。"}, "sentence_index": 0, "correct_answer": "锻炼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天锻炼钢琴，手指越来越灵活。", "explanation": "这里应该用〈练习〉。学习乐器、技艺要用练习，锻炼只用于身体、意志或能力。"}, {"text": "学校锻炼了学生的兴趣。", "explanation": "这里应该用〈培养〉。兴趣、习惯要用培养，锻炼只用于身体、意志或能力。"}, {"text": "工人锻炼了那台机器。", "explanation": "这里应该用〈修理〉。机器要用修理，锻炼的对象是人的身体、意志或能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "锻炼", "is_correct": true, "explanation": "正确：“锻炼过两年”指在农村经历过一段磨炼，所以变得能吃苦。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：旅游是休闲活动，不会让人变得很能吃苦。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”的对象是场所或展品，不能说参观两年。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”的对象是房屋，不能用于人的生活经历。"}], "explanations": {"锻炼": "正确：“锻炼过两年”指在农村经历过一段磨炼，所以变得能吃苦。", "旅游": "语义：旅游是休闲活动，不会让人变得很能吃苦。", "参观": "配价：“参观”的对象是场所或展品，不能说参观两年。", "装修": "搭配：“装修”的对象是房屋，不能用于人的生活经历。"}, "sentence_index": 6, "correct_answer": "锻炼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天锻炼家里的旧书柜，书柜越来越结实。", "explanation": "这里应该用〈加固〉。此句把“锻炼”用成了“使…变结实”的意思，但锻炼只用于人的身体、意志或能力，使书柜变结实要用“加固”。"}, {"text": "妈妈每天锻炼窗户，窗户很快就亮了。", "explanation": "这里应该用〈擦〉。此句把“锻炼”用成了“擦洗、使…干净”的意思，但锻炼只用于人的身体、意志或能力，擦窗户要用“擦”。"}, {"text": "我们每天锻炼这条马路，马路变得很平。", "explanation": "这里应该用〈修整〉。此句把“锻炼”用成了“修平、使…平整”的意思，但锻炼只用于人的身体、意志或能力，修整马路要用“修整”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次演讲很锻炼了我的胆量。", "corrected_sentence": "这次演讲锻炼了我的胆量。", "error_description": "错误：“很”修饰了动词“锻炼”。“很”一般修饰形容词，不宜直接修饰“锻炼”这类动作动词，应去掉。正确说法：这次演讲锻炼了我的胆量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她工厂锻炼过半年，学会了独立做事。", "corrected_sentence": "她在工厂锻炼过半年，学会了独立做事。", "error_description": "错误：漏掉了介词“在”。“在＋地点”要放在动词前面，表示动作发生的地点；“工厂锻炼”不成立，应说“在工厂锻炼”。正确说法：她在工厂锻炼过半年，学会了独立做事。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
