INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92511, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "那么着是说就照那个样子去做。", "primary_collocate": null, "pronunciation": "nà me zhe", "ipa": "na˥˩ mɤ tʂɤ", "syllable_count": 3, "sentences": [{"text": "老师教我怎么写，我就那么着写。", "target_word": "那么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你那么着试试，说不定能成。", "target_word": "那么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他画得很好，你也那么着画吧。", "target_word": "那么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说那么着吃药，病就会好。", "target_word": "那么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈那么着做饭，菜特别香。", "target_word": "那么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法不错，咱们就那么着吧。", "target_word": "那么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想那么着也行，我没有意见。", "target_word": "那么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他让我怎么办，我就那么着办了。", "target_word": "那么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王那么着练了一个月，进步很大。", "target_word": "那么着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说好了，明天就那么着，不要改。", "target_word": "那么着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "就照那个样子去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5ffa561-fbb8-426b-81b7-350f6bf5c46a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92511, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "那么着", "is_correct": true, "explanation": "那么着：口语代词，表示照那个样子去写，与句意相合。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”指人，不能表示照某个样子去写。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”问事物，与“我就……写”的意思不符。"}, {"text": "哪样", "is_correct": false, "explanation": "搭配：“哪样”用于疑问，不能用在“我就……写”的陈述句中。"}], "explanations": {"那么着": "那么着：口语代词，表示照那个样子去写，与句意相合。", "谁": "语义：“谁”指人，不能表示照某个样子去写。", "什么": "语义：“什么”问事物，与“我就……写”的意思不符。", "哪样": "搭配：“哪样”用于疑问，不能用在“我就……写”的陈述句中。"}, "sentence_index": 0, "correct_answer": "那么着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他那么着懂了这道题。", "explanation": "这里应该直接用〈懂〉。那么着表示“照那个样子去做”，“懂”是理解的结果，不能按某种样子进行。"}, {"text": "我那么着认识了新朋友。", "explanation": "这里应该直接用〈认识〉。那么着表示“照那个样子去做”，“认识”不能按某种样子完成，这里的状语搭配不通。"}, {"text": "她那么着考上了大学。", "explanation": "这里应该直接用〈考上〉。那么着表示“照那个样子去做”，“考上”是考试的结果，不能按某种方式完成，这里的状语搭配不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92511, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那么着", "is_correct": true, "explanation": "那么着：口语代词，表示照那个样子去做，与“你想……也行”的句意相合。"}, {"text": "大家", "is_correct": false, "explanation": "语义：“大家”指众人，不能引出“照那个样子去做”的意思。"}, {"text": "别人", "is_correct": false, "explanation": "语义：“别人”指他人，与“你想……也行”的句意不符。"}, {"text": "人家", "is_correct": false, "explanation": "搭配：“人家”一般指他人，不能用在“你想……也行”的位置。"}], "explanations": {"那么着": "那么着：口语代词，表示照那个样子去做，与“你想……也行”的句意相合。", "大家": "语义：“大家”指众人，不能引出“照那个样子去做”的意思。", "别人": "语义：“别人”指他人，与“你想……也行”的句意不符。", "人家": "搭配：“人家”一般指他人，不能用在“你想……也行”的位置。"}, "sentence_index": 6, "correct_answer": "那么着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我那么着生病了。", "explanation": "这里应该直接用〈生病〉。那么着表示“照那个样子去做”，“生病”不是可以按某种样子完成的动作，这里的状语搭配不通。"}, {"text": "他那么着接到了一个电话。", "explanation": "这里应该直接用〈接到〉。那么着表示“照那个样子去做”，“接到”是结果，不能按某种方式完成，这里的状语搭配不通。"}, {"text": "她那么着记住了我的电话。", "explanation": "这里应该直接用〈记住〉。那么着表示“照那个样子去做”，“记住”不能按某种样子完成，这里的状语搭配不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92511, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我就那么着地写，你别管。", "corrected_sentence": "我就那么着写，你别管。", "error_description": "“地”多余：口语“那么着”修饰动词时通常不加“地”（“那样地”属书面用法），此处应写作“那么着写”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92511, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我就那么着的问，你别怪我。", "corrected_sentence": "我就那么着问，你别怪我。", "error_description": "“的”多余：“那么着”修饰动词时直接接在动词前，中间不能加“的”，应写作“那么着问”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
