INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92529, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "上家是玩牌时，排在你前面出牌的人。", "primary_collocate": null, "pronunciation": "shàng jiā", "ipa": "ʂɑŋ˥˩ t͡ɕja˥", "syllable_count": 2, "sentences": [{"text": "我的上家出了一张红桃。", "target_word": "上家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上家没有出牌，轮到我了。", "target_word": "上家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我的上家，我要看他出什么牌。", "target_word": "上家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上家出了一个三带一，我接不上。", "target_word": "上家", "complexity_tier": "T3", "furigana": "shàng jiā chū le yí gè sān dài yī, wǒ jiē bu shàng", "sentence_source": "generated"}, {"text": "打牌时要看清上家出了什么牌。", "target_word": "上家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上家一出大牌，我就知道他手里有好牌。", "target_word": "上家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一局，我的上家打得很快。", "target_word": "上家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的上家刚才出了什么牌？", "target_word": "上家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王是我的上家，小李是我的下家。", "target_word": "上家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上家不要，我就可以出牌了。", "target_word": "上家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "玩牌时排在自己前面出牌的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e47ca02c-da77-46cf-8e0b-0a9f8df1a1a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92529, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上家", "is_correct": true, "explanation": "上家（shàng jiā）指玩牌时排在自己前面出牌的人，是正确答案。"}, {"text": "商家", "is_correct": false, "explanation": "shāng（第一声）与 shàng（第四声）声调不同，意思是做买卖的人或店铺。"}, {"text": "上架", "is_correct": false, "explanation": "jià（第四声）与 jiā（第一声）声调不同，意思是把商品放到货架上。"}, {"text": "上交", "is_correct": false, "explanation": "jiāo 与 jiā 韵母不同（多一个 o），意思是把东西交给上级或组织。"}], "explanations": {"上家": "上家（shàng jiā）指玩牌时排在自己前面出牌的人，是正确答案。", "商家": "shāng（第一声）与 shàng（第四声）声调不同，意思是做买卖的人或店铺。", "上架": "jià（第四声）与 jiā（第一声）声调不同，意思是把商品放到货架上。", "上交": "jiāo 与 jiā 韵母不同（多一个 o），意思是把东西交给上级或组织。"}, "sentence_index": null, "correct_answer": "上家"}, "level_3": {"options": [{"text": "上家", "is_correct": true, "explanation": "上家指玩牌时排在我前面出牌的人，与“我的”和“出牌”搭配，是正确答案。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不会出牌，“我的手机出了一张红桃”说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能玩牌，“出了一张红桃”只能是人。"}, {"text": "牌", "is_correct": false, "explanation": "配价：“出”的施事必须是人，“牌”不能主动出牌。"}], "explanations": {"上家": "上家指玩牌时排在我前面出牌的人，与“我的”和“出牌”搭配，是正确答案。", "手机": "语义：手机不会出牌，“我的手机出了一张红桃”说不通。", "桌子": "语义：桌子不能玩牌，“出了一张红桃”只能是人。", "牌": "配价：“出”的施事必须是人，“牌”不能主动出牌。"}, "sentence_index": 0, "correct_answer": "上家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我先出牌，我的上家接着出。", "explanation": "这里应该用〈下家〉。我出牌之后接着出的是下家；上家是排在我前面出牌的人，不会接在我后面。"}, {"text": "上家那局我赢了，这局我输了。", "explanation": "这里应该用〈上一局〉。上家指排在我前面出牌的人，不能指上一局。"}, {"text": "他是我们公司的上家，比我早来了两年。", "explanation": "这里应该用〈前辈〉或〈同事〉。上家指排在前面出牌的人或上一环节的供货方，不指同事中的前辈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92529, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上家", "is_correct": true, "explanation": "上家指排在我前面出牌的人，能够“打”牌，是正确答案。"}, {"text": "球", "is_correct": false, "explanation": "配价：“打”的施事必须是人，“球”不能做“打”的主语。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不会打牌，“我的房子打得很快”说不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不会玩牌，“我的汽车打得很快”说不通。"}], "explanations": {"上家": "上家指排在我前面出牌的人，能够“打”牌，是正确答案。", "球": "配价：“打”的施事必须是人，“球”不能做“打”的主语。", "房子": "语义：房子不会打牌，“我的房子打得很快”说不通。", "汽车": "语义：汽车不会玩牌，“我的汽车打得很快”说不通。"}, "sentence_index": 6, "correct_answer": "上家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和上家是一伙的，我们一起赢了这局。", "explanation": "这里应该用〈对家〉。打牌时和我同一伙的人坐在对面，是对家；上家挨着我、排在我前面出牌，是对手。"}, {"text": "我的上家是我的队友，他每次都帮我出牌。", "explanation": "这里不能用“上家”指队友。上家是排在我前面出牌的人，与我是对手；与我同伴的是〈队友〉。"}, {"text": "上家卖给我一张牌，我就赢了这局。", "explanation": "这里应该用〈卖家〉。上家是排在我前面出牌的人，不会卖牌给我；〈卖家〉是卖东西的一方，用于买卖关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92529, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天我遇到了一张很厉害的上家。", "corrected_sentence": "今天我遇到了一个很厉害的上家。", "error_description": "量词错误：上家指人，应该用“个”或“位”，不能用“张”（“张”用于纸、桌子等平面的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92529, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一直盯着一只上家，想看他出什么牌。", "corrected_sentence": "我一直盯着上家，想看他出什么牌。", "error_description": "量词错误：上家指人，应该用“个”或“位”，不能用“只”；“只”多用于动物和成对器物中的一个。正确说法是“我一直盯着上家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92530, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
