INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92532, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打扰，使不安宁。", "primary_collocate": null, "pronunciation": "sāo rǎo", "ipa": "sau˥ ʐau˨˩˦", "syllable_count": 2, "sentences": [{"text": "半夜的汽车喇叭声骚扰着全楼的人。", "target_word": "骚扰", "complexity_tier": "T3", "furigana": "bàn yè de qì chē lǎ ba shēng sāo rǎo zhe quán lóu de rén", "sentence_source": "generated"}, {"text": "工地的机器声一早就骚扰了整条街。", "target_word": "骚扰", "complexity_tier": "T3", "furigana": "gōng dì de jī qì shēng yì zǎo jiù sāo rǎo le zhěng tiáo jiē", "sentence_source": "generated"}, {"text": "为了不骚扰别人，他把音乐关小了。", "target_word": "骚扰", "complexity_tier": "T3", "furigana": "wèi le bù sāo rǎo bié rén, tā bǎ yīn yuè guān xiǎo le", "sentence_source": "generated"}, {"text": "施工的声音骚扰了他的工作。", "target_word": "骚扰", "complexity_tier": "T3", "furigana": "shī gōng de shēng yīn sāo rǎo le tā de gōng zuò", "sentence_source": "generated"}, {"text": "深夜的敲门声骚扰着老人的睡眠。", "target_word": "骚扰", "complexity_tier": "T3", "furigana": "shēn yè de qiāo mén shēng sāo rǎo zhe lǎo rén de shuì mián", "sentence_source": "generated"}, {"text": "蚊子在房间里骚扰我，我睡不好。", "target_word": "骚扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上别用音乐骚扰邻居。", "target_word": "骚扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的鞭炮声常常骚扰整个村子。", "target_word": "骚扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼上的脚步声整夜骚扰着我。", "target_word": "骚扰", "complexity_tier": "T3", "furigana": "lóu shàng de jiǎo bù shēng zhěng yè sāo rǎo zhe wǒ", "sentence_source": "generated"}, {"text": "窗外的噪音骚扰着他。", "target_word": "骚扰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "骚扰了", "label": "体标"}, {"form": "骚扰着", "label": "体标"}, {"form": "骚扰过", "label": "体标"}], "register": "中性", "sense_fingerprint": "一般的打扰、干扰，使人或地方不得安宁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e81304c3-911e-48ff-b4ba-3e9273962e3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92532, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骚扰", "is_correct": true, "explanation": "骚扰：打扰，使人不安宁。喇叭声在半夜打扰了全楼的人。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：「照顾」的施事应是有意识的人，喇叭声不能照顾全楼的人。"}, {"text": "提高", "is_correct": false, "explanation": "配价：「提高」的宾语多为水平、质量等抽象事物，不能说提高全楼的人。"}, {"text": "监督", "is_correct": false, "explanation": "语义：喇叭声不能监督人，句中“半夜”的语境也与监督无关。"}], "explanations": {"骚扰": "骚扰：打扰，使人不安宁。喇叭声在半夜打扰了全楼的人。", "照顾": "语义：「照顾」的施事应是有意识的人，喇叭声不能照顾全楼的人。", "提高": "配价：「提高」的宾语多为水平、质量等抽象事物，不能说提高全楼的人。", "监督": "语义：喇叭声不能监督人，句中“半夜”的语境也与监督无关。"}, "sentence_index": 0, "correct_answer": "骚扰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "谢谢您的款待，我该走了，不再骚扰您了。", "explanation": "这里应该用〈打扰〉。告辞时的客气说法是打扰，骚扰含有反复纠缠、令人反感的意思，不能用于客气的告辞。"}, {"text": "雷雨天气骚扰了电视信号。", "explanation": "这里应该用〈干扰〉。骚扰的对象通常是人或生活环境，信号受影响应说干扰。"}, {"text": "他总是骚扰别人的时间。", "explanation": "这里应该用〈占用〉。骚扰强调打扰他人、使人不安，占用别人的时间应说占用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92532, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骚扰", "is_correct": true, "explanation": "骚扰：打扰，使人不安宁。句意是请别人不要用音乐打扰邻居。"}, {"text": "批评", "is_correct": false, "explanation": "语义：音乐不能“批评”人，且句子是请人停止打扰，批评不合语境。"}, {"text": "推广", "is_correct": false, "explanation": "配价：「推广」的宾语多为产品、方法等，不能说推广邻居。"}, {"text": "检查", "is_correct": false, "explanation": "语义：音乐不能检查人，句意与检查无关。"}], "explanations": {"骚扰": "骚扰：打扰，使人不安宁。句意是请别人不要用音乐打扰邻居。", "批评": "语义：音乐不能“批评”人，且句子是请人停止打扰，批评不合语境。", "推广": "配价：「推广」的宾语多为产品、方法等，不能说推广邻居。", "检查": "语义：音乐不能检查人，句意与检查无关。"}, "sentence_index": 6, "correct_answer": "骚扰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次意外骚扰了我们的计划。", "explanation": "这里应该用〈扰乱〉。骚扰多指打扰人、使人不安，计划被打乱应说扰乱。"}, {"text": "警察要负责骚扰社会秩序。", "explanation": "这里应该用〈维护〉。骚扰的对象是人或生活环境，维护秩序不能用骚扰。"}, {"text": "他的粗心骚扰了我们的合作。", "explanation": "这里应该用〈破坏〉。骚扰表示打扰、使人不安，不能用于合作关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "半夜的喇叭声一直骚扰了着邻居。", "corrected_sentence": "半夜的喇叭声一直骚扰着邻居。", "error_description": "“骚扰”后的动态助词用错：不能同时用“了”和“着”。应为“骚扰着”，表示持续的状态。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他骚扰了过邻居很多次。", "corrected_sentence": "他骚扰过邻居很多次。", "error_description": "动态助词重复：“过”已表示经验，前面不能再加“了”，应为“骚扰过邻居很多次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92535, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以前", "is_correct": true, "explanation": "「以前」与「今后」以说话的现在为界，分指过去与将来，是反义关系。"}, {"text": "昨天", "is_correct": false, "explanation": "「昨天」指过去的一天，只是同类时间词，不是「今后」的反义词。"}, {"text": "时候", "is_correct": false, "explanation": "「时候」泛指一段时间，与「今后」并不构成反义。"}, {"text": "清晨", "is_correct": false, "explanation": "「清晨」指一天中的一个时段，与「今后」不是反义关系。"}], "correct_answer": "以前", "explanations": {"以前": "「以前」与「今后」以说话的现在为界，分指过去与将来，是反义关系。", "昨天": "「昨天」指过去的一天，只是同类时间词，不是「今后」的反义词。", "时候": "「时候」泛指一段时间，与「今后」并不构成反义。", "清晨": "「清晨」指一天中的一个时段，与「今后」不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92535, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以前", "is_correct": true, "explanation": "「以前」与「今后」以说话的现在为界，分指过去与将来，是反义关系。"}, {"text": "星期", "is_correct": false, "explanation": "「星期」是一周的时间单位，与「今后」不构成反义。"}, {"text": "时代", "is_correct": false, "explanation": "「时代」指历史阶段，与「今后」不是反义关系。"}, {"text": "周末", "is_correct": false, "explanation": "「周末」指一周的休息日，与「今后」不是反义关系。"}], "correct_answer": "以前", "explanations": {"以前": "「以前」与「今后」以说话的现在为界，分指过去与将来，是反义关系。", "星期": "「星期」是一周的时间单位，与「今后」不构成反义。", "时代": "「时代」指历史阶段，与「今后」不是反义关系。", "周末": "「周末」指一周的休息日，与「今后」不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92535, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "今后是从今天开始，以后的日子。", "primary_collocate": null, "pronunciation": "jīn hòu", "ipa": "tɕin˥˥ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "今后的日子，我们一起努力。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今后的生活会越来越好。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说今后每天都要早起。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今后你有什么打算？", "target_word": "今后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今后的路要靠你自己走。", "target_word": "今后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师告诉我们，今后要多读书。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬到这里，今后我们就是邻居了。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今后的几年，这个城市会变得更大。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想好了今后的计划。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不知道今后会怎么样。", "target_word": "今后", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "今後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "今后：指从今天开始的以后的日子，常说今后的日子、生活、路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf42e3e0-3aa5-4213-89fd-9bc9b80dff5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92535, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "今后", "is_correct": true, "explanation": "正确：「今后」指从现在往后的时间，与「一起努力」的将来含义相合。"}, {"text": "以前", "is_correct": false, "explanation": "语义：「以前」指过去，与「一起努力」面向将来的意思相反。"}, {"text": "昨天", "is_correct": false, "explanation": "搭配：「昨天」只指一天，不能修饰「日子」这样的长时段。"}, {"text": "年代", "is_correct": false, "explanation": "搭配：「年代」指某个十年的历史时期，不能泛指「的日子」。"}], "explanations": {"今后": "正确：「今后」指从现在往后的时间，与「一起努力」的将来含义相合。", "以前": "语义：「以前」指过去，与「一起努力」面向将来的意思相反。", "昨天": "搭配：「昨天」只指一天，不能修饰「日子」这样的长时段。", "年代": "搭配：「年代」指某个十年的历史时期，不能泛指「的日子」。"}, "sentence_index": 0, "correct_answer": "今后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我吃完饭今后去散步。", "explanation": "这里应该用〈以后〉。今后从现在往后算，不能表示紧接在某个动作之后的先后，此处要用〈以后〉。"}, {"text": "今后，他去了北京工作。", "explanation": "这里应该用〈后来〉。「去了」说的是已经发生的事，而今后只指从现在往后，不能用于过去。"}, {"text": "他把碗洗好，今后马上出门。", "explanation": "这里应该用〈然后〉。今后指从现在往后，不能连接刚做完的动作；「马上」的即时义也与「今后」的长远义相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92535, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "今后", "is_correct": true, "explanation": "正确：「今后」表示从搬来之后开始的时间，与「就是邻居了」的先后关系相合。"}, {"text": "时代", "is_correct": false, "explanation": "搭配：「时代」是泛指的历史阶段，不能直接作「就是邻居」的时间状语。"}, {"text": "从前", "is_correct": false, "explanation": "语义：「从前」指往昔，与「搬到这里」之后才成为邻居的先后关系矛盾。"}, {"text": "假期", "is_correct": false, "explanation": "语义：「假期」是休假的时段，与搬家后成为邻居的情况无关。"}], "explanations": {"今后": "正确：「今后」表示从搬来之后开始的时间，与「就是邻居了」的先后关系相合。", "时代": "搭配：「时代」是泛指的历史阶段，不能直接作「就是邻居」的时间状语。", "从前": "语义：「从前」指往昔，与「搬到这里」之后才成为邻居的先后关系矛盾。", "假期": "语义：「假期」是休假的时段，与搬家后成为邻居的情况无关。"}, "sentence_index": 6, "correct_answer": "今后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今后，警察赶到了现场。", "explanation": "这里应该用〈随后〉。今后只指从现在往后，而「赶到了」说的是已经发生的事。"}, {"text": "我们先检查行李，今后马上出发。", "explanation": "这里应该用〈接着〉。今后指从现在往后，不能表示检查行李之后紧接着出发；「马上」的即时义也与「今后」矛盾。"}, {"text": "今后，他向大家道了歉。", "explanation": "这里应该用〈事后〉。「道了歉」是已经完成的事，今后指将来，不能表示事后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92535, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今后地生活，我们一起努力。", "corrected_sentence": "今后的生活，我们一起努力。", "error_description": "错误形式：「今后地生活，我们一起努力」；正确形式：「今后的生活，我们一起努力」。「今后」作定语修饰名词「生活」时须用「的」，误用「地」（「地」用于修饰动词、形容词）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92535, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今后了我每天早起。", "corrected_sentence": "今后我每天早起。", "error_description": "错误形式：「今后了我每天早起」；正确形式：「今后我每天早起」。「今后」是时间词，后面不能加「了」，应去掉「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92536, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以前", "is_correct": true, "explanation": "「以前」与「今后」以说话的现在为界，分指过去与将来，是反义关系。"}, {"text": "昨天", "is_correct": false, "explanation": "「昨天」指过去的一天，只是同类时间词，不是「今后」的反义词。"}, {"text": "时候", "is_correct": false, "explanation": "「时候」泛指一段时间，与「今后」并不构成反义。"}, {"text": "清晨", "is_correct": false, "explanation": "「清晨」指一天中的一个时段，与「今后」不是反义关系。"}], "correct_answer": "以前", "explanations": {"以前": "「以前」与「今后」以说话的现在为界，分指过去与将来，是反义关系。", "昨天": "「昨天」指过去的一天，只是同类时间词，不是「今后」的反义词。", "时候": "「时候」泛指一段时间，与「今后」并不构成反义。", "清晨": "「清晨」指一天中的一个时段，与「今后」不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92536, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以前", "is_correct": true, "explanation": "「以前」与「今后」以说话的现在为界，分指过去与将来，是反义关系。"}, {"text": "星期", "is_correct": false, "explanation": "「星期」是一周的时间单位，与「今后」不构成反义。"}, {"text": "时代", "is_correct": false, "explanation": "「时代」指历史阶段，与「今后」不是反义关系。"}, {"text": "周末", "is_correct": false, "explanation": "「周末」指一周的休息日，与「今后」不是反义关系。"}], "correct_answer": "以前", "explanations": {"以前": "「以前」与「今后」以说话的现在为界，分指过去与将来，是反义关系。", "星期": "「星期」是一周的时间单位，与「今后」不构成反义。", "时代": "「时代」指历史阶段，与「今后」不是反义关系。", "周末": "「周末」指一周的休息日，与「今后」不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92536, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从现在起往后的时间。", "primary_collocate": null, "pronunciation": "jīn hòu", "ipa": "tɕin˥˥ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "今后请大家准时上课。", "target_word": "今后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今后我一定注意身体。", "target_word": "今后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司说，今后不再发纸质通知。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今后一个月，我每天跑步。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今后他再也不迟到了。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今后有问题，请直接给我打电话。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我保证，今后不会再犯同样的错误。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今后天气会越来越冷。", "target_word": "今后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校规定今后不能带手机进教室。", "target_word": "今后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你今后想做什么工作？", "target_word": "今后", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "今後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "今后：作时间词放在句首或主语后，表示从现在起往后的时间，常引出打算、保证、规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf42e3e0-3aa5-4213-89fd-9bc9b80dff5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92536, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "今后", "is_correct": true, "explanation": "正确：「今后」指从现在起往后，与「请大家准时上课」的规定相合。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：「昨天」指已过去的一天，与「请大家准时上课」的规定不相符。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：「星期」是时间单位，不能直接作这样的时间状语。"}, {"text": "时代", "is_correct": false, "explanation": "搭配：「时代」泛指历史阶段，不能作「请大家准时上课」的时间状语。"}], "explanations": {"今后": "正确：「今后」指从现在起往后，与「请大家准时上课」的规定相合。", "昨天": "语义：「昨天」指已过去的一天，与「请大家准时上课」的规定不相符。", "星期": "搭配：「星期」是时间单位，不能直接作这样的时间状语。", "时代": "搭配：「时代」泛指历史阶段，不能作「请大家准时上课」的时间状语。"}, "sentence_index": 0, "correct_answer": "今后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我考完试今后去旅行。", "explanation": "这里应该用〈以后〉。今后从现在往后算，不能表示紧接在考试之后的先后，此处要用〈以后〉。"}, {"text": "今后，妈妈回了老家。", "explanation": "这里应该用〈后来〉。「回了老家」说的是已经发生的事，今后只指从现在往后。"}, {"text": "他洗完澡，今后马上睡觉。", "explanation": "这里应该用〈然后〉。今后指从现在往后，不能表示洗完澡之后紧接着的动作；「马上」的即时义也与「今后」的长远义相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92536, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "今后", "is_correct": true, "explanation": "正确：「今后」指从现在往后，与「保证」面向将来的语气相合。"}, {"text": "过去", "is_correct": false, "explanation": "语义：「过去」指已经发生的时间，与「保证不会再犯」的将来承诺相矛盾。"}, {"text": "时候", "is_correct": false, "explanation": "搭配：「时候」是泛指的时段，不能单独作「不会再犯」的时间状语。"}, {"text": "从前", "is_correct": false, "explanation": "语义：「从前」指往昔，与「保证」面向将来的语气不合。"}], "explanations": {"今后": "正确：「今后」指从现在往后，与「保证」面向将来的语气相合。", "过去": "语义：「过去」指已经发生的时间，与「保证不会再犯」的将来承诺相矛盾。", "时候": "搭配：「时候」是泛指的时段，不能单独作「不会再犯」的时间状语。", "从前": "语义：「从前」指往昔，与「保证」面向将来的语气不合。"}, "sentence_index": 6, "correct_answer": "今后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今后，他签了合同。", "explanation": "这里应该用〈随后〉。今后只指从现在往后，而「签了合同」是已经发生的事。"}, {"text": "他签完字，今后离开办公室。", "explanation": "这里应该用〈接着〉。今后指从现在往后，不能表示签字之后紧接着离开，此处要用〈接着〉。"}, {"text": "今后，我们总结了经验。", "explanation": "这里应该用〈事后〉。「总结了经验」是已经完成的事，今后指将来，不能表示事后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今后地工作，我会好好努力。", "corrected_sentence": "今后的工作，我会好好努力。", "error_description": "错误形式：「今后地工作，我会好好努力」；正确形式：「今后的工作，我会好好努力」。「今后」作定语修饰名词「工作」时须用「的」，误用「地」（「地」用于修饰动词、形容词）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今后了我们要多锻炼身体。", "corrected_sentence": "今后我们要多锻炼身体。", "error_description": "错误形式：「今后了我们要多锻炼身体」；正确形式：「今后我们要多锻炼身体」。「今后」是时间词，后面不能加「了」，应去掉「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
