INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92539, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "行为数据是记下人做了什么事的数字。", "primary_collocate": null, "pronunciation": "xíng wéi shù jù", "ipa": "ɕiŋ˧˥ weɪ˧˥ ʂu˥˩ tɕy˥˩", "syllable_count": 4, "sentences": [{"text": "这个软件会记下你的行为数据。", "target_word": "行为数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司每天看用户的行为数据。", "target_word": "行为数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师用行为数据了解学生的学习情况。", "target_word": "行为数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店根据行为数据，决定多放什么东西。", "target_word": "行为数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份行为数据记录了用户每天的操作。", "target_word": "行为数据", "complexity_tier": "T3", "furigana": "zhè fèn xíng wéi shù jù jì lù le yòng hù měi tiān de cāo zuò.", "sentence_source": "generated"}, {"text": "手机能记录你每天走多少步，这就是行为数据。", "target_word": "行为数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把行为数据放在电脑里。", "target_word": "行为数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他整理了一份行为数据给经理看。", "target_word": "行为数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "行为数据可以说明人们喜欢什么。", "target_word": "行为数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看完行为数据，她发现大家晚上用手机更多。", "target_word": "行为数据", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "行為數據", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词；记录人做过哪些事的数字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71448ad7-633e-46ca-9bd3-7ed98c22466a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92539, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行为数据", "is_correct": true, "explanation": "“记下”记录的是人做过什么的数字，与软件记录用户操作相符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无法被记下成数字或文字，“记下”的对象应是可以记录的信息，句子不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：软件无法记录味道这类感官体验，“记下你的”与软件的功能不符。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：天空不能被“记下”成数字或文字，“记下”不能与“天空”搭配。"}], "explanations": {"行为数据": "“记下”记录的是人做过什么的数字，与软件记录用户操作相符。", "空气": "语义：空气无法被记下成数字或文字，“记下”的对象应是可以记录的信息，句子不通。", "味道": "语义：软件无法记录味道这类感官体验，“记下你的”与软件的功能不符。", "天空": "搭配：天空不能被“记下”成数字或文字，“记下”不能与“天空”搭配。"}, "sentence_index": 0, "correct_answer": "行为数据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对朋友的行为数据很诚恳。", "explanation": "这里应该用〈态度〉。行为数据是记录下来的数字，不能像态度一样诚恳；说对人的态度诚恳要用态度。"}, {"text": "早睡早起是他的行为数据。", "explanation": "这里应该用〈习惯〉。行为数据是记录下来的数字，不是一种生活方式；说某种生活方式要用习惯。"}, {"text": "这次见面给我留下了行为数据。", "explanation": "这里应该用〈印象〉。行为数据是记录的数字，不能像印象那样留在人的心里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92539, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行为数据", "is_correct": true, "explanation": "“放在电脑里”的应是可以存入电脑的数字记录，行为数据符合。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无法放进电脑，“把……放在电脑里”的对象应是可以存放的数据或文件。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不能装进电脑，与“放在电脑里”的性质矛盾。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：“放”与“阳光”不搭配，阳光应说“晒”或“照”，不能说“放”。"}], "explanations": {"行为数据": "“放在电脑里”的应是可以存入电脑的数字记录，行为数据符合。", "空气": "语义：空气无法放进电脑，“把……放在电脑里”的对象应是可以存放的数据或文件。", "河流": "语义：河流不能装进电脑，与“放在电脑里”的性质矛盾。", "阳光": "搭配：“放”与“阳光”不搭配，阳光应说“晒”或“照”，不能说“放”。"}, "sentence_index": 6, "correct_answer": "行为数据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做了一个跳跃的行为数据，大家都笑了。", "explanation": "这里应该用〈动作〉。行为数据是记录下来的数字，不能像动作一样做出来；说做一个动作要用动作。"}, {"text": "他的行为数据很大方，见人总是先打招呼。", "explanation": "这里应该用〈举止〉。行为数据是记录下来的数字，不能有大方不大方的举止；说人的举止大方要用举止。"}, {"text": "我们从这次失败中吸取了行为数据，以后不再犯同样的错。", "explanation": "这里应该用〈教训〉。行为数据是记录下来的数字，不能像教训一样吸取；从失败中吸取的是教训。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92539, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们整理了一份行为数据唱给老师。", "corrected_sentence": "他们整理了一份行为数据发给老师。", "error_description": "用词错误：“唱”不能与“行为数据”搭配，应说“发给”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92539, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司把这只行为数据交给了经理。", "corrected_sentence": "公司把这份行为数据交给了经理。", "error_description": "量词错误：行为数据是一批记录，应说“这份”；“只”多用于单个的动物或物件，不能用来数据。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
