INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92540, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92540, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "记录用户或人群行为的数据。", "primary_collocate": null, "pronunciation": "xíng wéi shù jù", "ipa": "ɕiŋ˧˥ weɪ˧˥ ʂu˥˩ tɕy˥˩", "syllable_count": 4, "sentences": [{"text": "网站收集用户的行为数据。", "target_word": "行为数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司有很多顾客的行为数据。", "target_word": "行为数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作人员正在分析行为数据。", "target_word": "行为数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要保护好用户的行为数据，不能乱给别人。", "target_word": "行为数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "通过行为数据，公司知道哪个广告更受欢迎。", "target_word": "行为数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个应用没有保存我的行为数据。", "target_word": "行为数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "行为数据显示，年轻人常常在晚上买东西。", "target_word": "行为数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作是研究人群的行为数据。", "target_word": "行为数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用户的行为数据越多，推荐就越准。", "target_word": "行为数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理想看上个月的行为数据。", "target_word": "行为数据", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "行為數據", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词；记录用户或人群行为的数据", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71448ad7-633e-46ca-9bd3-7ed98c22466a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92540, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行为数据", "is_correct": true, "explanation": "“收集用户的”后接的是用户行为的数字记录，行为数据符合。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：网站收集的是数据，眼泪不能被网站收集成记录，句子语义不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是网站能收集的对象，“收集用户的”后应接数据或信息，句子不通。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是性格的表现，网站无法收集用户的脾气。"}], "explanations": {"行为数据": "“收集用户的”后接的是用户行为的数字记录，行为数据符合。", "眼泪": "语义：网站收集的是数据，眼泪不能被网站收集成记录，句子语义不通。", "天空": "语义：天空不是网站能收集的对象，“收集用户的”后应接数据或信息，句子不通。", "脾气": "语义：脾气是性格的表现，网站无法收集用户的脾气。"}, "sentence_index": 0, "correct_answer": "行为数据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的行为数据长得很快，已经比爸爸高了。", "explanation": "这里应该用〈身高〉。行为数据是记录下来的数字，不会生长，也不能用来比较高矮。"}, {"text": "她的行为数据很大方，见人总是微笑。", "explanation": "这里应该用〈举止〉。行为数据是记录下来的数字，不能有大方不大方的举止；说人的举止大方要用举止。"}, {"text": "她的行为数据很好听。", "explanation": "这里应该用〈声音〉。行为数据没有声音，不能用“好听”来形容，说声音好听要用声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92540, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行为数据", "is_correct": true, "explanation": "“显示”需要能呈现信息的对象，行为数据记录了人的消费习惯，符合。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：梦想不能显示人们的消费习惯，句子语义不通。"}, {"text": "笑声", "is_correct": false, "explanation": "搭配：“显示”后接的应是能呈现信息的事物，笑声不能显示购买习惯。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶无法显示年轻人在晚上买东西的规律，语义不通。"}], "explanations": {"行为数据": "“显示”需要能呈现信息的对象，行为数据记录了人的消费习惯，符合。", "梦想": "语义：梦想不能显示人们的消费习惯，句子语义不通。", "笑声": "搭配：“显示”后接的应是能呈现信息的事物，笑声不能显示购买习惯。", "树叶": "语义：树叶无法显示年轻人在晚上买东西的规律，语义不通。"}, "sentence_index": 6, "correct_answer": "行为数据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师的行为数据很文雅，学生都很尊敬她。", "explanation": "这里应该用〈风度〉。行为数据是记录下来的数字，不能有文雅的风度；说人的风度文雅要用风度。"}, {"text": "她做了一个优美的行为数据，大家都看呆了。", "explanation": "这里应该用〈动作〉。行为数据是记录下来的数字，不能像动作一样优美地做出来；说做动作要用动作。"}, {"text": "这次失败给我们留下了深刻的行为数据。", "explanation": "这里应该用〈教训〉。行为数据是记录下来的数字，不能像教训一样留下深刻的印象；失败留下的是教训。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92540, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "网站唱了一份用户行为数据。", "corrected_sentence": "网站收集了一份用户行为数据。", "error_description": "用词错误：“唱”不能与“行为数据”搭配，应说“收集”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92540, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究人员把一只行为数据送给了经理。", "corrected_sentence": "研究人员把一份行为数据送给了经理。", "error_description": "量词错误：行为数据是一批记录，应说“这份”；“只”多用于单个的动物或物件，不能用来数据。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92541, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "马虎", "is_correct": true, "explanation": "正确：“马虎”与“仔细”（做事不马虎、看得清楚）意思相反。"}, {"text": "热情", "is_correct": false, "explanation": "无关：“热情”形容待人的态度，与“仔细”不构成反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "无关：“聪明”指头脑反应快，不是“仔细”的反义词。"}, {"text": "勇敢", "is_correct": false, "explanation": "无关：“勇敢”指不怕困难和危险，与“仔细”不构成反义关系。"}], "correct_answer": "马虎", "explanations": {"马虎": "正确：“马虎”与“仔细”（做事不马虎、看得清楚）意思相反。", "热情": "无关：“热情”形容待人的态度，与“仔细”不构成反义关系。", "聪明": "无关：“聪明”指头脑反应快，不是“仔细”的反义词。", "勇敢": "无关：“勇敢”指不怕困难和危险，与“仔细”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92541, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "马虎", "is_correct": true, "explanation": "正确：“马虎”与“仔细”（做事不马虎、看得清楚）意思相反。"}, {"text": "慷慨", "is_correct": false, "explanation": "无关：“慷慨”指大方给予，与“仔细”不构成反义关系。"}, {"text": "幽默", "is_correct": false, "explanation": "无关：“幽默”形容谈吐风趣，与“仔细”不构成反义关系。"}, {"text": "坚强", "is_correct": false, "explanation": "无关：“坚强”指意志或身体有力量，与“仔细”不构成反义关系。"}], "correct_answer": "马虎", "explanations": {"马虎": "正确：“马虎”与“仔细”（做事不马虎、看得清楚）意思相反。", "慷慨": "无关：“慷慨”指大方给予，与“仔细”不构成反义关系。", "幽默": "无关：“幽默”形容谈吐风趣，与“仔细”不构成反义关系。", "坚强": "无关：“坚强”指意志或身体有力量，与“仔细”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92541, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "仔细是做事不马虎，看得很清楚。", "primary_collocate": null, "pronunciation": "zǐ xì", "ipa": "tsɿ˨˩ ɕi˥˩", "syllable_count": 2, "sentences": [{"text": "请仔细看这张图。", "target_word": "仔细", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你再仔细想想，别急着回答。", "target_word": "仔细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师仔细地听了学生的回答。", "target_word": "仔细", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "签字以前，请仔细读一读合同。", "target_word": "仔细", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他仔细看着地图，想找那条小路。", "target_word": "仔细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我仔细检查了一遍，没有发现错误。", "target_word": "仔细", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃药前要仔细看说明书。", "target_word": "仔细", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把每个字都仔细地写好。", "target_word": "仔细", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他仔细打量了我一下。", "target_word": "仔细", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请大家仔细听，我只说一遍。", "target_word": "仔细", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "仔仔细细", "label": "重叠"}, {"form": "仔細", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做事认真、看听想得清楚，用作状语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5ffa561-fbb8-426b-81b7-350f6bf5c46a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92541, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仔细", "is_correct": true, "explanation": "正确：“仔细”作状语，表示看得认真、清楚，与“看这张图”相符。"}, {"text": "大声", "is_correct": false, "explanation": "语义：“大声”说的是声音大小，看图不靠声音，句子不通。"}, {"text": "猛烈", "is_correct": false, "explanation": "搭配：“猛烈”形容风、雨、攻势等的强烈程度，不能用来修饰“看”。"}, {"text": "狂热", "is_correct": false, "explanation": "搭配：“狂热”形容对某事物极端的爱好，不能用来修饰“看”这一动作。"}], "explanations": {"仔细": "正确：“仔细”作状语，表示看得认真、清楚，与“看这张图”相符。", "大声": "语义：“大声”说的是声音大小，看图不靠声音，句子不通。", "猛烈": "搭配：“猛烈”形容风、雨、攻势等的强烈程度，不能用来修饰“看”。", "狂热": "搭配：“狂热”形容对某事物极端的爱好，不能用来修饰“看”这一动作。"}, "sentence_index": 0, "correct_answer": "仔细"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他仔细瞥了一眼窗外，什么都没看清。", "explanation": "这里应该用〈匆匆〉。仔细强调看得周密，与“什么都没看清”相矛盾；随便快速看一眼要说匆匆。"}, {"text": "他仔细签了字，看都没看合同。", "explanation": "这里应该用〈草草〉。仔细要求看清内容，与“看都没看”相矛盾；随手签字、不认真看要说草草。"}, {"text": "他仔细地打翻了牛奶。", "explanation": "这里应该用〈不小心〉。仔细形容做事周密，打翻东西是意外，要说不小心，不能用仔细修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92541, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仔细", "is_correct": true, "explanation": "正确：“仔细”作状语，表示认真、清楚地看，与“看说明书”相符。"}, {"text": "高声", "is_correct": false, "explanation": "语义：“高声”指声音大，看说明书不靠声音，与句意不符。"}, {"text": "激烈", "is_correct": false, "explanation": "搭配：“激烈”形容竞争、争论等的强烈程度，不能用来修饰“看”。"}, {"text": "豪爽", "is_correct": false, "explanation": "搭配：“豪爽”形容性格直爽、不拘小节，不能用来修饰“看”这一动作。"}], "explanations": {"仔细": "正确：“仔细”作状语，表示认真、清楚地看，与“看说明书”相符。", "高声": "语义：“高声”指声音大，看说明书不靠声音，与句意不符。", "激烈": "搭配：“激烈”形容竞争、争论等的强烈程度，不能用来修饰“看”。", "豪爽": "搭配：“豪爽”形容性格直爽、不拘小节，不能用来修饰“看”这一动作。"}, "sentence_index": 6, "correct_answer": "仔细"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他仔细地打了一个哈欠，好像很困。", "explanation": "这里应该用〈不由自主〉。仔细强调做事认真周密，打哈欠是不由自主的动作，不能用仔细修饰。"}, {"text": "孩子仔细地哭了一场。", "explanation": "这里应该用〈伤心〉。仔细形容做事周密，哭泣是情绪表现，要说伤心，不能用仔细。"}, {"text": "他仔细地跑了一圈，很快就到了终点。", "explanation": "这里应该用〈飞快〉。仔细强调做事周密，形容跑得快要说飞快，不能用仔细。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92541, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请仔细得看这份说明。", "corrected_sentence": "请仔细看这份说明。", "error_description": "助词错误：“仔细”修饰动词“看”时后面不能加“得”，应说“仔细看”，不能说“仔细得看”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92541, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "吃饭前要仔细得洗手。", "corrected_sentence": "吃饭前要仔细洗手。", "error_description": "助词错误：“仔细”修饰动词“洗手”时后面不用“得”，应说“仔细洗手”，不能说“仔细得洗手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
