INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92542, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "细心，周密，不马虎。", "primary_collocate": null, "pronunciation": "zǐ xì", "ipa": "tsɿ˨˩ ɕi˥˩", "syllable_count": 2, "sentences": [{"text": "他做事很仔细，从来不出错。", "target_word": "仔细", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李很仔细，每个数字都检查了两遍。", "target_word": "仔细", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写作业的时候要仔细一点。", "target_word": "仔细", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是个仔细的人，不会忘带东西。", "target_word": "仔细", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生检查得非常仔细。", "target_word": "仔细", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这份报告写得不够仔细，有很多错字。", "target_word": "仔细", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他工作仔细，老板很放心。", "target_word": "仔细", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈买菜很仔细，总要挑半天。", "target_word": "仔细", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟太粗心，哥哥却很仔细。", "target_word": "仔细", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他算账很仔细，一分钱也不会错。", "target_word": "仔细", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "仔仔细细", "label": "重叠"}, {"form": "仔細", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容人或工作细心周密、不马虎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5ffa561-fbb8-426b-81b7-350f6bf5c46a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92542, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仔细", "is_correct": true, "explanation": "正确：“仔细”指做事周密、不马虎，与“从来不出错”相合。"}, {"text": "粗心", "is_correct": false, "explanation": "语义：“粗心”指做事马虎，与后半句“从来不出错”相矛盾。"}, {"text": "大方", "is_correct": false, "explanation": "搭配：“大方”多用来形容人的态度或不吝啬，不能说“做事很大方”。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”表示心情难过，与做事的状态无关，句子不通。"}], "explanations": {"仔细": "正确：“仔细”指做事周密、不马虎，与“从来不出错”相合。", "粗心": "语义：“粗心”指做事马虎，与后半句“从来不出错”相矛盾。", "大方": "搭配：“大方”多用来形容人的态度或不吝啬，不能说“做事很大方”。", "悲伤": "语义：“悲伤”表示心情难过，与做事的状态无关，句子不通。"}, "sentence_index": 0, "correct_answer": "仔细"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子很仔细。", "explanation": "这里应该用〈结实〉。仔细形容人做事周密、不马虎，形容椅子牢固要说结实，不能用仔细。"}, {"text": "她仔细地哭了起来。", "explanation": "这里应该用〈伤心〉。仔细形容做事周密，不能用来形容哭这种情绪，表达难过要说伤心。"}, {"text": "他仔细地摔了一跤。", "explanation": "这里应该用〈不小心〉。仔细形容做事周密，摔跤是意外，要说不小心，不能用仔细修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92542, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仔细", "is_correct": true, "explanation": "正确：“仔细”指工作周密、认真，与“老板很放心”相符。"}, {"text": "懒散", "is_correct": false, "explanation": "语义：“懒散”指做事没精神、不认真，与“老板很放心”相矛盾。"}, {"text": "幽默", "is_correct": false, "explanation": "搭配：“幽默”形容人的谈吐或性格，不能用来说“工作幽默”。"}, {"text": "慷慨", "is_correct": false, "explanation": "搭配：“慷慨”指大方给予，多用于钱财或帮助，不能用来形容工作。"}], "explanations": {"仔细": "正确：“仔细”指工作周密、认真，与“老板很放心”相符。", "懒散": "语义：“懒散”指做事没精神、不认真，与“老板很放心”相矛盾。", "幽默": "搭配：“幽默”形容人的谈吐或性格，不能用来说“工作幽默”。", "慷慨": "搭配：“慷慨”指大方给予，多用于钱财或帮助，不能用来形容工作。"}, "sentence_index": 6, "correct_answer": "仔细"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台仪器仔细地坏了。", "explanation": "这里应该用〈突然〉。仔细形容做事周密，仪器损坏是意外，要说突然，不能用仔细修饰。"}, {"text": "他的脾气很仔细，说话总是慢慢的。", "explanation": "这里应该用〈温和〉。仔细形容做事周密，形容脾气平和要说温和，不能用仔细。"}, {"text": "他仔细地一口吃完了饭，连菜都没尝。", "explanation": "这里应该用〈狼吞虎咽〉。仔细形容做事周密，形容吃得很快要说狼吞虎咽，不能用仔细。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是个仔细地人，很少出错。", "corrected_sentence": "她是个仔细的人，很少出错。", "error_description": "助词错误：“仔细”修饰名词“人”时要用“的”，“地”只修饰动词，应说“她是个仔细的人”，不能说“她是个仔细地人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他仔细得算账，一分钱也不会错。", "corrected_sentence": "他仔细地算账，一分钱也不会错。", "error_description": "助词错误：“仔细”修饰动词“算账”时要用“地”，“得”用于引出补语，不修饰动词，应说“他仔细地算账”，不能说“他仔细得算账”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
