INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92543, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92543, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "故事里能让不可能的事发生的本事。", "primary_collocate": null, "pronunciation": "mó fǎ", "ipa": "mwo˧˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "在这个故事里，魔法能让死去的人活过来。", "target_word": "魔法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男孩有魔法，所以能在天上飞。", "target_word": "魔法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的小女孩靠魔法找到了回家的路。", "target_word": "魔法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有魔法，他飞不过那座高山。", "target_word": "魔法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家的人都会魔法，可是我们不会。", "target_word": "魔法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的魔法很强，连时间都能停下来。", "target_word": "魔法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里，魔法让穷孩子一夜之间变富了。", "target_word": "魔法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王很怕魔法，因为它太危险了。", "target_word": "魔法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，故事里的魔法不是真的。", "target_word": "魔法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想学魔法，这样就能让雨停下来。", "target_word": "魔法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "魔法师", "label": "复合"}, {"form": "魔法棒", "label": "复合"}, {"form": "一种魔法", "label": "量词"}], "register": "中性", "sense_fingerprint": "故事里人物拥有的、能让不可能的事发生的本事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e461a86-2103-4f36-87ea-09eaf67ac906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92543, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "魔法", "is_correct": true, "explanation": "正确：魔法指故事里能让不可能的事发生的本事，句中能让死去的人活过来。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能作让死去的人活过来的主语。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能让死去的人活过来。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子只能照出影像，不能让死人复活。"}], "explanations": {"魔法": "正确：魔法指故事里能让不可能的事发生的本事，句中能让死去的人活过来。", "颜色": "搭配：“颜色”不能作让死去的人活过来的主语。", "桌子": "语义：桌子不能让死去的人活过来。", "镜子": "语义：镜子只能照出影像，不能让死人复活。"}, "sentence_index": 0, "correct_answer": "魔法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那只魔法跑得很快，一下就不见了。", "explanation": "这里应该用〈野兽〉。魔法指故事里的超自然力量，跑得很快的动物要说〈野兽〉。"}, {"text": "他很快就把魔法转得六面都是同一种颜色，朋友们都很佩服。", "explanation": "这里应该用〈魔方〉。魔法指故事里的超自然力量，把六面玩具转到六面同色要说〈魔方〉。"}, {"text": "班里的魔法很严，老师要求每天背诵。", "explanation": "这里应该用〈纪律〉。魔法指故事里的超自然力量，班级里的规矩要说〈纪律〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92543, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "魔法", "is_correct": true, "explanation": "正确：魔法指故事里能让不可能的事发生的本事，句中让穷孩子一夜之间变富。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典是工具书，不能让人一夜之间变富。"}, {"text": "扫帚", "is_correct": false, "explanation": "语义：扫帚是打扫用的工具，与“变富”无关。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：说“让……变富”的主语要是力量或机会，“雨伞”不能这样搭配。"}], "explanations": {"魔法": "正确：魔法指故事里能让不可能的事发生的本事，句中让穷孩子一夜之间变富。", "字典": "语义：字典是工具书，不能让人一夜之间变富。", "扫帚": "语义：扫帚是打扫用的工具，与“变富”无关。", "雨伞": "搭配：说“让……变富”的主语要是力量或机会，“雨伞”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "魔法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把魔法调到了三台，屏幕却一直黑着。", "explanation": "这里应该用〈频道〉。魔法指故事里的超自然力量，电视上切换的节目通道要说〈频道〉。"}, {"text": "他出门忘了带魔法，结果被雨淋湿了。", "explanation": "这里应该用〈雨伞〉。魔法指故事里的超自然力量，下雨时要带的遮雨工具要说〈雨伞〉。"}, {"text": "妈妈去买了一种魔法，吃下去就退烧了。", "explanation": "这里应该用〈退烧药〉。魔法指故事里的超自然力量，吃了能退烧的药要说〈退烧药〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92543, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人用一根魔法把旧房子变成了花园。", "corrected_sentence": "老人用一种魔法把旧房子变成了花园。", "error_description": "量词错误：“魔法”应用量词“种”，不能用“根”（“根”用于细长的东西）。改为：一种魔法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92543, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他花了三年才学会一只魔法。", "corrected_sentence": "他花了三年才学会一种魔法。", "error_description": "量词错误：“魔法”应用量词“种”，不能用“只”（“只”用于动物等）。改为：一种魔法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
