INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92544, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "神话和故事中能变出奇异事物的法术。", "primary_collocate": null, "pronunciation": "mó fǎ", "ipa": "mwo˧˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "巫师用魔法把南瓜变成了马车。", "target_word": "魔法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老巫师念着咒语，施展了魔法。", "target_word": "魔法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的魔法能让石头变成金子。", "target_word": "魔法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩学会了一种魔法，能变出蛋糕。", "target_word": "魔法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巫师不用钥匙，用魔法打开了门。", "target_word": "魔法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个童话里有很多神奇的魔法。", "target_word": "魔法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看过一个故事，主人公会用魔法变出食物。", "target_word": "魔法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巫婆用魔法把王子变成了青蛙。", "target_word": "魔法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在电影里，魔法能让扫帚飞起来。", "target_word": "魔法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们最爱听魔法变出糖果的故事。", "target_word": "魔法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "魔法师", "label": "复合"}, {"form": "魔法棒", "label": "复合"}, {"form": "一种魔法", "label": "量词"}], "register": "中性", "sense_fingerprint": "神话故事中靠咒语变出奇异事物的法术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e461a86-2103-4f36-87ea-09eaf67ac906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92544, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "魔法", "is_correct": true, "explanation": "正确：魔法指故事里能变出奇异事物的法术，句中用它把南瓜变成马车。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙只能开锁，不能把南瓜变成马车。"}, {"text": "颜料", "is_correct": false, "explanation": "搭配：颜料可以涂色，但不能说“用颜料把南瓜变成马车”。"}, {"text": "剪刀", "is_correct": false, "explanation": "语义：剪刀只能剪东西，无法让南瓜变成马车。"}], "explanations": {"魔法": "正确：魔法指故事里能变出奇异事物的法术，句中用它把南瓜变成马车。", "钥匙": "语义：钥匙只能开锁，不能把南瓜变成马车。", "颜料": "搭配：颜料可以涂色，但不能说“用颜料把南瓜变成马车”。", "剪刀": "语义：剪刀只能剪东西，无法让南瓜变成马车。"}, "sentence_index": 0, "correct_answer": "魔法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家的魔法很严，人人都要遵守。", "explanation": "这里应该用〈法律〉。魔法指故事里的超自然力量，国家规定人们遵守的要说〈法律〉。"}, {"text": "那个魔法很凶，见了人就咬。", "explanation": "这里应该用〈魔鬼〉。魔法指故事里的超自然力量，凶恶会咬人的怪物要说〈魔鬼〉。"}, {"text": "他花了十分钟，终于把魔法拼好了。", "explanation": "这里应该用〈魔方〉。魔法指故事里的超自然力量，拼六面颜色的玩具要说〈魔方〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92544, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "魔法", "is_correct": true, "explanation": "正确：魔法指故事里能变出东西的法术，句中主人公用它变出食物。"}, {"text": "图片", "is_correct": false, "explanation": "语义：图片是画面，不能变出食物。"}, {"text": "纸张", "is_correct": false, "explanation": "语义：纸张是材料，本身无法变出食物。"}, {"text": "清单", "is_correct": false, "explanation": "搭配：“清单”不能用来“变出”东西，搭配不当。"}], "explanations": {"魔法": "正确：魔法指故事里能变出东西的法术，句中主人公用它变出食物。", "图片": "语义：图片是画面，不能变出食物。", "纸张": "语义：纸张是材料，本身无法变出食物。", "清单": "搭配：“清单”不能用来“变出”东西，搭配不当。"}, "sentence_index": 6, "correct_answer": "魔法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "科学家用魔法证明了这个理论。", "explanation": "这里应该用〈实验〉。魔法是故事里的超自然力量，证明理论要靠实验。"}, {"text": "这台电脑的魔法卡住了，怎么也打不开。", "explanation": "这里应该用〈程序〉。魔法指故事里的超自然力量，电脑卡住的运行程序要说〈程序〉。"}, {"text": "这个孩子生病了，医生给他打了一针魔法。", "explanation": "这里应该用〈疫苗〉。魔法指故事里的超自然力量，预防疾病要打的针剂是〈疫苗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92544, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位老爷爷有一根魔法，能让花开得很快。", "corrected_sentence": "那位老爷爷有一种魔法，能让花开得很快。", "error_description": "量词错误：“魔法”应用量词“种”，不能用“根”（“根”用于细长的东西）。改为：一种魔法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92544, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他学过一只魔法，所以能变出一只小鸟。", "corrected_sentence": "他学过一种魔法，所以能变出一只小鸟。", "error_description": "量词错误：“魔法”应用量词“种”，不能用“只”（“只”用于动物等）。改为：一种魔法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a304d357-2cb6-4a8f-b6c8-cfdc8b5a4034') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
