INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92549, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "故事里很漂亮的一种大鸟。", "primary_collocate": null, "pronunciation": "fèng huáng", "ipa": "fɤŋ˥˩ xuɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "故事里有一只很大的凤凰。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凤凰飞到了山上。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里的凤凰非常漂亮。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子画了一只红色的凤凰。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我讲了凤凰的故事。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凤凰的尾巴又长又漂亮。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动画片里，凤凰扇着翅膀在天上飞。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在墙上看到了一只凤凰。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只凤凰是金色的，眼睛很亮。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你见过真的凤凰吗？", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一只凤凰", "label": "量词"}], "register": "中性", "sense_fingerprint": "故事、图画里出现的漂亮大鸟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e81304c3-911e-48ff-b4ba-3e9273962e3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92549, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凤凰", "is_correct": true, "explanation": "凤凰：故事里很漂亮的一种大鸟。句中“一只很大的”正指这种大鸟。"}, {"text": "椅子", "is_correct": false, "explanation": "量词：“一只”用于动物，椅子应说“一把”，“一只很大的椅子”不成立。"}, {"text": "电视", "is_correct": false, "explanation": "量词：电视应说“一台”，不能说“一只”。"}, {"text": "桌子", "is_correct": false, "explanation": "量词：“只”不能计量桌子，桌子应说“一张”。"}], "explanations": {"凤凰": "凤凰：故事里很漂亮的一种大鸟。句中“一只很大的”正指这种大鸟。", "椅子": "量词：“一只”用于动物，椅子应说“一把”，“一只很大的椅子”不成立。", "电视": "量词：电视应说“一台”，不能说“一只”。", "桌子": "量词：“只”不能计量桌子，桌子应说“一张”。"}, "sentence_index": 0, "correct_answer": "凤凰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在动物园看到一本凤凰。", "explanation": "这里应该用〈只〉。凤凰是鸟，计量鸟类用“只”，“本”用于书籍。"}, {"text": "我的凤凰每天骑自行车上学。", "explanation": "这里应该用〈同学〉。凤凰是鸟，不能骑自行车上学，指人应说同学。"}, {"text": "我在博物馆见过一匹凤凰。", "explanation": "这里应该用〈只〉。凤凰是鸟，计量鸟类用只，匹用于马等牲口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92549, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凤凰", "is_correct": true, "explanation": "凤凰：故事里很漂亮的一种大鸟。动画片里能在天上飞的正是它。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有翅膀，不会扇着翅膀在天上飞，句意不通。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师不会扇着翅膀在天上飞，句意不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“在天上飞”的主语多为鸟、飞机等会飞的事物，雨伞一般不说在天上飞。"}], "explanations": {"凤凰": "凤凰：故事里很漂亮的一种大鸟。动画片里能在天上飞的正是它。", "石头": "语义：石头没有翅膀，不会扇着翅膀在天上飞，句意不通。", "老师": "语义：老师不会扇着翅膀在天上飞，句意不通。", "雨伞": "搭配：“在天上飞”的主语多为鸟、飞机等会飞的事物，雨伞一般不说在天上飞。"}, "sentence_index": 6, "correct_answer": "凤凰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在市场上买了一棵凤凰。", "explanation": "这里应该用〈只〉。凤凰是鸟，计量鸟类用“只”，“棵”用于树木。"}, {"text": "他在笼子里养了三头凤凰。", "explanation": "这里应该用〈只〉。凤凰是鸟，计量鸟类用“只”，“头”多用于牛、猪等大型牲畜。"}, {"text": "他在桌上放了一颗凤凰。", "explanation": "这里应该用〈只〉。凤凰是鸟，计量鸟类用“只”，“颗”用于粒状或球形的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92549, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师讲的故事里有一个金色的凤凰。", "corrected_sentence": "老师讲的故事里有一只金色的凤凰。", "error_description": "量词错误：“凤凰”是鸟，应用量词“只”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92549, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在博物馆见过过一只铜做的凤凰。", "corrected_sentence": "我在博物馆见过一只铜做的凤凰。", "error_description": "重复用“过”：“见过”已含经验态，不能再加一个“过”，应为“见过一只铜做的凤凰”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7cc546-f8a1-46d5-bf76-f998f3690352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
