INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92550, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "传说中的百鸟之王，羽毛华丽。", "primary_collocate": null, "pronunciation": "fèng huáng", "ipa": "fɤŋ˥˩ xuɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "传说凤凰是百鸟之王。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凤凰的羽毛五颜六色，非常华丽。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人认为凤凰出现，是好事。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的衣服上绣着一只凤凰。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国，凤凰是美好的象征。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传说中，凤凰一飞，百鸟都跟着它。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她头上戴着凤凰形状的饰品。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凤凰和龙常常一起出现在婚礼上。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传说凤凰在火里重生。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇后的衣服上常常有凤凰。", "target_word": "凤凰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一只凤凰", "label": "量词"}, {"form": "鳳凰", "label": "繁体"}], "register": "书面", "sense_fingerprint": "传说中的百鸟之王，象征吉祥与美好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e81304c3-911e-48ff-b4ba-3e9273962e3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
